INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lakin-afolabi-law-london','Lakin Afolabi Law','London','ON','southwestern',0,4.9,239,42.98869,-81.2348181,'{"name":"Lakin Afolabi Law","city":"London","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"southwestern","province":"ON","lat":42.98869,"lng":-81.2348181,"address":"433 William St, London, ON N6B 3N6","phone":"+15196456969","rating":4.9,"count":239,"slug":"lakin-afolabi-law-london","mapsUrl":"https://www.google.com/maps/search/Lakin+Afolabi+Law+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=433+William+St%2C+London%2C+ON+N6B+3N6","website":"https://www.lakinafolabilaw.com","blurb":"Criminal Defence in London. Rated 4.9 from 239 Google reviews.","type":"logo","src":"images/logos/lakin-afolabi-law-london.jpg","details":{"lawyers":[{"name":"Lakin Afolabi"}],"areas":["Criminal defence","Sexual assault defence","Quasi-criminal law"],"serving":["London","Kitchener"]}}',NULL,'Lakin Afolabi Law is a London, Ontario criminal defence firm that focuses on sexual assault and domestic assault charges.

