INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('michael-juskey-toronto','Michael Juskey','Toronto','ON','toronto',0,4.9,200,43.6475556,-79.3962148,'{"name":"Michael Juskey","city":"Toronto","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"toronto","province":"ON","lat":43.6475556,"lng":-79.3962148,"address":"130 Spadina Ave. #606, Toronto, ON M5V 2L4","phone":"+14164282760","rating":4.9,"count":200,"slug":"michael-juskey-toronto","mapsUrl":"https://www.google.com/maps/search/Michael+Juskey+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=130+Spadina+Ave.+%23606%2C+Toronto%2C+ON+M5V+2L4","website":"https://mpjlaw.ca","blurb":"Criminal Defence / Civil Litigation in Toronto. Rated 4.9 from 200 Google reviews.","type":"logo","src":"images/logos/michael-juskey-toronto.png","bioImage":"images/bio/michael-juskey-toronto.webp","details":{"lawyers":[{"name":"Michael Juskey"}],"areas":["Assault","Domestic assault","Criminal defence"],"serving":["Toronto","Newmarket","Brampton","Southern Ontario"]}}',NULL,'Michael Juskey is a Toronto criminal defence lawyer representing clients charged with assault, theft, fraud, young offender and driving offences.

The practice acts in Toronto, Newmarket, Brampton and throughout Southern Ontario, appearing in the Ontario Court of Justice and the Superior Court of Justice. Born and raised in Toronto, Michael studied political science at the University of Western Ontario and earned his LL.B. at the University of Leicester with first class honours. He interned with a community Legal Aid clinic and continues to provide legal aid services. Domestic assault, sexual assault, mischief and weapons offences are among the firm''s focus areas.','dynamic','live',NULL);
