INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('jeffrey-i-reisman-north-york','Jeffrey I. Reisman','North York','ON','toronto',0,4.9,115,43.7617106,-79.3477529,'{"name":"Jeffrey I. Reisman","city":"North York","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"toronto","province":"ON","lat":43.7617106,"lng":-79.3477529,"address":"220 Duncan Mill Rd #419, North York, ON M3B 3J5","phone":"+16473514357","rating":4.9,"count":115,"slug":"jeffrey-i-reisman-north-york","mapsUrl":"https://www.google.com/maps/search/Jeffrey+I.+Reisman+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=220+Duncan+Mill+Rd+%23419%2C+North+York%2C+ON+M3B+3J5","website":"https://www.jeffreismanlaw.ca","blurb":"Criminal Defence in North York. Rated 4.9 from 115 Google reviews.","type":"logo","src":"images/logos/jeffrey-i-reisman-north-york.png","details":{"lawyers":[{"name":"Jeffrey I. Reisman"}],"areas":["Criminal defence","Bail hearings","Probation violations","Drug charges","Property offenses","Domestic assault","Sexual assault","Impaired driving","Weapons & firearms","Murder"],"serving":["Toronto","Brampton","Collingwood","Newmarket","Oshawa","Scarborough","GTA"]}}','{"1":[["00:00","23:59"]],"2":[["00:00","23:59"]],"3":[["00:00","23:59"]],"4":[["00:00","23:59"]],"5":[["00:00","23:59"]],"6":[["00:00","23:59"]],"7":[["00:00","23:59"]]}','Jeffrey Reisman is a criminal defence lawyer in North York serving Toronto and the GTA on bail hearings, impaired driving, assault and drug charges.

