INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kainth-law-group-kitchener','Kainth Law Group','Kitchener','ON','waterloo-guelph',0,4.9,109,43.45327,-80.51747,'{"name":"Kainth Law Group","city":"Kitchener","featured":false,"tags":["Criminal Defence","Wills & Estates","Family Law","Real Estate"],"caseTypes":["criminal","wills","family","realestate"],"region":"waterloo-guelph","province":"ON","lat":43.45327,"lng":-80.51747,"address":"690 Belmont Ave W #303, Kitchener, ON N2M 1N6","phone":"+12262406640","rating":4.9,"count":109,"slug":"kainth-law-group-kitchener","mapsUrl":"https://www.google.com/maps/search/Kainth+Law+Group+Kitchener+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=690+Belmont+Ave+W+%23303%2C+Kitchener%2C+ON+N2M+1N6","website":"https://www.klawgp.com","blurb":"Criminal Defence / Wills & Estates in Kitchener. Rated 4.9 from 109 Google reviews.","type":"logo","src":"images/logos/kainth-law-group-kitchener.webp","details":{"areas":["Powers of attorney for Indian property"]}}',NULL,'Kainth Law Group in Kitchener covers family, criminal, real estate, estate and business law, plus civil litigation and notary services.

Family law services cover divorce, separation and child custody, criminal defence is for people facing charges, and real estate law is a further area. Estate planning and powers of attorney are separate services, and the firm also handles civil litigation and employment law. A notary public administers oaths and affirmations, takes affidavits and witnesses signatures to deter fraud. The firm is a general practice serving Kitchener clients across several areas of law.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('infinity-law-victoria','Infinity Law','Victoria','BC','bc-victoria',0,4.6,116,48.4237799,-123.3586065,'{"name":"Infinity Law","city":"Victoria","featured":false,"tags":[],"caseTypes":[],"region":"bc-victoria","province":"BC","lat":48.4237799,"lng":-123.3586065,"address":"931 Fort St #200, Victoria, BC V8V 3K3","phone":"+12503856004","rating":4.6,"count":116,"slug":"infinity-law-victoria","mapsUrl":"https://www.google.com/maps/search/Infinity+Law+Victoria+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=931+Fort+St+%23200%2C+Victoria%2C+BC+V8V+3K3","website":"https://www.infinity-law.com","blurb":"Law firm in Victoria. Rated 4.6 from 116 Google reviews.","type":"logo","src":"images/logos/infinity-law-victoria.png","details":{"areas":["Commercial litigation","Civil litigation","Corporate law","Criminal law","Wills & estates","Real estate law","Immigration law","Alternative dispute resolution","Family law"],"serving":["Victoria","Mill Bay","Nanaimo","Vancouver Island","Vancouver"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Infinity Law is a Victoria, BC firm offering real estate, corporate, family, estate and immigration services on Vancouver Island.

The firm was founded in 2013 through the union of two Victoria law firms. It has two Victoria offices, Broadmead and Downtown, plus offices in Mill Bay, Nanaimo and Vancouver. Its service area covers Sidney, Sooke, Esquimalt, Oak Bay, Saanich, Langford, Colwood and Metchosin, and its work extends across Vancouver Island. Practice areas also include estate planning and administration, commercial litigation and immigration services in Victoria and Nanaimo.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('macdonald-zhivov-calgary','MacDonald Zhivov','Calgary','AB','ab-calgary',0,4.8,109,50.9850897,-114.0490467,'{"name":"MacDonald Zhivov","city":"Calgary","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"ab-calgary","province":"AB","lat":50.9850897,"lng":-114.0490467,"address":"7710 5 St SE Ste 108, Calgary, AB T2H 2L9","phone":"+14037704939","rating":4.8,"count":109,"slug":"macdonald-zhivov-calgary","mapsUrl":"https://www.google.com/maps/search/MacDonald+Zhivov+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7710+5+St+SE+Ste+108%2C+Calgary%2C+AB+T2H+2L9","website":"https://macz.ca","blurb":"Personal Injury in Calgary. Rated 4.8 from 109 Google reviews.","type":"logo","src":"images/logos/macdonald-zhivov-calgary.webp","details":{"areas":["Injury law","Immigration law","Family law","Wills & estates","Notary services","Car accident law","Motor vehicle accidents","Premises liability","Wrongful death claims"],"serving":["Calgary","Alberta"]}}',NULL,'MacDonald Zhivov is a Calgary firm that focuses on personal injury, including car accidents and slip and falls, alongside immigration, family and estate work.

The firm began in Calgary supporting people hurt in accidents and has served clients across Alberta. Its practice areas include injury law, immigration law, family law, wills and estates, and notary services. Multilingual services and personalized client care are emphasized. The firm has brought thousands of cases to resolution, and its history is one of advocacy centred on injured Albertans.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('gray-criminal-defence-toronto','Gray Criminal Defence','Toronto','ON','toronto',0,5,103,43.6484203,-79.373554,'{"name":"Gray Criminal Defence","city":"Toronto","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"toronto","province":"ON","lat":43.6484203,"lng":-79.373554,"address":"65 Front St E 3rd floor, Toronto, ON M5E 1B5","phone":"+14168268610","rating":5,"count":103,"slug":"gray-criminal-defence-toronto","mapsUrl":"https://www.google.com/maps/search/Gray+Criminal+Defence+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=65+Front+St+E+3rd+floor%2C+Toronto%2C+ON+M5E+1B5","website":"https://georgegray.ca","blurb":"Criminal Defence in Toronto. Rated 5.0 from 103 Google reviews.","type":"logo","src":"images/logos/gray-criminal-defence-toronto.png","details":{"lawyers":[{"name":"George Gray","title":"Founder and principal"}],"areas":["Criminal defence","Impaired driving","Assault","Sexual offences","Drug charges"],"serving":["Toronto","GTA","Hamilton","London","Barrie","Kingston"]}}',NULL,'Gray Criminal Defence, also known as Gray Defence, is a Toronto practice led by founder George Gray that defends people charged with criminal offences.

George Gray was admitted to the Ontario bar in 2009 and has spent more than fifteen years defending the accused, first as a criminal litigator at a national firm. He has appeared at all levels of court in Ontario and prepared written advocacy for the Supreme Court of Canada. The firm takes an evidence-based approach, and Chetanaya Gupta and Kinza Siddiqui are on its team. Its service area includes Brampton, Newmarket, Milton, Hamilton and Brantford, and its commentary covers disclosure delays and searches of devices at the border.','dynamic','live',NULL);
