INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('neinstein-personal-injury-lawyers-toronto','Neinstein Personal Injury Lawyers','Toronto','ON','toronto',0,4.8,592,43.6699987,-79.3898475,'{"name":"Neinstein Personal Injury Lawyers","city":"Toronto","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"toronto","province":"ON","lat":43.6699987,"lng":-79.3898475,"address":"1200 Bay St. Suite 700, Toronto, ON M5R 2A5","phone":"+14169204242","rating":4.8,"count":592,"slug":"neinstein-personal-injury-lawyers-toronto","mapsUrl":"https://www.google.com/maps/search/Neinstein+Personal+Injury+Lawyers+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1200+Bay+St.+Suite+700%2C+Toronto%2C+ON+M5R+2A5","website":"https://www.neinstein.com","blurb":"Personal Injury in Toronto. Rated 4.8 from 592 Google reviews.","type":"logo","src":"images/logos/neinstein-personal-injury-lawyers-toronto.png"}',NULL,'Neinstein Personal Injury Lawyers is a Toronto firm that represents seriously and catastrophically injured people across Ontario.

Its lawyers have practised personal injury law in Ontario since 1970, a span of more than 55 years. Matters include serious car accidents, motorcycle accidents, long-term disability insurance disputes and slip and fall injuries. The firm has argued complex trials in courts across the country and negotiated multi-million dollar settlements, and it works with clients on a contingency basis. Areas served are Toronto, Ontario and Canada.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('green-and-spiegel-llp-toronto','Green and Spiegel LLP','Toronto','ON','toronto',0,4.8,1213,43.649616,-79.384656,'{"name":"Green and Spiegel LLP","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.649616,"lng":-79.384656,"address":"150 York St 5th floor, Toronto, ON M5H 3S5","phone":"+14168627880","rating":4.8,"count":1213,"slug":"green-and-spiegel-llp-toronto","mapsUrl":"https://www.google.com/maps/search/Green+and+Spiegel+LLP+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=150+York+St+5th+floor%2C+Toronto%2C+ON+M5H+3S5","website":"https://www.gands.com","blurb":"Immigration in Toronto. Rated 4.8 from 1213 Google reviews.","type":"logo","src":"images/logos/green-and-spiegel-llp-toronto.png","details":{"founded":1962,"lawyers":[{"name":"Stephen W. Green"},{"name":"Jonathan A. Grode"},{"name":"Evan J. Green"},{"name":"Dana Imperia"},{"name":"Dan H. Berger"},{"name":"Shoshana T. Green"},{"name":"Emily M. Cohen"},{"name":"Alexandra Cole"},{"name":"Kerry E. Doyle"},{"name":"Cristina Guida"},{"name":"Brian J. Halliday"},{"name":"Katelyn Hufe Karahan"}],"areas":["Canadian immigration","U.S. immigration","Corporate immigration","Individual immigration"],"serving":["Toronto","Philadelphia","Providence","Boston","Cleveland","Orlando","Vail","Amsterdam"]}}',NULL,'Green and Spiegel LLP is a Toronto immigration firm practising Canadian and U.S. immigration law for corporations and individuals.

Mendel Green established the firm in 1962, and it has practised only immigration law since. It moved into the U.S. market in the 1990s and established Green & Spiegel U.S. in 2012. Its head offices are in Toronto and Philadelphia. Services are organized into corporate immigration, covering global mobility and compliance for businesses, and individual immigration, with separate Canadian and U.S. practices.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('unified-immigration-lawyers-toronto','Unified Immigration Lawyers','Toronto','ON','toronto',0,4.8,809,43.6503578,-79.3967078,'{"name":"Unified Immigration Lawyers","city":"Toronto","featured":false,"tags":["Immigration","Civil Litigation"],"caseTypes":["immigration","litigation"],"region":"toronto","province":"ON","lat":43.6503578,"lng":-79.3967078,"address":"197 Spadina Ave. Ste 400, Toronto, ON M5T 2C8","phone":"+14375251293","rating":4.8,"count":809,"slug":"unified-immigration-lawyers-toronto","mapsUrl":"https://www.google.com/maps/search/Unified+Immigration+Lawyers+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=197+Spadina+Ave.+Ste+400%2C+Toronto%2C+ON+M5T+2C8","website":"https://uilawyers.com","blurb":"Immigration / Civil Litigation in Toronto. Rated 4.8 from 809 Google reviews.","type":"logo","src":"images/logos/unified-immigration-lawyers-toronto.webp","details":{"founded":2017,"lawyers":[{"name":"Sonia Akilov"},{"name":"Natalie Domazet","title":"Partner"},{"name":"Gina You","title":"Partner"},{"name":"Rylee Raeburn-Gibson","title":"Senior Immigration Lawyer"},{"name":"Dania Bajwa","title":"Immigration Lawyer"}],"areas":["Canadian and U.S. immigration","Federal Court litigation","Immigration appeals","Sponsorships","Economic immigration","Temporary status matters"],"serving":["Toronto"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Unified Immigration Lawyers is a Toronto firm handling Canadian and American immigration applications, appeals and sponsorships.

The firm was formerly known as Matkowsky Immigration Law and was founded in 2017. It acts for individuals, families and corporations, with work ranging from Federal Court appeals and spousal sponsorship to executive work visas. Clients deal directly with lawyers rather than consultants or paralegals, and the firm works on flat fees. Sonia Akilov is associated with the firm, and a step-by-step process takes each file from first meeting to filing.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('axess-law-toronto','Axess Law','Toronto','ON','toronto',0,4.8,2534,43.6899033,-79.3929527,'{"name":"Axess Law","city":"Toronto","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"toronto","province":"ON","lat":43.6899033,"lng":-79.3929527,"address":"43 Alvin Ave, Toronto, ON M4T 2A7","phone":"+18444705020","rating":4.8,"count":2534,"slug":"axess-law-toronto","mapsUrl":"https://www.google.com/maps/search/Axess+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=43+Alvin+Ave%2C+Toronto%2C+ON+M4T+2A7","website":"https://www.axesslaw.com","blurb":"Wills & Estates in Toronto. Rated 4.8 from 2534 Google reviews.","type":"logo","src":"images/logos/axess-law-toronto.png","details":{"areas":["Home closings"],"serving":["Ontario","Alberta","British Columbia"]}}',NULL,'Axess Law is a Toronto firm that handles home closings online or at the client''s home, and also advises small businesses on incorporation and registration.

The firm has focused for over a decade on virtual real estate closings, with a short onboarding process, video signing meetings, in-home signing and status updates. It also handles closings for Quebec properties. Its business law work covers business names, registration, incorporation and partnerships for small businesses and start-ups, through virtual or in-person appointments in Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('randy-ai-law-office-toronto','Randy Ai Law Office','Toronto','ON','toronto',0,4.8,558,43.6546403,-79.3790879,'{"name":"Randy Ai Law Office","city":"Toronto","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"toronto","province":"ON","lat":43.6546403,"lng":-79.3790879,"address":"210 Victoria St #4311, Toronto, ON M5B 2R3","phone":"+18662910998","rating":4.8,"count":558,"slug":"randy-ai-law-office-toronto","mapsUrl":"https://www.google.com/maps/search/Randy+Ai+Law+Office+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=210+Victoria+St+%234311%2C+Toronto%2C+ON+M5B+2R3","website":"https://www.employmentlawyer-toronto.com","blurb":"Employment Law in Toronto. Rated 4.8 from 558 Google reviews.","type":"logo","src":"images/logos/randy-ai-law-office-toronto.jpg","details":{"areas":["Employment law","Severance packages","Wrongful dismissal","Employment contracts","Workplace harassment","Human rights","Disability claims","Union issues"],"serving":["Toronto","Ontario"]}}','{"1":[["06:00","22:30"]],"2":[["06:00","22:30"]],"3":[["06:00","22:30"]],"4":[["06:00","22:30"]],"5":[["06:00","22:30"]],"6":[["06:00","22:30"]],"7":[["06:00","22:30"]]}','Randy Ai Law Office is a Toronto employment law practice handling severance, wrongful dismissal and workplace harassment matters.

The firm was founded in 2014 by Randy Ai and acts for both employees and employers across Ontario. Its areas include labour law, human rights, disability law, employment litigation and class actions, and it works under the Employment Standards Act, the Canada Labour Code and the Ontario Human Rights Code. The firm has represented more than 10,000 clients and offers evening and weekend appointments. Randy Ai appears on CTV News and writes for the Globe and Mail.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('unified-llp-toronto','Unified LLP','Toronto','ON','toronto',0,4.8,317,43.6503576,-79.3967077,'{"name":"Unified LLP","city":"Toronto","featured":false,"tags":["Real Estate","Employment Law"],"caseTypes":["realestate","employment"],"region":"toronto","province":"ON","lat":43.6503576,"lng":-79.3967077,"address":"197 Spadina Ave. 4th Floor, Toronto, ON M5T 2C8","phone":"+14167877678","rating":4.8,"count":317,"slug":"unified-llp-toronto","mapsUrl":"https://www.google.com/maps/search/Unified+LLP+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=197+Spadina+Ave.+4th+Floor%2C+Toronto%2C+ON+M5T+2C8","website":"https://www.unifiedllp.com","blurb":"Real Estate / Employment Law in Toronto. Rated 4.8 from 317 Google reviews.","type":"logo","src":"images/logos/unified-llp-toronto.webp","details":{"lawyers":[{"name":"José Bento Rodrigues"},{"name":"Gil Fischler"},{"name":"Christopher Kim"},{"name":"Michael Paiva"}],"areas":["Employment law","Family law","Property and commerce law","Disability law","Labour law","Divorce law","Child custody","Spousal support","Commercial litigation"],"serving":["Toronto"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Unified LLP is a Toronto firm handling long-term disability, family, real estate, labour and employment matters for clients across Ontario.

The firm has offices in Toronto and also serves the GTA and Kitchener. On the labour side it acts for unions, not individual grievors, in grievance arbitration, tribunals, professional regulators and courts. Its family group handles uncontested and contested divorces, separation agreements, support and parenting, with flat-fee options for straightforward matters. For disability cases, it helps people whose short-term or long-term benefits are denied, delayed or cut off, and some matters proceed on a contingency fee basis.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ylaw-vancouver','YLaw','Vancouver','BC','bc-vancouver',0,4.8,337,49.2752185,-123.1208857,'{"name":"YLaw","city":"Vancouver","featured":false,"tags":["Family Law","Civil Litigation","Employment Law","Immigration"],"caseTypes":["family","litigation","employment","immigration"],"region":"bc-vancouver","province":"BC","lat":49.2752185,"lng":-123.1208857,"address":"1122 Mainland St #580, Vancouver, BC V6B 5L1","phone":"+16049749529","rating":4.8,"count":337,"slug":"ylaw-vancouver","mapsUrl":"https://www.google.com/maps/search/YLaw+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1122+Mainland+St+%23580%2C+Vancouver%2C+BC+V6B+5L1","website":"https://www.ylaw.ca","blurb":"Family Law / Civil Litigation in Vancouver. Rated 4.8 from 337 Google reviews.","type":"logo","src":"images/logos/ylaw-vancouver.png","details":{"lawyers":[{"name":"Leena R. Yousefi"},{"name":"Ari Wormeli"},{"name":"Abib Ngom"},{"name":"Jasmeet Mangat"},{"name":"Trudy Hopman"},{"name":"Lisa Newby"},{"name":"Cathleen McClughan"},{"name":"Mandy Lai"},{"name":"Karen Tiwana"},{"name":"Andrew Gray"},{"name":"Susan Justice"},{"name":"Stuart Koop"}],"areas":["Family law","Employment law","Immigration law","Estate litigation","Strata law","Wills variation claims","Civil litigation"],"serving":["Vancouver","Langley","Chilliwack","Surrey"]}}',NULL,'YLaw is a Vancouver firm handling family, employment, estate litigation, immigration and strata law matters across British Columbia.

The firm has offices in Vancouver, Langley and Chilliwack, and also serves Surrey. Its family lawyers deal with divorce, common-law separation, asset and debt division, spousal and child support and parenting time, plus mediation. The employment group covers wrongful dismissal, severance, contracts and workplace equity, while estate litigators handle will disputes and unfair wills. YLaw also handles civil litigation and class actions. It does not treat every case as a battle and focuses on a client''s long-term family, career and financial interests.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('immiland-montreal','Immiland','Montreal','QC','qc-montreal',0,4.8,1067,45.529777,-73.5565972,'{"name":"Immiland","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.529777,"lng":-73.5565972,"address":"2025 Rue Parthenais #320, Montreal, Quebec H2K 3T2","phone":"+14386302527","rating":4.8,"count":1067,"slug":"immiland-montreal","mapsUrl":"https://www.google.com/maps/search/Immiland+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2025+Rue+Parthenais+%23320%2C+Montreal%2C+Quebec+H2K+3T2","website":"https://www.immilandcanada.com","blurb":"Immigration in Montreal. Rated 4.8 from 1067 Google reviews.","type":"logo","src":"images/logos/immiland-montreal.png","details":{"areas":["Inmigración"],"serving":["Ottawa"]}}',NULL,'Immiland is a Montreal immigration consulting company that helps families, workers and students plan a move to Canada, and it works in Spanish.

Its services cover immigration, recruitment, education, translation and settlement, along with support for working in Canada, studying in Canada and tourist visas. The company holds more than 100 education agreements with colleges, universities and institutes recognized as Designated Learning Institutions, which lets it process study permits. It also addresses practical settlement questions such as choosing a neighbourhood. Immiland is regulated by the Law Society of Ontario and the College of Immigration and Citizenship Consultants, and its office is on Rue Parthenais.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('liberty-law-llp-edmonton','Liberty Law LLP','Edmonton','AB','ab-edmonton',0,4.8,298,53.5410763,-113.5049513,'{"name":"Liberty Law LLP","city":"Edmonton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-edmonton","province":"AB","lat":53.5410763,"lng":-113.5049513,"address":"10110 107 St NW, Edmonton, AB T5J 1J4","phone":"+17807847500","rating":4.8,"count":298,"slug":"liberty-law-llp-edmonton","mapsUrl":"https://www.google.com/maps/search/Liberty+Law+LLP+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10110+107+St+NW%2C+Edmonton%2C+AB+T5J+1J4","website":"https://libertylaw.ca","blurb":"Criminal Defence in Edmonton. Rated 4.8 from 298 Google reviews.","type":"logo","src":"images/logos/liberty-law-llp-edmonton.webp","details":{"areas":["Criminal defence","Impaired driving defence","SafeRoads IRS reviews","Sexual assault defence"],"serving":["Edmonton","Grande Prairie","Fort McMurray"]}}','{"1":[["08:30","17:00"]],"2":[["08:30","17:00"]],"3":[["08:30","17:00"]],"4":[["08:30","17:00"]],"5":[["08:30","17:00"]]}','Liberty Law LLP is an Edmonton criminal defence firm that represents people charged with offences at every level of Alberta courts.

The firm practises criminal defence only. Its lawyers appear in Provincial Court, the Court of King''s Bench and the Court of Appeal, and matters include murder, sexual assault, drug and weapon offences, domestic violence, impaired driving and appeals. Besides its downtown Edmonton office, it has offices in Grande Prairie and Fort McMurray, and it serves Alberta, Saskatchewan and the Northwest Territories. A team of more than twenty lawyers includes senior trial and appellate counsel.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('gogna-immigration-inc-edmonton','Gogna Immigration Inc.','Edmonton','AB','ab-edmonton',0,4.9,291,53.5482266,-113.6209608,'{"name":"Gogna Immigration Inc.","city":"Edmonton","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"ab-edmonton","province":"AB","lat":53.5482266,"lng":-113.6209608,"address":"17415 105 Ave NW, Edmonton, AB T5S 2G8","phone":"+17802441907","rating":4.9,"count":291,"slug":"gogna-immigration-inc-edmonton","mapsUrl":"https://www.google.com/maps/search/Gogna+Immigration+Inc.+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=17415+105+Ave+NW%2C+Edmonton%2C+AB+T5S+2G8","website":"https://www.gognaimmigration.com","blurb":"Immigration in Edmonton. Rated 4.9 from 291 Google reviews.","type":"logo","src":"images/logos/gogna-immigration-inc-edmonton.png","details":{"areas":["Express Entry","Family sponsorship","Spousal sponsorship","Parents and grandparents sponsorship","Provincial Nominee Program","Super visa","LMIA and work permits"],"serving":["Edmonton"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Gogna Immigration Inc., based in Edmonton, is a team of regulated immigration consultants handling Canadian visas, citizenship and immigration applications.

The company serves clients across Canada and overseas, and covers nearby communities including St. Albert, Leduc, Sherwood Park, Fort Saskatchewan and Spruce Grove. Rather than limiting itself to one category or program, it helps with a broad range of applications. Neha has worked in immigration consulting for more than a decade, and the company''s aim is to simplify immigration steps for people whose applications affect their families and futures.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('shapiro-llp-north-york','Shapiro LLP','North York','ON','toronto',0,4.7,446,43.765946,-79.3900944,'{"name":"Shapiro LLP","city":"North York","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.765946,"lng":-79.3900944,"address":"333 Sheppard Ave E #201, North York, ON M2N 3B3","phone":"+14162240808","rating":4.7,"count":446,"slug":"shapiro-llp-north-york","mapsUrl":"https://www.google.com/maps/search/Shapiro+LLP+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=333+Sheppard+Ave+E+%23201%2C+North+York%2C+ON+M2N+3B3","website":"https://www.shapirollp.ca","blurb":"Real Estate in North York. Rated 4.7 from 446 Google reviews.","type":"logo","src":"images/logos/shapiro-llp-north-york.png"}',NULL,'Shapiro LLP is a North York law firm serving the Greater Toronto Area in residential and commercial real estate, business law, and wills and estates.

The firm''s work also includes commercial matters and private mortgages, and it provides legal services across Canada. The practice is at Sheppard Avenue East in North York. Its practice areas are grouped under real estate, business and commercial law, private mortgage work and wills, estates and trusts.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bellissimo-immigration-law-group-pc-toronto','Bellissimo Immigration Law Group PC','Toronto','ON','toronto',0,4.7,560,43.7066847,-79.3994865,'{"name":"Bellissimo Immigration Law Group PC","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.7066847,"lng":-79.3994865,"address":"20 Eglinton Ave W #1402, Toronto, ON M4R 1K8","phone":"+14167876505","rating":4.7,"count":560,"slug":"bellissimo-immigration-law-group-pc-toronto","mapsUrl":"https://www.google.com/maps/search/Bellissimo+Immigration+Law+Group+PC+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=20+Eglinton+Ave+W+%231402%2C+Toronto%2C+ON+M4R+1K8","website":"https://www.bellissimolawgroup.com","blurb":"Immigration in Toronto. Rated 4.7 from 560 Google reviews.","type":"logo","src":"images/logos/bellissimo-immigration-law-group-pc-toronto.webp","details":{"areas":["Immigration litigation","Inadmissibility","Citizenship"],"serving":["Calgary","Toronto"]}}',NULL,'Bellissimo Immigration Law Group PC is a Toronto firm handling immigration, citizenship and refugee matters for individuals and families from around the world.

The firm is one of few remaining law firms in Canada that focus exclusively on citizenship, immigration and refugee law, and its team''s experience goes back more than forty-five years. It has been responsible for key court decisions, policy work and publications in the field. Its work includes complex citizenship, immigration and refugee appeals and inadmissibility cases. The firm takes a client-centred approach with plain and transparent communication, and answers common questions about hiring an immigration lawyer in Canada.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('choice-immigration-services-edmonton','Choice Immigration Services','Edmonton','AB','ab-edmonton',0,4.7,322,53.4518213,-113.4778738,'{"name":"Choice Immigration Services","city":"Edmonton","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"ab-edmonton","province":"AB","lat":53.4518213,"lng":-113.4778738,"address":"9650 20 Ave NW Ste 103, Edmonton, AB T6N 1G1","phone":"+17804367666","rating":4.7,"count":322,"slug":"choice-immigration-services-edmonton","mapsUrl":"https://www.google.com/maps/search/Choice+Immigration+Services+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=9650+20+Ave+NW+Ste+103%2C+Edmonton%2C+AB+T6N+1G1","website":"https://choiceimmigration.ca","blurb":"Immigration in Edmonton. Rated 4.7 from 322 Google reviews.","type":"logo","src":"images/logos/choice-immigration-services-edmonton.png","details":{"areas":["Permanent residence applications","Sponsorship applications","Provincial nominations","LMIA applications","Immigration appeals","Refugee cases","Express Entry","Super visa","Study visas","Work visas"],"serving":["Edmonton"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Choice Immigration Services is an Edmonton practice handling permanent residence, study and work visas, sponsorships and citizenship.

Its work also includes provincial nominations, LMIA applications, immigration appeals and refugee cases, along with assessments and commissioner of oaths services. Its team of regulated immigration consultants has over 16 years of combined experience. Clients are taken through three steps: an assessment, preparation of the case and filing of the application, and then the outcome. The firm manages an application from document preparation through submission, and Alberta and wider Canadian immigration rules have become stricter over time.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lambert-avocats-montreal','Lambert Avocats','Montreal','QC','qc-montreal',0,4.7,399,45.5013271,-73.5707508,'{"name":"Lambert Avocats","city":"Montreal","featured":false,"tags":["Personal Injury","Civil Litigation","Criminal Defence","Real Estate"],"caseTypes":["injury","litigation","criminal","realestate"],"region":"qc-montreal","province":"QC","lat":45.5013271,"lng":-73.5707508,"address":"1200 McGill College Ave bureau 1800, Montreal, Quebec H3B 4G7","phone":"+15145262378","rating":4.7,"count":399,"slug":"lambert-avocats-montreal","mapsUrl":"https://www.google.com/maps/search/Lambert+Avocats+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1200+McGill+College+Ave+bureau+1800%2C+Montreal%2C+Quebec+H3B+4G7","website":"https://lambertavocats.ca","blurb":"Personal Injury / Civil Litigation in Montreal. Rated 4.7 from 399 Google reviews.","type":"logo","src":"images/logos/lambert-avocats-montreal.png","details":{"areas":["Droit civil","Droit administratif","Droit criminel","Droit pénal","Droit disciplinaire","Responsabilité civile","Actions collectives","SAAQ","CNESST","IVAC"],"serving":["Montréal"]}}',NULL,'Lambert Avocats is a Montreal firm handling civil, administrative, criminal, penal and disciplinary law, including SAAQ and injury matters.

The firm works in French, offers percentage-based, hourly or mixed fee arrangements and is available around the clock in criminal matters. Its civil liability work covers injuries from unsafe public places and collapsed stairs or balconies. A further area is disciplinary law, including nurses facing complaints before the Ordre des infirmières et infirmiers. The practice is located on McGill College Avenue and represents clients through each stage, from explaining rights and obligations to filing proceedings and appearing in court.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('barrou-nadia-montreal','Barrou Nadia','Montreal','QC','qc-montreal',0,4.7,351,45.4958427,-73.6163753,'{"name":"Barrou Nadia","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.4958427,"lng":-73.6163753,"address":"5000 Decelles Ave Suite 101, Montreal, Quebec H3V 1H7","phone":"+15142861613","rating":4.7,"count":351,"slug":"barrou-nadia-montreal","mapsUrl":"https://www.google.com/maps/search/Barrou+Nadia+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5000+Decelles+Ave+Suite+101%2C+Montreal%2C+Quebec+H3V+1H7","website":"https://www.barrou.com","blurb":"Immigration in Montreal. Rated 4.7 from 351 Google reviews.","type":"logo","src":"images/logos/barrou-nadia-montreal.png","details":{"founded":1998,"areas":["Droit de l’immigration","Résidence permanente","Parrainage","Citoyenneté canadienne","Permis d’étude","Permis de travail","Entrée Express","Super visa","Travailleurs temporaires"]}}',NULL,'Barrou Nadia is a Montreal immigration law practice handling temporary visas, permanent residence, sponsorship and citizenship applications.

The firm has worked in Canadian immigration law since 1998, with a team of lawyers and consultants. It acts on applications for foreign students, temporary workers, permanent residents, sponsored family members, visitors and prospective citizens. Work permit routes include labour market impact assessment streams, the International Mobility Program, the Programme de l''expérience québécoise and the regular skilled worker program, along with permanent resident card renewals. Nadia Barrou Avocate Inc. now operates as Barrou Immigration Inc., and the team presents online webinars.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lmrt-immigration-services-montreal','LMRT Immigration Services','Montreal','QC','qc-montreal',0,4.7,481,45.5390818,-73.6550021,'{"name":"LMRT Immigration Services","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.5390818,"lng":-73.6550021,"address":"433 Rue Chabanel O Office 620, Montreal, Quebec H2N 2J9","phone":"+14387006165","rating":4.7,"count":481,"slug":"lmrt-immigration-services-montreal","mapsUrl":"https://www.google.com/maps/search/LMRT+Immigration+Services+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=433+Rue+Chabanel+O+Office+620%2C+Montreal%2C+Quebec+H2N+2J9","website":"https://lmrtimmigration.com","blurb":"Immigration in Montreal. Rated 4.7 from 481 Google reviews.","type":"logo","src":"images/logos/lmrt-immigration-services-montreal.png","details":{"founded":2017,"languages":["English","Arabic","Persian","French"],"areas":["Asylum claims and refugee status","Family sponsorship","Express Entry","Business immigration","Quebec immigration programs","Study permits","Work permits and LMIA","Humanitarian and compassionate applications"],"serving":["Montreal"]}}','{"1":[["09:30","16:30"]],"2":[["09:30","16:30"]],"3":[["09:30","16:30"]],"4":[["09:30","16:30"]],"5":[["09:30","16:30"]]}','LMRT Immigration Services is a Montreal team of regulated immigration consultants handling asylum cases, family sponsorship and Express Entry.

The firm has worked on refugee and sponsorship files since 2017, and its founder, Loujin Khalil, is a regulated consultant authorized to appear before the Immigration and Refugee Board. His background includes business immigration streams such as entrepreneur programs, the Start-up Visa and owner-operator. Services are offered in English, French, Arabic and Persian, Quebec programs are covered, appointments can be held online, and guides are published on topics such as the four divisions of the Immigration and Refugee Board of Canada.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('diversitas-law-group-london','Diversitas Law Group','London','ON','southwestern',0,4.7,312,42.9730033,-81.2624282,'{"name":"Diversitas Law Group","city":"London","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"southwestern","province":"ON","lat":42.9730033,"lng":-81.2624282,"address":"145 Wharncliffe Rd S #100, London, ON N6J 2K4","phone":"+15199143380","rating":4.7,"count":312,"slug":"diversitas-law-group-london","mapsUrl":"https://www.google.com/maps/search/Diversitas+Law+Group+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=145+Wharncliffe+Rd+S+%23100%2C+London%2C+ON+N6J+2K4","website":"https://www.dlawgroup.ca","blurb":"Family Law in London. Rated 4.7 from 312 Google reviews.","type":"logo","src":"images/logos/diversitas-law-group-london.png","details":{"lawyers":[{"name":"Harkamal Singh"},{"name":"Selvin Mejia"},{"name":"Ahmad Barzak"},{"name":"Li Tian"}],"areas":["Immigration law","Citizenship law","Refugee protection law"]}}',NULL,'Diversitas Law Group is a London, Ontario association of independent practitioners handling immigration, citizenship and refugee protection matters.

The group is not a law firm, partnership or limited liability company: each sole practitioner runs a separate practice, shares office space and administrative resources, and holds the solicitor-client relationship personally. Its practitioners have more than thirty years of combined experience and offer service in Arabic, Spanish, Mandarin, Cantonese, Hindi, Punjabi and Urdu. Its work covers immigration, refugee and citizenship appeals, including reconsideration, residency obligation appeals and responses to various immigration refusals.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ronen-kurzfeld-immigration-lawyer-toronto-north-york','Ronen Kurzfeld Immigration Lawyer Toronto','North York','ON','toronto',0,4.8,279,43.7634621,-79.404535,'{"name":"Ronen Kurzfeld Immigration Lawyer Toronto","city":"North York","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.7634621,"lng":-79.404535,"address":"110 Sheppard Ave E Ste 630, North York, ON M2N 6Y8","phone":"+16472497976","rating":4.8,"count":279,"slug":"ronen-kurzfeld-immigration-lawyer-toronto-north-york","mapsUrl":"https://www.google.com/maps/search/Ronen+Kurzfeld+Immigration+Lawyer+Toronto+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=110+Sheppard+Ave+E+Ste+630%2C+North+York%2C+ON+M2N+6Y8","website":"https://www.immigrationway.com","blurb":"Immigration in North York. Rated 4.8 from 279 Google reviews.","type":"logo","src":"images/logos/ronen-kurzfeld-immigration-lawyer-toronto-north-york.webp","details":{"lawyers":[{"name":"Ronen Kurzfeld"}],"areas":["Spousal sponsorship","Family sponsorship","Common-law partner sponsorship","Parents and grandparents sponsorship","Business immigration","Humanitarian and compassionate applications"],"serving":["Toronto"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Ronen Kurzfeld Immigration Lawyer Toronto is a North York practice handling spousal sponsorship, Express Entry, citizenship and immigration appeals.

The firm is a licensed and insured immigration law office headquartered in the Toronto area. Ronen Kurzfeld graduated from Osgoode Hall Law School, studied in its intensive immigration and refugee law programme, and has more than twenty years in the field with over 2,500 clients worldwide. Services include business applications and enforcement matters, and the team can represent clients in almost any language. Payment plans are available, and the firm publishes articles on refugee cases and refusal appeals.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('randhawa-law-centre-surrey','Randhawa Law Centre','Surrey','BC','bc-fraser',0,4.8,277,49.1475771,-122.8671023,'{"name":"Randhawa Law Centre","city":"Surrey","featured":false,"tags":["Family Law","Real Estate","Wills & Estates"],"caseTypes":["family","realestate","wills"],"region":"bc-fraser","province":"BC","lat":49.1475771,"lng":-122.8671023,"address":"12830 80 Ave #105B, Surrey, BC V3W 3A8","phone":"+17785644774","rating":4.8,"count":277,"slug":"randhawa-law-centre-surrey","mapsUrl":"https://www.google.com/maps/search/Randhawa+Law+Centre+Surrey+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=12830+80+Ave+%23105B%2C+Surrey%2C+BC+V3W+3A8","website":"https://www.randhawalawyer.com","blurb":"Family Law / Real Estate in Surrey. Rated 4.8 from 277 Google reviews.","type":"logo","src":"images/logos/randhawa-law-centre-surrey.png","details":{"areas":["Property law","Family law","Wills and estates","Notary","Power of attorney"],"serving":["Surrey"]}}','{"1":[["09:00","18:00"]],"2":[["09:00","18:00"]],"3":[["09:00","18:00"]],"4":[["09:00","18:00"]],"5":[["09:00","18:00"]],"6":[["09:00","18:00"]]}','Randhawa Law Centre is a Surrey, BC law office and notary practice handling real estate, family law, and wills and estates for the Lower Mainland.

The firm was founded by Honveer Randhawa, who earned his law degree at the University of Manitoba, and it serves clients in English, Punjabi and Hindi. Its work includes divorce, builder''s liens, property sales and purchases, refinancing, mortgage conveyancing, certificates of pending litigation and notary services, with immigration also handled. The office keeps late weekday hours, is available on weekends when needed, and welcomes walk-ins at its ground-floor location on 80 Avenue.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('crossroads-law-vancouver','Crossroads Law','Vancouver','BC','bc-vancouver',0,4.9,270,49.2873133,-123.1160038,'{"name":"Crossroads Law","city":"Vancouver","featured":false,"tags":["Family Law","Civil Litigation","Wills & Estates"],"caseTypes":["family","litigation","wills"],"region":"bc-vancouver","province":"BC","lat":49.2873133,"lng":-123.1160038,"address":"999 W Hastings St Ste 1660, Vancouver, BC V6C 2W2","phone":"+18004661838","rating":4.9,"count":270,"slug":"crossroads-law-vancouver","mapsUrl":"https://www.google.com/maps/search/Crossroads+Law+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=999+W+Hastings+St+Ste+1660%2C+Vancouver%2C+BC+V6C+2W2","website":"https://www.crossroadslaw.ca","blurb":"Family Law / Civil Litigation in Vancouver. Rated 4.9 from 270 Google reviews.","type":"logo","src":"images/logos/crossroads-law-vancouver.png","details":{"lawyers":[{"name":"Marcus M. Sixta"},{"name":"Mat Wirove","title":"Partner"},{"name":"Matthew Katsionis"},{"name":"Amanda Marsden"},{"name":"Cindy Marshall","title":"Sr. Family Lawyer"},{"name":"Cori Molloy","title":"Managing Lawyer"},{"name":"Ashley R. Wilson"},{"name":"Camille Boyer"},{"name":"Paul R. Meyers"},{"name":"Jenna Lalani"},{"name":"Millad Ossudallah"},{"name":"Tanya Thakur"}],"areas":["Family law","Divorce","Separation","Mediation","Estate planning","Estate litigation","Civil litigation","Child and spousal support"],"serving":["Vancouver","Calgary","Alberta"]}}','{"1":[["08:30","16:30"]],"2":[["08:30","16:30"]],"3":[["08:30","16:30"]],"4":[["08:30","16:30"]],"5":[["08:30","16:30"]]}','Crossroads Law is a Vancouver family law firm handling divorce, separation, child support and parenting matters in British Columbia and Alberta.

Founded in 2017, the firm has family lawyers in Vancouver, Calgary and Edmonton. Beyond court proceedings, it offers mediation, collaborative family law and arbitration, with billing choices that range from flat-rate fees to legal coaching and unbundled services. Remote legal support is also available. The firm takes a client-centred approach, features a discussion of legal coaching with lawyer Marcus Sixta, and does volunteer work and partners with community organizations in both provinces.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('anderson-haak-and-engels-edmonton','Anderson Haak & Engels','Edmonton','AB','ab-edmonton',0,4.8,255,53.4670976,-113.4822157,'{"name":"Anderson Haak & Engels","city":"Edmonton","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"ab-edmonton","province":"AB","lat":53.4670976,"lng":-113.4822157,"address":"9811 34 Ave NW, Edmonton, AB T6E 5X9","phone":"+17804131763","rating":4.8,"count":255,"slug":"anderson-haak-and-engels-edmonton","mapsUrl":"https://www.google.com/maps/search/Anderson+Haak+%26+Engels+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=9811+34+Ave+NW%2C+Edmonton%2C+AB+T6E+5X9","website":"https://www.albertarealestatelawyers.com","blurb":"Real Estate in Edmonton. Rated 4.8 from 255 Google reviews.","type":"logo","src":"images/logos/anderson-haak-and-engels-edmonton.png","details":{"lawyers":[{"name":"Kenneth R. Haak"},{"name":"Robert A. Engels"},{"name":"Graham Semeniuk"}],"areas":["Real estate","Enduring power of attorney"]}}',NULL,'Anderson Haak & Engels is an Edmonton real estate law firm handling home and condo purchases, sales and mortgage refinancing in Alberta.

A lawyer is needed in Alberta to transfer title on a purchase or sale, and the firm brings more than sixty years of experience to that work. It has handled over 45,000 real estate transactions, and its partners are Kenneth R. Haak and Robert A. Engels. The firm also prepares wills, personal care directives and enduring powers of attorney, and it publishes base fees for each service.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lm-law-group-toronto','LM Law Group','Toronto','ON','toronto',0,4.9,249,43.6522998,-79.3752505,'{"name":"LM Law Group","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.6522998,"lng":-79.3752505,"address":"103 Church St #500, Toronto, ON M5C 2G3","phone":"+14165489101","rating":4.9,"count":249,"slug":"lm-law-group-toronto","mapsUrl":"https://www.google.com/maps/search/LM+Law+Group+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=103+Church+St+%23500%2C+Toronto%2C+ON+M5C+2G3","website":"https://www.lmlawgroup.com","blurb":"Immigration in Toronto. Rated 4.9 from 249 Google reviews.","type":"logo","src":"images/logos/lm-law-group-toronto.png","details":{"lawyers":[{"name":"Elizabeth Long","title":"Partner"},{"name":"Aadil Mangalji","title":"Partner"},{"name":"Ziah Sumar","title":"Partner"},{"name":"Erin Levitsky","title":"Associate"},{"name":"Catanne Boan-Mitchell","title":"Associate"}],"areas":["Economic immigration","Family sponsorship","Humanitarian and compassionate","Immigration and refugee law"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','LM Law Group is a Toronto immigration firm handling study permits, work permits, permanent residence, visitor visas, Express Entry and citizenship applications.

Founded in 2007, the firm has a team of about 25. Partners are Elizabeth Long, Aadil Mangalji and Ziah Sumar, with associates including Erin Levitsky and Catanne Boan-Mitchell. Services are organized by client group: employers, students, permanent residents, workers, visitors, citizens and entrepreneurs. Each case is assessed individually so that the immigration path fits the person, with an empathy-focused approach.','dynamic','live',NULL);
