INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('chandler-law-kelowna','Chandler Law','Kelowna','BC','bc-okanagan',0,4.9,57,49.8848373,-119.4952968,'{"name":"Chandler Law","city":"Kelowna","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"bc-okanagan","province":"BC","lat":49.8848373,"lng":-119.4952968,"address":"1630 Pandosy St #402, Kelowna, BC V1Y 1P7","phone":"+12507624415","rating":4.9,"count":57,"slug":"chandler-law-kelowna","mapsUrl":"https://www.google.com/maps/search/Chandler+Law+Kelowna+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1630+Pandosy+St+%23402%2C+Kelowna%2C+BC+V1Y+1P7","website":"https://www.chandlerlaw.ca","blurb":"Family Law in Kelowna. Rated 4.9 from 57 Google reviews.","type":"logo","src":"images/logos/chandler-law-kelowna.png","details":{"lawyers":[{"name":"John Chandler"}],"areas":["Family law","Cohabitation agreements","Prenuptial and marriage agreements","Separation agreements","Divorce litigation","Mediation"],"serving":["Okanagan","British Columbia"]}}',NULL,'Chandler Law is a Kelowna family law firm advising on separation, divorce, parenting, support and property division.

John Chandler, the founding partner, holds a B.A. and LL.B. and represents clients throughout the Okanagan and across British Columbia, preferring resolution where possible but prepared to go to trial. The firm also prepares cohabitation, prenuptial or marriage, and separation agreements and assists with mediation and negotiated settlements. Parenting arrangements, child and spousal support, and division of property and debt are among the issues it handles. Chantelle A., a legal assistant and office manager who has worked in the legal field since 2018, keeps the office running.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('brum-immigration-ottawa','Brum Immigration','Ottawa','ON','eastern',0,5,55,45.3846125,-75.6730117,'{"name":"Brum Immigration","city":"Ottawa","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"eastern","province":"ON","lat":45.3846125,"lng":-75.6730117,"address":"1376 Bank St #308, Ottawa, ON K1H 7Y3","phone":"+16133020001","rating":5,"count":55,"slug":"brum-immigration-ottawa","mapsUrl":"https://www.google.com/maps/search/Brum+Immigration+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1376+Bank+St+%23308%2C+Ottawa%2C+ON+K1H+7Y3","website":"https://brumimmigration.ca","blurb":"Immigration in Ottawa. Rated 5.0 from 55 Google reviews.","type":"logo","src":"images/logos/brum-immigration-ottawa.png","details":{"areas":["US immigration"]}}',NULL,'Brum Immigration is an Ottawa immigration and citizenship practice led by Renata Brum, a former Senior Citizenship Judge of Canada.

