INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('share-lawyers-calgary-calgary','Share Lawyers Calgary','Calgary','AB','ab-calgary',0,4.9,53,51.0495031,-114.0734208,'{"name":"Share Lawyers Calgary","city":"Calgary","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"ab-calgary","province":"AB","lat":51.0495031,"lng":-114.0734208,"address":"330 5 St SW Ste 1800, Calgary, AB T2P 0J4","phone":"+15878033049","rating":4.9,"count":53,"slug":"share-lawyers-calgary-calgary","mapsUrl":"https://www.google.com/maps/search/Share+Lawyers+Calgary+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=330+5+St+SW+Ste+1800%2C+Calgary%2C+AB+T2P+0J4","website":"https://sharelawyers.com","blurb":"Employment Law in Calgary. Rated 4.9 from 53 Google reviews.","type":"logo","src":"images/logos/share-lawyers-calgary-calgary.png","heroImage":"images/hero/share-lawyers-calgary-calgary.webp","details":{"areas":["Long term disability","Disability insurance","Employment law"],"serving":["Toronto"]}}',NULL,'Share Lawyers, listed in Calgary, is a long-term disability insurance practice with a Toronto base and service across Canada.

