INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('wyman-and-williamson-criminal-defence-lawyers-calgary','Wyman & Williamson Criminal Defence Lawyers','Calgary','AB','ab-calgary',0,5,51,51.0465571,-114.0756951,'{"name":"Wyman & Williamson Criminal Defence Lawyers","city":"Calgary","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-calgary","province":"AB","lat":51.0465571,"lng":-114.0756951,"address":"645 7 Ave SW #2650, Calgary, AB T2P 4G8","phone":"+15873168733","rating":5,"count":51,"slug":"wyman-and-williamson-criminal-defence-lawyers-calgary","mapsUrl":"https://www.google.com/maps/search/Wyman+%26+Williamson+Criminal+Defence+Lawyers+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=645+7+Ave+SW+%232650%2C+Calgary%2C+AB+T2P+4G8","website":"https://criminallawyercalgary.ca","blurb":"Criminal Defence in Calgary. Rated 5.0 from 51 Google reviews.","type":"logo","src":"images/logos/wyman-and-williamson-criminal-defence-lawyers-calgary.png","details":{"areas":["Criminal defence","Sexual assault","Domestic assault","Assault","Theft and fraud","DUI","Drug offence","Youth offence","Impaired driving"],"serving":["Calgary","Airdrie","Cochrane","Okotoks","Didsbury","Turner Valley","Strathmore","Canmore"]}}','{"1":[["08:00","17:00"]],"2":[["08:00","17:00"]],"3":[["08:00","17:00"]],"4":[["08:00","17:00"]],"5":[["08:00","17:00"]]}','Wyman & Williamson is a Calgary criminal defence firm that handles only Criminal Code prosecutions, with a focus on sexual assault and impaired driving.

Its lawyers act at all levels of court in Alberta, have made several appearances before the Supreme Court of Canada, and take cases throughout Western Canada. The firm handles domestic assault matters, including the conditions police impose barring communication after a domestic incident, and covers simple and aggravated assault, threats and bail conditions. The consequences of a sexual assault conviction include possible incarceration and registration on the sex offender registry. The Calgary office sits on Seventh Avenue SW.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mccrea-immigration-law-vancouver','McCrea Immigration Law','Vancouver','BC','bc-vancouver',0,4.8,53,49.2802449,-123.1097316,'{"name":"McCrea Immigration Law","city":"Vancouver","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"bc-vancouver","province":"BC","lat":49.2802449,"lng":-123.1097316,"address":"560 Beatty St #205, Vancouver, BC V6B 2L3","phone":"+16046628200","rating":4.8,"count":53,"slug":"mccrea-immigration-law-vancouver","mapsUrl":"https://www.google.com/maps/search/McCrea+Immigration+Law+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=560+Beatty+St+%23205%2C+Vancouver%2C+BC+V6B+2L3","website":"https://www.mccrealaw.ca","blurb":"Immigration in Vancouver. Rated 4.8 from 53 Google reviews.","type":"logo","src":"images/logos/mccrea-immigration-law-vancouver.png","details":{"areas":["Canadian immigration law"]}}',NULL,'McCrea Immigration Law is a Vancouver firm advising on work permits, permanent residence, citizenship and corporate immigration.

The firm has worked only in Canadian immigration law for more than three decades, and its lawyers came from not-for-profit organizations and global law firms. It takes a plain-spoken style that turns legal language into practical advice, giving the same attention to a large corporation as to an individual applicant. The practice handles anything from a single narrow step to a full program of applications, and also assists clients dealing with audits. Its office is on Beatty Street in Vancouver, British Columbia.','dynamic','live',NULL);
