INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('pav-singh-criminal-lawyer-mississauga','Pav Singh Criminal Lawyer','Mississauga','ON','peel-halton',0,4.9,51,43.6181961,-79.6732124,'{"name":"Pav Singh Criminal Lawyer","city":"Mississauga","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.6181961,"lng":-79.6732124,"address":"90 Matheson Blvd W Ste 101, Mississauga, ON L5R 3R3","phone":"+14169022002","rating":4.9,"count":51,"slug":"pav-singh-criminal-lawyer-mississauga","mapsUrl":"https://www.google.com/maps/search/Pav+Singh+Criminal+Lawyer+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=90+Matheson+Blvd+W+Ste+101%2C+Mississauga%2C+ON+L5R+3R3","website":"https://www.lawpsk.com","blurb":"Criminal Defence in Mississauga. Rated 4.9 from 51 Google reviews.","type":"logo","src":"images/logos/pav-singh-criminal-lawyer-mississauga.png","bioImage":"images/bio/pav-singh-criminal-lawyer-mississauga.webp","details":{"lawyers":[{"name":"Pav Singh"}],"areas":["Criminal defence","DUI impaired driving","Assault and domestic violence","Financial crimes"],"serving":["Mississauga"]}}',NULL,'Pav Singh is a Mississauga criminal defence lawyer who represents clients across Peel Region, Toronto and surrounding areas.

Pav Singh completed a Bachelor of Arts in Criminal Justice at Ryerson University, a law degree at the University of Leicester, and a Master of Laws at Osgoode Hall Law School. His personal line is answered around the clock, every day of the year, and evening, weekend and out-of-office meetings are available. Fees are quoted upfront, with block fee and hourly options and payment plans. His office is on Matheson Boulevard West in Mississauga, Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('campbell-litigation-waterloo','Campbell Litigation','Waterloo','ON','waterloo-guelph',0,4.8,51,43.4993976,-80.5353302,'{"name":"Campbell Litigation","city":"Waterloo","featured":false,"tags":["Personal Injury","Civil Litigation"],"caseTypes":["injury","litigation"],"region":"waterloo-guelph","province":"ON","lat":43.4993976,"lng":-80.5353302,"address":"40 Durward Pl, Waterloo, ON N2L 4E4","phone":"+15198861204","rating":4.8,"count":51,"slug":"campbell-litigation-waterloo","mapsUrl":"https://www.google.com/maps/search/Campbell+Litigation+Waterloo+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=40+Durward+Pl%2C+Waterloo%2C+ON+N2L+4E4","website":"https://petkerlaw.com","blurb":"Personal Injury / Civil Litigation in Waterloo. Rated 4.8 from 51 Google reviews.","type":"logo","src":"images/logos/campbell-litigation-waterloo.png","details":{"founded":2015,"lawyers":[{"name":"Richard Campbell","title":"Litigator"}],"areas":["Personal injury","Boating and snowmobile accidents","Litigation","Mortgage enforcement"],"serving":["Kitchener-Waterloo"]}}',NULL,'Campbell Litigation is a Waterloo practice handling personal injury, wrongful death and commercial and construction disputes in Kitchener-Waterloo.

Lawyer Richard Campbell has litigated since 1999, working mainly for plaintiffs in personal injury, professional negligence, product liability, secured creditors'' remedies and contract matters. He holds a Bachelor of Arts from St. Jerome''s College and a Juris Doctor from Osgoode Hall Law School, and conducts trials and appeals in the Ontario courts. He advises early on whether a dispute can be mediated, arbitrated or negotiated before litigation. Published articles cover fiduciary duty in closely held companies and ATV accidents.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('hoogbruin-and-company-vancouver','Hoogbruin & Company','Vancouver','BC','bc-vancouver',0,4.9,49,49.2861578,-123.1256058,'{"name":"Hoogbruin & Company","city":"Vancouver","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"bc-vancouver","province":"BC","lat":49.2861578,"lng":-123.1256058,"address":"1166 Alberni St Suite 1604, Vancouver, BC V6E 3Z3","phone":"+16046093783","rating":4.9,"count":49,"slug":"hoogbruin-and-company-vancouver","mapsUrl":"https://www.google.com/maps/search/Hoogbruin+%26+Company+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1166+Alberni+St+Suite+1604%2C+Vancouver%2C+BC+V6E+3Z3","website":"https://www.hoogbruin.com","blurb":"Personal Injury in Vancouver. Rated 4.9 from 49 Google reviews.","type":"logo","src":"images/logos/hoogbruin-and-company-vancouver.webp","details":{"lawyers":[{"name":"Michael Hoogbruin"},{"name":"Arsen Krekovic"},{"name":"Abraham An"}],"areas":["Personal injury law","Strata corporations","Real estate litigation","Commercial litigation","Wills and estates","Slip trip and fall","Medical malpractice","Wrongful death","Bicycle accidents","Product liability"],"serving":["Vancouver","British Columbia"]}}',NULL,'Hoogbruin & Company is a Vancouver litigation firm handling strata, real estate and commercial disputes, along with injury and wrongful death matters.

The firm has taken on cases across British Columbia since 1987. Its practice areas are strata corporations, strata owners and tenants, real estate litigation, commercial litigation, wills and estates, slip, trip and fall injuries, medical malpractice and wrongful death. Lawyers include Michael Hoogbruin, Arsen Krekovic and Abraham An. Injuries can affect work, family and mental health, and the firm works under a defined fee structure. The office is on Alberni Street in downtown Vancouver.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('white-and-jeet-criminal-defence-calgary','White & Jeet Criminal Defence','Calgary','AB','ab-calgary',0,4.9,49,51.080931,-114.0311377,'{"name":"White & Jeet Criminal Defence","city":"Calgary","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-calgary","province":"AB","lat":51.080931,"lng":-114.0311377,"address":"1212 31 Ave NE Ste 202, Calgary, AB T2E 7S8","phone":"+15877411351","rating":4.9,"count":49,"slug":"white-and-jeet-criminal-defence-calgary","mapsUrl":"https://www.google.com/maps/search/White+%26+Jeet+Criminal+Defence+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1212+31+Ave+NE+Ste+202%2C+Calgary%2C+AB+T2E+7S8","website":"https://whitejeetlaw.com","blurb":"Criminal Defence in Calgary. Rated 4.9 from 49 Google reviews.","type":"logo","src":"images/logos/white-and-jeet-criminal-defence-calgary.webp","details":{"lawyers":[{"name":"Greg White"},{"name":"Sarvesh Jeet"},{"name":"Amina Younas"},{"name":"Namra Latif"},{"name":"Jacqueline Pelland"},{"name":"David Ly"},{"name":"Jessica Atwal"},{"name":"Connor Mørk"},{"name":"Andrew MacKenzie"},{"name":"Jared Goruk"},{"name":"Balraj S. Bains"},{"name":"Gurjit S. Sidhu"}],"areas":["Sexual assault","Murder and homicide","Drug charges","Impaired driving","Domestic violence","Bail hearings","Young offenders","Record suspensions","Appeals","Theft and robbery"],"serving":["Lethbridge","Calgary","Medicine Hat","Red Deer","Alberta"]}}',NULL,'White & Jeet Criminal Defence is a Calgary team of criminal lawyers with offices in Lethbridge, Medicine Hat and Red Deer, serving all of Alberta.

Practice areas include violent and serious charges, sexual assault, murder and homicide, drug and controlled substance offences, financial and complex matters, and criminal driving offences. The firm also handles administration of justice offences, such as breaches of release conditions or probation under section 145 of the Criminal Code. Its work runs from early investigation and bail hearings through trial, appeals and post-conviction matters, and it operates a round-the-clock help line.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bergel-magence-guelph','Bergel Magence','Guelph','ON','waterloo-guelph',0,4.9,49,43.5438833,-80.24895,'{"name":"Bergel Magence","city":"Guelph","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"waterloo-guelph","province":"ON","lat":43.5438833,"lng":-80.24895,"address":"24 Carden St Ste 300A, Guelph, ON N1H 3A2","phone":"+18664923743","rating":4.9,"count":49,"slug":"bergel-magence-guelph","mapsUrl":"https://www.google.com/maps/search/Bergel+Magence+Guelph+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=24+Carden+St+Ste+300A%2C+Guelph%2C+ON+N1H+3A2","website":"https://www.bergellaw.com","blurb":"Personal Injury in Guelph. Rated 4.9 from 49 Google reviews.","type":"logo","src":"images/logos/bergel-magence-guelph.webp","bioImage":"images/bio/bergel-magence-guelph.webp","details":{"founded":1972,"areas":["Car accidents","Medical malpractice","Motorcycle accidents","Brain injuries","Slip and fall accidents","Long term disability"],"serving":["Toronto","Ontario"]}}','{"1":[["00:00","23:59"]],"2":[["00:00","23:59"]],"3":[["00:00","23:59"]],"4":[["00:00","23:59"]],"5":[["00:00","23:59"]],"6":[["00:00","23:59"]],"7":[["00:00","23:59"]]}','Bergel Magence is a personal injury firm in Guelph, with a Toronto practice for catastrophically injured clients across Ontario.

The firm was founded in 1972 by Hy Bergel, a former Provincial Court Deputy Judge, and is now led by partners Andrew Bergel, Ilan Bergel and Jeremy Magence. Its practice covers car, motorcycle, truck, pedestrian and bicycle accidents, slip and fall cases, dog bites, medical malpractice and brain injuries. Services are offered in English, French, Hebrew, Russian, Persian, Italian, Spanish and Chinese, and the practice is a three-generation family business.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('onyx-law-group-vancouver','Onyx Law Group','Vancouver','BC','bc-vancouver',0,4.6,52,49.281898,-123.1179131,'{"name":"Onyx Law Group","city":"Vancouver","featured":false,"tags":["Family Law","Wills & Estates"],"caseTypes":["family","wills"],"region":"bc-vancouver","province":"BC","lat":49.281898,"lng":-123.1179131,"address":"650 W Georgia St #1215, Vancouver, BC V6B 4N8","phone":"+16043302207","rating":4.6,"count":52,"slug":"onyx-law-group-vancouver","mapsUrl":"https://www.google.com/maps/search/Onyx+Law+Group+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=650+W+Georgia+St+%231215%2C+Vancouver%2C+BC+V6B+4N8","website":"https://onyxlaw.ca","blurb":"Family Law / Wills & Estates in Vancouver. Rated 4.6 from 52 Google reviews.","type":"logo","src":"images/logos/onyx-law-group-vancouver.webp","bioImage":"images/bio/onyx-law-group-vancouver.webp","details":{"areas":["Estates, trusts and probate","Divorce and family law","Estate planning","Estate and trusts litigation","Prenuptial agreements","Child and spousal support","Collaborative family law"],"serving":["British Columbia"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Onyx Law Group is a Vancouver boutique handling family law, divorce, and estate and trust litigation across Metro Vancouver.

The firm combines family and estate work, which lets it handle personal disputes that touch both areas. Its lead lawyers, Candace and Judith, have more than twenty years of combined family and estate law experience, and the team also includes paralegals. Offices are in Vancouver, Burnaby and Surrey, and clients are served in Richmond, Coquitlam, North Vancouver, West Vancouver and New Westminster. The firm works under the British Columbia Family Law Act, including property division and parenting rules, and offers flexible billing methods.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('osra-avocats-laval','Osra Avocats','Laval','QC','qc-laval-laurentides',0,4.9,48,45.5650398,-73.7243739,'{"name":"Osra Avocats","city":"Laval","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"qc-laval-laurentides","province":"QC","lat":45.5650398,"lng":-73.7243739,"address":"1555 Bd de l''Avenir #306, Laval, Quebec H7S 2N5","phone":"+18773492659","rating":4.9,"count":48,"slug":"osra-avocats-laval","mapsUrl":"https://www.google.com/maps/search/Osra+Avocats+Laval+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1555+Bd+de+l%27Avenir+%23306%2C+Laval%2C+Quebec+H7S+2N5","website":"https://www.osraavocats.com","blurb":"Family Law in Laval. Rated 4.9 from 48 Google reviews.","type":"logo","src":"images/logos/osra-avocats-laval.png","details":{"lawyers":[{"name":"Me Wafa Ouafi"}],"areas":["Droit familial","Pension alimentaire pour enfants","Pension alimentaire pour ex-conjoint","Modification de pension alimentaire","Partage du patrimoine familial"],"serving":["Laval"]}}',NULL,'Osra Avocats is a Laval, Quebec, firm working mainly in family law across the greater Montreal region.

Matters include contested and amicable divorces, separation, negotiated settlements, child custody, child and spousal support, changes to support orders, partition of the family patrimony and the partnership of acquests, safeguard measures and loss of parental authority. Family law rests above all on human and psychological considerations, so each file is handled with attention to the client''s needs and expectations, with an emphasis on listening. Lawyer Me Wafa Ouafi is part of the team.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('oracle-law-vancouver','Oracle Law','Vancouver','BC','bc-vancouver',0,5,47,49.2806097,-123.1176899,'{"name":"Oracle Law","city":"Vancouver","featured":false,"tags":["Real Estate","Business Law"],"caseTypes":["realestate","business"],"region":"bc-vancouver","province":"BC","lat":49.2806097,"lng":-123.1176899,"address":"777 Richards St Suite 602, Vancouver, BC V6B 0M6","phone":"+16044428242","rating":5,"count":47,"slug":"oracle-law-vancouver","mapsUrl":"https://www.google.com/maps/search/Oracle+Law+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=777+Richards+St+Suite+602%2C+Vancouver%2C+BC+V6B+0M6","website":"https://oraclelaw.ca","blurb":"Real Estate / Business Law in Vancouver. Rated 5.0 from 47 Google reviews.","type":"logo","src":"images/logos/oracle-law-vancouver.png","details":{"areas":["Real estate","Business law","Estate planning and probate","Residential real estate purchases","Strata or condo purchases","Commercial property purchases","Shareholders agreements","Commercial leasing","Last will and testament","Power of attorney"],"serving":["Vancouver"]}}',NULL,'Oracle Law is a Vancouver firm handling real estate conveyancing, mortgage refinancing and corporate law, with flat-fee residential purchase and sale work.

Work includes residential and strata purchases, commercial property purchases, family transfers and gifted property, and subdivisions. Lawyer Peter has more than ten years of experience, has run his own firm, and works alongside clients'' accountants, mortgage brokers and realtors when issues arise. He is fluent in Greek and serves clients in both English and Greek, and he is involved in the Greek Community of Greater Vancouver. Pricing is transparent and advice is practical.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('carbert-waite-llp-calgary','Carbert Waite LLP','Calgary','AB','ab-calgary',0,4.7,50,51.046559,-114.075729,'{"name":"Carbert Waite LLP","city":"Calgary","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"ab-calgary","province":"AB","lat":51.046559,"lng":-114.075729,"address":"645 7 Ave SW #2300, Calgary, AB T2P 4G8","phone":"+14032635656","rating":4.7,"count":50,"slug":"carbert-waite-llp-calgary","mapsUrl":"https://www.google.com/maps/search/Carbert+Waite+LLP+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=645+7+Ave+SW+%232300%2C+Calgary%2C+AB+T2P+4G8","website":"https://carbertwaite.com","blurb":"Employment Law in Calgary. Rated 4.7 from 50 Google reviews.","type":"logo","src":"images/logos/carbert-waite-llp-calgary.png","details":{"lawyers":[{"name":"Madina Abdi"},{"name":"Katie Ahn"},{"name":"Fiona Balaton"},{"name":"Sarah Barker"},{"name":"Lauren Barteluk"},{"name":"Michael Bokhaut"},{"name":"Davud Camgöz"},{"name":"Blair Carbert"},{"name":"Eleanor Carlson"},{"name":"Braeden Davis"},{"name":"Roxanne Davis"},{"name":"Bradley Dobbin"}],"areas":["Alternative dispute resolution","Commercial litigation","Condominium law","Construction litigation","Employment and labour law","Health law","Immigration law","Insurance law","Personal injury and negligence","Wills, estates and trusts"],"serving":["Calgary"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Carbert Waite LLP is a Calgary litigation firm covering commercial, employment, construction, condominium, insurance and personal injury disputes.

Founded in 1999, the firm acts for local, American and international clients in high-stakes matters across Alberta''s key industries. Its services also include alternative dispute resolution, health law, immigration, estate planning and business law. The employment and labour group is one of the largest in Calgary, advising both employers and employees across Alberta and western Canada. Lawyers include Roxanne Davis, KC, and Michael Waite, KC. The approach is practical, client-centred and tailored to each case.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('pender-litigation-vancouver','Pender Litigation','Vancouver','BC','bc-vancouver',0,4.7,50,49.2751066,-123.1220961,'{"name":"Pender Litigation","city":"Vancouver","featured":false,"tags":["Civil Litigation"],"caseTypes":["litigation"],"region":"bc-vancouver","province":"BC","lat":49.2751066,"lng":-123.1220961,"address":"1168 Hamilton St Suite 506, Vancouver, BC V6B 2S2","phone":"+16046696699","rating":4.7,"count":50,"slug":"pender-litigation-vancouver","mapsUrl":"https://www.google.com/maps/search/Pender+Litigation+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1168+Hamilton+St+Suite+506%2C+Vancouver%2C+BC+V6B+2S2","website":"https://www.penderlitigation.com","blurb":"Civil Litigation in Vancouver. Rated 4.7 from 50 Google reviews.","type":"logo","src":"images/logos/pender-litigation-vancouver.webp","details":{"areas":["Driving offences","Sexual offences","Violent offences","Drug offences","Fraud and theft"],"serving":["British Columbia","Vancouver"]}}',NULL,'Pender Litigation is a Vancouver criminal defence firm covering driving, sexual and violent offences in British Columbia courts.

The firm''s lawyers have also acted as ad hoc prosecutors, which lets them see cases from both sides. Its work spans minor offences, large complex cases, appeals and related applications. Driving law is a cornerstone of the practice, with attention to the strict time limits that apply to challenges involving driving privileges. Pender Litigation examines the evidence in detail, guides clients through how the justice system works, and takes a collaborative, team-based approach to each case.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('annette-lefebvre-avocats-montreal','Annette Lefebvre Avocats','Montreal','QC','qc-montreal',0,4.6,50,45.4987839,-73.5786722,'{"name":"Annette Lefebvre Avocats","city":"Montreal","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"qc-montreal","province":"QC","lat":45.4987839,"lng":-73.5786722,"address":"2185 Rue Crescent, Montréal, QC H3G 2C1","phone":"+15142881114","rating":4.6,"count":50,"slug":"annette-lefebvre-avocats-montreal","mapsUrl":"https://www.google.com/maps/search/Annette+Lefebvre+Avocats+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2185+Rue+Crescent%2C+Montr%C3%A9al%2C+QC+H3G+2C1","website":"https://www.annettelefebvre.com","blurb":"Personal Injury in Montreal. Rated 4.6 from 50 Google reviews.","type":"logo","src":"images/logos/annette-lefebvre-avocats-montreal.webp","bioImage":"images/bio/annette-lefebvre-avocats-montreal.webp","details":{"areas":["Erreur médicale","Préjudice corporel","Traumatismes obstétricaux","Blessure médullaire","Produits défectueux"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Annette Lefebvre Avocats is a Montreal firm representing patients and accident victims in medical malpractice and personal injury cases.

The firm acts only for patients and victims, including in birth injury, spinal cord injury and chiropractic injury cases against doctors, medical institutions, building owners and insurers. It has more than forty years of experience. Annette Lefebvre is a former intensive care nurse who has spent over thirty years on malpractice and injury suits, and Melissa Lonn has devoted her practice to the same fields, drawing on a background in social work and science. The firm serves Montreal, Laval, Longueuil and Brossard.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('purves-smith-law-guelph','Purves-Smith Law','Guelph','ON','waterloo-guelph',0,4.6,49,43.544372,-80.2480463,'{"name":"Purves-Smith Law","city":"Guelph","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"waterloo-guelph","province":"ON","lat":43.544372,"lng":-80.2480463,"address":"2 Wyndham St N, Guelph, ON N1H 4E3","phone":"+15198352100","rating":4.6,"count":49,"slug":"purves-smith-law-guelph","mapsUrl":"https://www.google.com/maps/search/Purves-Smith+Law+Guelph+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2+Wyndham+St+N%2C+Guelph%2C+ON+N1H+4E3","website":"https://www.purvessmithlaw.com","blurb":"Family Law in Guelph. Rated 4.6 from 49 Google reviews.","type":"logo","src":"images/logos/purves-smith-law-guelph.png","details":{"lawyers":[{"name":"Michael Purves-Smith"}],"areas":["Family law","Criminal law","Custody disputes","Child support","Divorce","Property equalization","Domestic contracts","Children''s Aid Society matters","Separation agreements"],"serving":["Guelph","Kitchener-Waterloo"]}}',NULL,'Purves-Smith Law is a Guelph family law practice serving Guelph and Kitchener-Waterloo on custody, support, property and child protection matters.

Lawyer Michael D. Purves-Smith, an Osgoode Hall Law School graduate who received the Morden prize in Evidence Law, focuses on high-conflict and complex files. The work covers custody disputes, guideline child support, imputation of income, property equalization involving business, corporate and farm assets, pensions, occupation rent, domestic contracts, and Children''s Aid Society matters. The firm also offers mediated settlement of family issues and accepts Legal Aid certificates case by case. Michael Purves-Smith is both a family and criminal lawyer.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('colautti-landry-partners-windsor','Colautti Landry Partners','Windsor','ON','southwestern',0,4.8,46,42.2845311,-83.0193176,'{"name":"Colautti Landry Partners","city":"Windsor","featured":false,"tags":["Civil Litigation"],"caseTypes":["litigation"],"region":"southwestern","province":"ON","lat":42.2845311,"lng":-83.0193176,"address":"2555 Ouellette Ave Bldg 140, Suite 200, Windsor, ON N8X 1L9","phone":"+15199661300","rating":4.8,"count":46,"slug":"colautti-landry-partners-windsor","mapsUrl":"https://www.google.com/maps/search/Colautti+Landry+Partners+Windsor+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2555+Ouellette+Ave+Bldg+140%2C+Suite+200%2C+Windsor%2C+ON+N8X+1L9","website":"https://www.clplaw.net","blurb":"Civil Litigation in Windsor. Rated 4.8 from 46 Google reviews.","type":"logo","src":"images/logos/colautti-landry-partners-windsor.jpg","details":{"lawyers":[{"name":"Raymond Colautti","title":"Senior Partner"},{"name":"Anita Landry","title":"Managing Partner"},{"name":"Andrew Colautti","title":"Associate"},{"name":"Patrick Clark"}],"areas":["Civil litigation","Wills and estates","Construction liens and litigation","Landlord and tenant disputes","Defamation, libel and slander","Aborted real estate transactions","Estate planning","Probate and estate administration"],"serving":["Windsor"]}}',NULL,'Colautti Landry Partners, known as CLP Law, is a Windsor firm handling civil litigation, corporate and commercial matters, and wills and estates.

Two of its lawyers hold Law Society of Ontario certification in civil litigation, one of only five such certifications in Windsor. Senior partner Raymond Colautti has over forty years of litigation experience, including appearances before the Supreme Court of Canada and a federal security intelligence oversight committee. Managing partner Anita Landry focuses on commercial disputes, fraud, trust and estate claims and appeals, and also runs a private mediation practice. Andrew Colautti handles construction, development and lien litigation, and holds law degrees from Ontario and Michigan.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('pihl-law-corporation-kelowna','Pihl Law Corporation','Kelowna','BC','bc-okanagan',0,4.6,47,49.8872668,-119.4933187,'{"name":"Pihl Law Corporation","city":"Kelowna","featured":false,"tags":["Civil Litigation"],"caseTypes":["litigation"],"region":"bc-okanagan","province":"BC","lat":49.8872668,"lng":-119.4933187,"address":"1465 Ellis St #300, Kelowna, BC V1Y 2A3","phone":"+12507625434","rating":4.6,"count":47,"slug":"pihl-law-corporation-kelowna","mapsUrl":"https://www.google.com/maps/search/Pihl+Law+Corporation+Kelowna+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1465+Ellis+St+%23300%2C+Kelowna%2C+BC+V1Y+2A3","website":"https://pihl.ca","blurb":"Civil Litigation in Kelowna. Rated 4.6 from 47 Google reviews.","type":"logo","src":"images/logos/pihl-law-corporation-kelowna.png","details":{"lawyers":[{"name":"Avery Barnett"},{"name":"Emily Bowen"},{"name":"Connor Elliott"},{"name":"Bree Hankins"},{"name":"Lesley Hobden"},{"name":"Rosie Jacobs"},{"name":"Calen Janzen"},{"name":"David Pihl"},{"name":"Sean Pihl"},{"name":"Andrew Prior"},{"name":"Megan Santano"},{"name":"Michael Sinclair"}],"areas":["Commercial litigation","Personal injury","Construction law","Family and estate litigation","Employment and labour","Mediation services"]}}','{"1":[["08:30","16:30"]],"2":[["08:30","16:30"]],"3":[["08:30","16:30"]],"4":[["08:30","16:30"]],"5":[["08:30","16:30"]]}','Pihl Law Corporation is a Kelowna litigation firm covering commercial litigation, personal injury, construction, family and estate disputes, and employment law.

The firm also offers mediation services and is a dispute resolution practice built on a team approach. Sean Pihl, K.C., is among the lawyers, alongside Andrew Prior, Alexander Spraggs, Calen Janzen, Connor Elliott, Emily Bowen and Avery Barnett. The firm walks clients through the legal process, gives them a candid view of their case, and will refer a client to another professional when that serves them better. Its articles discuss toxic torts and commercial leases.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('sutherland-criminal-defence-edmonton','Sutherland Criminal Defence','Edmonton','AB','ab-edmonton',0,4.9,44,53.5369896,-113.5034157,'{"name":"Sutherland Criminal Defence","city":"Edmonton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-edmonton","province":"AB","lat":53.5369896,"lng":-113.5034157,"address":"9844 106 St 3rd floor, Edmonton, AB T5K 1B8","phone":"+15874159855","rating":4.9,"count":44,"slug":"sutherland-criminal-defence-edmonton","mapsUrl":"https://www.google.com/maps/search/Sutherland+Criminal+Defence+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=9844+106+St+3rd+floor%2C+Edmonton%2C+AB+T5K+1B8","website":"https://sutherlandcriminaldefence.ca","blurb":"Criminal Defence in Edmonton. Rated 4.9 from 44 Google reviews.","type":"logo","src":"images/logos/sutherland-criminal-defence-edmonton.webp","details":{"lawyers":[{"name":"Ellen Sutherland"}],"areas":["Sexual offences","Criminal driving offences","Domestic assault","Parole board assistance","Bail hearings"],"serving":["Edmonton"]}}',NULL,'Sutherland Criminal Defence is an Edmonton firm led by Ellen Sutherland, handling sexual offences, domestic violence, driving charges and murder cases.

Ms. Sutherland has tried cases across Alberta, Saskatchewan and British Columbia, appearing in the Court of King''s Bench and the Alberta Court of Appeal. She also appears before tribunals, including the Parole Board of Canada and SafeRoads Alberta. Practice areas include drug offences, violent offences, criminal driving offences and parole board assistance, and emergency and bail help is available at all hours. She holds a B.A. and J.D., and the firm acts for clients across Western Canada.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('tcz-law-toronto','TCZ Law','Toronto','ON','toronto',0,5,43,43.6423271,-79.3773332,'{"name":"TCZ Law","city":"Toronto","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"toronto","province":"ON","lat":43.6423271,"lng":-79.3773332,"address":"20 Bay St. #1100, Toronto, ON M5J 2N8","phone":"+16474786560","rating":5,"count":43,"slug":"tcz-law-toronto","mapsUrl":"https://www.google.com/maps/search/TCZ+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=20+Bay+St.+%231100%2C+Toronto%2C+ON+M5J+2N8","website":"https://tczlaw.ca","blurb":"Family Law in Toronto. Rated 5.0 from 43 Google reviews.","type":"logo","src":"images/logos/tcz-law-toronto.webp","details":{"lawyers":[{"name":"Eric Tianchuan Zhao"}],"areas":["Divorce and separation","Custody and access","Child support","Spousal support","Marriage contract","Division of property","Cohabitation agreement","Separation agreement","Child protection","Alternative dispute resolution"],"serving":["Toronto","North York","Ottawa"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','TCZ Law is a Toronto family law firm handling divorce, separation, custody, support and domestic contracts, with services in English and Chinese.

Lawyer Eric Tianchuan Zhao represents clients in negotiation and, when needed, in court. Areas include custody and access, child support, spousal support, division of property, marriage contracts, cohabitation agreements and motions to change. The firm provides a draft separation agreement or marriage contract within five business days of receiving the needed information. Before opening his own practice he worked at Baker McKenzie LLP, McInnis & Nicoll and Mahdi Leite Family Law LPP, and the firm has downtown and North York locations.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('guberman-appleby-immigration-lawyers-toronto','Guberman Appleby Immigration Lawyers','Toronto','ON','toronto',0,5,43,43.6770243,-79.4013612,'{"name":"Guberman Appleby Immigration Lawyers","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.6770243,"lng":-79.4013612,"address":"287 Macpherson Ave Unit 201, Toronto, ON M4V 1A4","phone":"+14165487100","rating":5,"count":43,"slug":"guberman-appleby-immigration-lawyers-toronto","mapsUrl":"https://www.google.com/maps/search/Guberman+Appleby+Immigration+Lawyers+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=287+Macpherson+Ave+Unit+201%2C+Toronto%2C+ON+M4V+1A4","website":"https://gaimmigrationlawyers.com","blurb":"Immigration in Toronto. Rated 5.0 from 43 Google reviews.","type":"logo","src":"images/logos/guberman-appleby-immigration-lawyers-toronto.webp","heroImage":"images/hero/guberman-appleby-immigration-lawyers-toronto.webp","details":{"lawyers":[{"name":"Joel S. Guberman"},{"name":"Lainie Michelle Appleby"}],"areas":["Canadian immigration law","Temporary resident visa","Labour market impact assessments","Express entry","Spousal and family class sponsorship","Provincial nominee program","Super visa","Work permits","Study permits","US immigration"],"serving":["Toronto"]}}',NULL,'Guberman Appleby Immigration Lawyers is a Toronto firm advising on Canadian and U.S. immigration, from work permits and Express Entry to business immigration.

Its lawyers have more than seventy years of combined experience and act for individuals, families, entrepreneurs and multinational employers. Joel S. Guberman and Lainie Michelle Appleby hold memberships in the Law Society of Ontario, the Canadian Bar Association, CILA, AILA and the Massachusetts Bar. The practice covers family sponsorship, permanent residence and U.S. visas. Based in Toronto, the firm serves clients across Canada, the U.S. and abroad, and gives plain-language guidance with realistic timelines.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('laredo-law-toronto','Laredo Law','Toronto','ON','toronto',0,5,43,43.7008148,-79.3864661,'{"name":"Laredo Law","city":"Toronto","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"toronto","province":"ON","lat":43.7008148,"lng":-79.3864661,"address":"250 Davisville Ave Ste 108, Toronto, ON M4S 1H2","phone":"+14164823328","rating":5,"count":43,"slug":"laredo-law-toronto","mapsUrl":"https://www.google.com/maps/search/Laredo+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=250+Davisville+Ave+Ste+108%2C+Toronto%2C+ON+M4S+1H2","website":"https://www.laredolaw.ca","blurb":"Wills & Estates in Toronto. Rated 5.0 from 43 Google reviews.","type":"logo","src":"images/logos/laredo-law-toronto.png","details":{"founded":2007,"languages":["Spanish"],"lawyers":[{"name":"Lisa Laredo","title":"Principal Lawyer"},{"name":"Ana Wagner","title":"Associate Lawyer"}],"areas":["Wills and estates","Real estate law","Estate administration","Succession planning","Estate planning"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Laredo Law is a Toronto estates firm preparing wills, trusts and tax-aware succession plans and acting in estate administration.

The firm was founded in 2007 by Lisa Laredo, a Certified Trust and Estate Practitioner through STEP Canada who belongs to the Canadian Bar Association, the Ontario Bar Association and the Estate Planning Council of Canada. She also teaches accredited programs for lawyers and writes for legal journals. Associate lawyer Ana Wagner and a legal administrative assistant are on the team. The firm also has a real estate law practice and publishes a blog on wills and estates topics in plain language. The office is on Davisville Avenue.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('h-and-h-law-group-mississauga','H&H Law Group','Mississauga','ON','peel-halton',0,5,43,43.5999908,-79.608348,'{"name":"H&H Law Group","city":"Mississauga","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"peel-halton","province":"ON","lat":43.5999908,"lng":-79.608348,"address":"3292 Cawthra Rd, Mississauga, ON L5A 2X7","phone":"+14165727483","rating":5,"count":43,"slug":"h-and-h-law-group-mississauga","mapsUrl":"https://www.google.com/maps/search/H%26H+Law+Group+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=3292+Cawthra+Rd%2C+Mississauga%2C+ON+L5A+2X7","website":"https://hhlawgroup.ca","blurb":"Family Law in Mississauga. Rated 5.0 from 43 Google reviews.","type":"logo","src":"images/logos/h-and-h-law-group-mississauga.png","details":{"areas":["Family law","Corporate law","Real estate law","Wills and estates","Immigration law","Simple divorce","Separation agreements"],"serving":["Mississauga","Oakville","Peel","Halton","Greater Toronto Area","Ontario"]}}','{"1":[["09:00","18:00"]],"2":[["09:00","18:00"]],"3":[["09:00","18:00"]],"4":[["09:00","18:00"]],"5":[["09:00","18:00"]]}','H&H Law Group is a Mississauga firm covering family law, corporate law, real estate, wills and estates, and immigration for clients across Ontario.

Its offices are on Cawthra Road and at Village Centre Place in Mississauga, with a third in Oakville, and it serves Peel, Halton and the wider Greater Toronto Area, plus other clients by video. Family, business and property problems overlap, so one team handles them together. Lawyers offer service in English, Pashto, Urdu, Punjabi and Hindi. The firm provides clients with a written plan from the first meeting, and its real estate commentary examines title problems, closing costs, condominium status certificates and hidden defects.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('browne-criminal-defence-calgary','Browne Criminal Defence','Calgary','AB','ab-calgary',0,5,43,51.0363027,-114.0943785,'{"name":"Browne Criminal Defence","city":"Calgary","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"ab-calgary","province":"AB","lat":51.0363027,"lng":-114.0943785,"address":"1842 14 St SW, Calgary, AB T2T 3S9","phone":"+14033330992","rating":5,"count":43,"slug":"browne-criminal-defence-calgary","mapsUrl":"https://www.google.com/maps/search/Browne+Criminal+Defence+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1842+14+St+SW%2C+Calgary%2C+AB+T2T+3S9","website":"https://bcdlaw.ca","blurb":"Criminal Defence / Civil Litigation in Calgary. Rated 5.0 from 43 Google reviews.","type":"logo","src":"images/logos/browne-criminal-defence-calgary.webp","details":{"lawyers":[{"name":"Matt Browne"}],"areas":["Criminal defence","Assault","Assault causing bodily harm"],"serving":["Calgary"]}}',NULL,'Browne Criminal Defence is a Calgary practice where lawyer Matt Browne works only on criminal law in Alberta and British Columbia.

Before law school he earned a Bachelor of Science in Chemical Engineering at the University of Alberta and worked for oil and gas companies in North America and Southeast Asia, from heavy oil in Fort McMurray to natural gas in the Gulf of Thailand. He draws on that science background when forensic evidence is at issue in court, and he has appeared at all levels of court in both provinces. The practice involves disclosure analysis, explanation of the criminal process and strategy meetings.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('reich-law-calgary','Reich Law','Calgary','AB','ab-calgary',0,4.8,44,51.087635,-114.157957,'{"name":"Reich Law","city":"Calgary","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"ab-calgary","province":"AB","lat":51.087635,"lng":-114.157957,"address":"4935 40 Ave NW, Calgary, AB T3A 2N1","phone":"+14039844868","rating":4.8,"count":44,"slug":"reich-law-calgary","mapsUrl":"https://www.google.com/maps/search/Reich+Law+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=4935+40+Ave+NW%2C+Calgary%2C+AB+T3A+2N1","website":"https://www.reichlaw.ca","blurb":"Real Estate in Calgary. Rated 4.8 from 44 Google reviews.","type":"logo","src":"images/logos/reich-law-calgary.png","details":{"areas":["Real estate","Foreclosure","Restrictive covenants","Litigation","Commercial and residential property"],"serving":["Calgary","Alberta"]}}',NULL,'Reich Law is a Calgary real estate firm handling commercial and residential property work, including foreclosure, restrictive covenants and related litigation.

The firm was founded and is based in Calgary, Alberta, and has built a practice focused on its clients over many years, with nearly thirty years of commercial and residential real estate law experience. Its work is organized under four headings: real estate, foreclosure, restrictive covenants and litigation. The office is on 40 Avenue NW in northwest Calgary. The firm works to build long-lasting relationships with the people it represents.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('longfield-law-professional-corporation-brampton','Longfield Law Professional Corporation','Brampton','ON','peel-halton',0,4.8,44,43.6922418,-79.769101,'{"name":"Longfield Law Professional Corporation","city":"Brampton","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"peel-halton","province":"ON","lat":43.6922418,"lng":-79.769101,"address":"303 Main St N, Brampton, ON L6X 1N5","phone":"+19054528622","rating":4.8,"count":44,"slug":"longfield-law-professional-corporation-brampton","mapsUrl":"https://www.google.com/maps/search/Longfield+Law+Professional+Corporation+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=303+Main+St+N%2C+Brampton%2C+ON+L6X+1N5","website":"https://www.longfieldlaw.com","blurb":"Real Estate in Brampton. Rated 4.8 from 44 Google reviews.","type":"logo","src":"images/logos/longfield-law-professional-corporation-brampton.png","details":{"founded":1986,"lawyers":[{"name":"Randall A. Longfield"}],"areas":["Real estate law","Wills, estates and trusts","Corporate and business law","Residential and commercial real estate","Mortgage financing","Estate administration and probate"],"serving":["Brampton","Caledon","Bolton","Georgetown","Halton Hills","Oakville","Burlington","Mississauga"]}}',NULL,'Longfield Law Professional Corporation is a family-operated Brampton firm covering real estate, wills, estates and trusts, and corporate and business law.

Randall A. Longfield founded the firm in 1986, his son Michael joined in 2013, and Meaghan Longfield joined in 2019 to oversee the corporate department. Clients are served throughout Peel and Halton, including Caledon, Bolton, Georgetown, Halton Hills, Oakville, Burlington, Mississauga and Milton. Real estate work includes residential and commercial purchases and sales, mortgage financing and refinancing, private mortgages and title insurance. The estates side prepares wills and powers of attorney, and assists executors with administration and probate.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('demelo-heathcote-london','DeMelo Heathcote','London','ON','southwestern',0,4.6,45,42.9824211,-81.2382711,'{"name":"DeMelo Heathcote","city":"London","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"southwestern","province":"ON","lat":42.9824211,"lng":-81.2382711,"address":"275 Colborne St, London, ON N6B 2S7","phone":"+15192047966","rating":4.6,"count":45,"slug":"demelo-heathcote-london","mapsUrl":"https://www.google.com/maps/search/DeMelo+Heathcote+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=275+Colborne+St%2C+London%2C+ON+N6B+2S7","website":"https://www.demelolaw.com","blurb":"Criminal Defence in London. Rated 4.6 from 45 Google reviews.","type":"logo","src":"images/logos/demelo-heathcote-london.png","details":{"founded":2014,"lawyers":[{"name":"Cassandra DeMelo"},{"name":"Katie Heathcote","title":"Partner"}],"areas":["Criminal Code offences","Drug offences","Provincial and municipal offences","Appeals","Bail review hearings","Record suspensions"],"serving":["London","Southwestern Ontario"]}}',NULL,'DeMelo Heathcote is a London, Ontario criminal defence firm handling Criminal Code, drug and provincial offences, plus appeals, across Southwestern Ontario.

Cassandra DeMelo founded the firm in 2014 and Katie Heathcote became a partner in 2022; the firm now has fourteen people. Other lawyers include Shayne Stroud and Adriana D''Arpino. Its practice covers domestic charges, possession for the purpose of trafficking, regulatory and by-law matters, and appellate work up to the Supreme Court of Canada. Service is offered in English, French, Portuguese and Spanish, and the office is on Colborne Street in London.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('tarnow-criminal-law-richmond','Tarnow Criminal Law','Richmond','BC','bc-richmond',0,4.7,44,49.1699648,-123.1423539,'{"name":"Tarnow Criminal Law","city":"Richmond","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"bc-richmond","province":"BC","lat":49.1699648,"lng":-123.1423539,"address":"7340 Westminster Hwy Unit 210, Richmond, BC V6X 1A1","phone":"+16042780555","rating":4.7,"count":44,"slug":"tarnow-criminal-law-richmond","mapsUrl":"https://www.google.com/maps/search/Tarnow+Criminal+Law+Richmond+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7340+Westminster+Hwy+Unit+210%2C+Richmond%2C+BC+V6X+1A1","website":"https://www.tarnowcriminallaw.com","blurb":"Criminal Defence / Civil Litigation in Richmond. Rated 4.7 from 44 Google reviews.","type":"logo","src":"images/logos/tarnow-criminal-law-richmond.png","details":{"lawyers":[{"name":"David Tarnow"},{"name":"Jason Tarnow"}],"areas":["Criminal defence","Fraud","Drug possession","Sexual assault","Weapons trafficking","Unauthorized firearm possession"],"serving":["Richmond","Vancouver"]}}',NULL,'Tarnow Criminal Law is a Richmond, British Columbia criminal defence firm acting for people charged with offences throughout Metro Vancouver.

Brothers David Tarnow and Jason Tarnow lead the practice, which is full-service and draws on decades of combined criminal law experience. They are trial lawyers by nature who treat guilty pleas and plea bargains as a last resort. The firm appears in court in Vancouver, Surrey and Richmond, along with the wider region of British Columbia, and Yukon is also among its service areas. Emphasis is placed on Charter rights and the right to legal counsel. The office is on Westminster Highway in Richmond.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('avtar-bhangal-mississauga','Avtar Bhangal','Mississauga','ON','peel-halton',0,4.8,43,43.6399104,-79.7138532,'{"name":"Avtar Bhangal","city":"Mississauga","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"peel-halton","province":"ON","lat":43.6399104,"lng":-79.7138532,"address":"295 Derry Rd W, Mississauga, ON L5W 1G3","phone":"+14166164211","rating":4.8,"count":43,"slug":"avtar-bhangal-mississauga","mapsUrl":"https://www.google.com/maps/search/Avtar+Bhangal+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=295+Derry+Rd+W%2C+Mississauga%2C+ON+L5W+1G3","website":"https://www.bhangallaw.ca","blurb":"Criminal Defence / Civil Litigation in Mississauga. Rated 4.8 from 43 Google reviews.","type":"logo","src":"images/logos/avtar-bhangal-mississauga.webp","details":{"lawyers":[{"name":"Avtar Bhangal"},{"name":"Savena Bhangal"}],"areas":["Assaults","Sexual offences","Impaired driving","Fraud and theft","Drugs","Youth offence","Domestic assault","Internet crimes"],"serving":["Mississauga","GTA"]}}',NULL,'Avtar Bhangal practises as Bhangal Law, a Mississauga criminal defence firm handling assaults, impaired driving, fraud, theft and drug charges.

The firm''s lawyers have over thirty years of courtroom experience between them. Avtar Bhangal has been a member of the Law Society of Ontario, formerly the Law Society of Upper Canada, since 1994, and Savena Bhangal since 2022. The firm has handled thousands of criminal matters, keeps clients informed about their case, and guides them through the criminal justice process. The office is on Derry Road West in Mississauga, Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('tz-law-calgary','TZ Law','Calgary','AB','ab-calgary',0,5,41,51.0429453,-114.0760424,'{"name":"TZ Law","city":"Calgary","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"ab-calgary","province":"AB","lat":51.0429453,"lng":-114.0760424,"address":"638 11 Ave SW #200, Calgary, AB T2R 0E2","phone":"+15872105618","rating":5,"count":41,"slug":"tz-law-calgary","mapsUrl":"https://www.google.com/maps/search/TZ+Law+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=638+11+Ave+SW+%23200%2C+Calgary%2C+AB+T2R+0E2","website":"https://www.tzlawyers.ca","blurb":"Employment Law in Calgary. Rated 5.0 from 41 Google reviews.","type":"logo","src":"images/logos/tz-law-calgary.png","bioImage":"images/bio/tz-law-calgary.webp","details":{"areas":["Human rights","Wrongful dismissal","Constructive dismissal","Employment law","Severance negotiation","Employment litigation","Employment agreements","Workplace policies","Wrongful termination","Discrimination claims"],"serving":["Calgary","Alberta","British Columbia"]}}',NULL,'TZ Law is a Calgary boutique handling employment, human rights and privacy law for employees and employers across Alberta and British Columbia.

Its work covers wrongful termination, discrimination, privacy and contractual matters, and it advises people on whether to accept a severance offer or sign a release. It also acts for businesses, including start-ups and entrepreneurs dealing with growth, compliance and risk. Fee options are contingency, hourly and hybrid arrangements. The full range of services is provided in both English and Mandarin. The office is on 11 Avenue SW in downtown Calgary.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('dolgin-family-law-ottawa','Dolgin Family Law','Ottawa','ON','eastern',0,5,41,45.4161173,-75.6953848,'{"name":"Dolgin Family Law","city":"Ottawa","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"eastern","province":"ON","lat":45.4161173,"lng":-75.6953848,"address":"331 Somerset St W, Ottawa, ON K2P 0J8","phone":"+16138002218","rating":5,"count":41,"slug":"dolgin-family-law-ottawa","mapsUrl":"https://www.google.com/maps/search/Dolgin+Family+Law+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=331+Somerset+St+W%2C+Ottawa%2C+ON+K2P+0J8","website":"https://dolginfamilylaw.ca","blurb":"Family Law in Ottawa. Rated 5.0 from 41 Google reviews.","type":"logo","src":"images/logos/dolgin-family-law-ottawa.png","details":{"serving":["Ontario","Ottawa"]}}',NULL,'Dolgin Family Law is an Ottawa family practice led by Jeremy Dolgin, who acts for clients in Ottawa, elsewhere in Ontario and abroad.

He has practised family law for almost thirty years since graduating from the University of Toronto Faculty of Law in 1997. He represents clients at the Ontario Court of Justice, the Superior Court of Justice and the Ontario Court of Appeal. He is a trained mediator and a founding member of the collaborative law network of Ottawa, and many of his files are settled through non-adversarial processes. Gabriel Bidner is also on the team. The office is on Somerset Street West.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('the-law-offices-of-nikolas-j-lust-ottawa','The Law Offices of Nikolas J. Lust','Ottawa','ON','eastern',0,4.7,43,45.4161173,-75.6953848,'{"name":"The Law Offices of Nikolas J. Lust","city":"Ottawa","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"eastern","province":"ON","lat":45.4161173,"lng":-75.6953848,"address":"331 Somerset St W, Ottawa, ON K2P 0J8","phone":"+16132332542","rating":4.7,"count":43,"slug":"the-law-offices-of-nikolas-j-lust-ottawa","mapsUrl":"https://www.google.com/maps/search/The+Law+Offices+of+Nikolas+J.+Lust+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=331+Somerset+St+W%2C+Ottawa%2C+ON+K2P+0J8","website":"https://www.nikolaslust.com","blurb":"Criminal Defence in Ottawa. Rated 4.7 from 43 Google reviews.","type":"logo","src":"images/logos/the-law-offices-of-nikolas-j-lust-ottawa.webp","details":{"serving":["Ontario"]}}',NULL,'Nikolas Lust runs an Ottawa criminal defence practice focused on sexual assault, domestic assault, impaired driving and drug trafficking.

Nikolas Lust also represents clients charged with first-degree murder, firearms offences and aggravated assault, from students to professionals. The service model is built on video, telephone or in-person meetings, with documents exchanged and bills paid online, so clients can take part from home. The office is downtown at Somerset Street West, and the firm serves clients across Ontario. A blog series walks through the preliminary inquiry, court appearances and resolution.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('eidelmann-law-inc-montreal','Eidelmann Law Inc','Montreal','QC','qc-montreal',0,4.7,43,45.497555,-73.6593055,'{"name":"Eidelmann Law Inc","city":"Montreal","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"qc-montreal","province":"QC","lat":45.497555,"lng":-73.6593055,"address":"8000 Bd Décarie, Montréal, QC H4P 2S4","phone":"+15145386966","rating":4.7,"count":43,"slug":"eidelmann-law-inc-montreal","mapsUrl":"https://www.google.com/maps/search/Eidelmann+Law+Inc+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=8000+Bd+D%C3%A9carie%2C+Montr%C3%A9al%2C+QC+H4P+2S4","website":"https://www.eidelmannlaw.ca","blurb":"Personal Injury in Montreal. Rated 4.7 from 43 Google reviews.","type":"logo","src":"images/logos/eidelmann-law-inc-montreal.png","details":{"languages":["English","French"],"lawyers":[{"name":"Adam Eidelmann","title":"Owner"}],"areas":["Business law","Debt collection","Labour law","Litigation law","Real estate law"],"serving":["Montreal"]}}','{"1":[["09:00","17:30"]],"2":[["09:00","17:30"]],"3":[["09:00","17:30"]],"4":[["09:00","17:30"]],"5":[["09:00","17:30"]]}','Eidelmann Law Inc is a bilingual Montreal litigation boutique handling business, real estate, labour, debt collection and civil matters.

