INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('szakacs-law-injury-lawyers-calgary-calgary','Szakacs Law Injury Lawyers Calgary','Calgary','AB','ab-calgary',0,4.8,42,50.9893367,-114.0502489,'{"name":"Szakacs Law Injury Lawyers Calgary","city":"Calgary","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"ab-calgary","province":"AB","lat":50.9893367,"lng":-114.0502489,"address":"550 71 Ave SE Ste 240, Calgary, AB T2H 0H6","phone":"+15876008996","rating":4.8,"count":42,"slug":"szakacs-law-injury-lawyers-calgary-calgary","mapsUrl":"https://www.google.com/maps/search/Szakacs+Law+Injury+Lawyers+Calgary+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=550+71+Ave+SE+Ste+240%2C+Calgary%2C+AB+T2H+0H6","website":"https://szakacslaw.ca","blurb":"Personal Injury in Calgary. Rated 4.8 from 42 Google reviews.","type":"logo","src":"images/logos/szakacs-law-injury-lawyers-calgary-calgary.webp","details":{"lawyers":[{"name":"Dale Szakacs"},{"name":"Bridget Belsher"}],"areas":["Personal injury","Car accidents","Truck accidents","Motorcycle accidents","Pedestrian accidents","Rideshare accidents","Cyclists"],"serving":["Calgary","Edmonton","Alberta"]}}','{"1":[["09:00","16:30"]],"2":[["09:00","16:30"]],"3":[["09:00","16:30"]],"4":[["09:00","16:30"]],"5":[["09:00","16:30"]]}','Szakacs Law Injury Lawyers is a Calgary personal injury firm that represented people hurt in car, truck, motorcycle and pedestrian accidents.

Founder Dale Szakacs defended insurance companies before switching sides. The firm had offices in Calgary and Edmonton and served Red Deer, Lethbridge, St. Albert, Sherwood Park and St. Paul. Lawyers included Sandra C.M. Folkins and Bridget Belsher. Mr. Szakacs has retired after more than thirty-five years in practice, and the firm has transitioned its practice to Cuming & Gillespie LLP.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('portfolio-estate-law-etobicoke','Portfolio Estate Law','Etobicoke','ON','toronto',0,5,40,43.6452349,-79.5107757,'{"name":"Portfolio Estate Law","city":"Etobicoke","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"toronto","province":"ON","lat":43.6452349,"lng":-79.5107757,"address":"900 Royal York Rd, Etobicoke, ON M8Y 2V6","phone":"+14169935996","rating":5,"count":40,"slug":"portfolio-estate-law-etobicoke","mapsUrl":"https://www.google.com/maps/search/Portfolio+Estate+Law+Etobicoke+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=900+Royal+York+Rd%2C+Etobicoke%2C+ON+M8Y+2V6","website":"https://portfoliolaw.ca","blurb":"Wills & Estates in Etobicoke. Rated 5.0 from 40 Google reviews.","type":"logo","src":"images/logos/portfolio-estate-law-etobicoke.png","details":{"lawyers":[{"name":"Birute Luksenaite","title":"Founder"}],"areas":["Tax and estate planning","Estate administration","Trustee and fiduciary services","Power of attorney","Succession planning","Estate freezes","Family trusts","Estate trustee appointment"]}}',NULL,'Portfolio Estate Law is an Etobicoke firm handling tax and estate planning, estate administration and fiduciary services for international clients.

Founder Birute Luksenaite holds a law degree from Queen''s University and arts degrees from the University of Toronto, and articled at the Tax Court of Canada. She later worked in tax law at a national firm, a global accounting firm and a bank. The firm handles powers of attorney, family, spousal and alter ego trusts, estate freezes and beneficiary designations, offers tax and succession planning for artists'' estates, and assists vulnerable persons.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('jasmin-sandhu-immigration-lawyer-toronto-toronto','Jasmin Sandhu- Immigration Lawyer Toronto','Toronto','ON','toronto',0,5,39,43.6517618,-79.3813169,'{"name":"Jasmin Sandhu- Immigration Lawyer Toronto","city":"Toronto","featured":false,"tags":["Immigration","Civil Litigation"],"caseTypes":["immigration","litigation"],"region":"toronto","province":"ON","lat":43.6517618,"lng":-79.3813169,"address":"401 Bay St. Unit #1600, Toronto, ON M5H 2Y4","phone":"+14165462549","rating":5,"count":39,"slug":"jasmin-sandhu-immigration-lawyer-toronto-toronto","mapsUrl":"https://www.google.com/maps/search/Jasmin+Sandhu-+Immigration+Lawyer+Toronto+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=401+Bay+St.+Unit+%231600%2C+Toronto%2C+ON+M5H+2Y4","website":"https://www.jasminsandhu.com","blurb":"Immigration / Civil Litigation in Toronto. Rated 5.0 from 39 Google reviews.","type":"logo","src":"images/logos/jasmin-sandhu-immigration-lawyer-toronto-toronto.png","bioImage":"images/bio/jasmin-sandhu-immigration-lawyer-toronto-toronto.webp","details":{"languages":["English","Punjabi","Hindi"],"lawyers":[{"name":"Jasmin Sandhu"}],"areas":["Permanent residence","Refugee law","Appeals and refusals","Judicial review","Work permits","Study permits","Citizenship","Family sponsorship","Express Entry","Humanitarian applications"],"serving":["Toronto","Brampton","Mississauga","GTA"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Jasmin Sandhu Law is a Toronto immigration and refugee firm handling permanent residence, refugee cases, appeals, visas and citizenship.

The firm handles Express Entry, family sponsorship, humanitarian and compassionate applications, Ontario nominee programs, and work and study permits. Jasmin Sandhu is a member of the Law Society and an Ontario Notary Public, and belongs to JusticeNet and the Legal Aid panel. Ireesha Jethanandani, a licensed paralegal, is the first person clients meet. Areas served include Ajax, Woodbridge, Vaughan, Mississauga, Brampton, Whitby, Oshawa and Barrie, and the firm offers several language options.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('dunlap-criminal-defence-lawyer-edmonton-edmonton','Dunlap Criminal Defence Lawyer Edmonton','Edmonton','AB','ab-edmonton',0,4.6,42,53.540686,-113.4943596,'{"name":"Dunlap Criminal Defence Lawyer Edmonton","city":"Edmonton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-edmonton","province":"AB","lat":53.540686,"lng":-113.4943596,"address":"10117 Jasper Ave #606, Edmonton, AB T5J 1W8","phone":"+17804282267","rating":4.6,"count":42,"slug":"dunlap-criminal-defence-lawyer-edmonton-edmonton","mapsUrl":"https://www.google.com/maps/search/Dunlap+Criminal+Defence+Lawyer+Edmonton+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10117+Jasper+Ave+%23606%2C+Edmonton%2C+AB+T5J+1W8","website":"https://www.dunlapcriminaldefencelawyer.com","blurb":"Criminal Defence in Edmonton. Rated 4.6 from 42 Google reviews.","type":"logo","src":"images/logos/dunlap-criminal-defence-lawyer-edmonton-edmonton.png","bioImage":"images/bio/dunlap-criminal-defence-lawyer-edmonton-edmonton.webp","details":{"lawyers":[{"name":"Timothy Dunlap"}],"areas":["Sexual assault","Domestic violence","Sexual interference","Sexual offences","Criminal defence"],"serving":["Edmonton","Calgary","Grande Prairie","Fort McMurray","Alberta"]}}','{"1":[["09:00","16:30"]],"2":[["09:00","16:30"]],"3":[["09:00","16:30"]],"4":[["09:00","16:30"]],"5":[["09:00","16:30"]]}','Dunlap Criminal Defence is an Edmonton firm led by Timothy Dunlap, who defends sexual assault, sexual interference and domestic violence allegations.

Mr. Dunlap has more than thirty years of experience and has handled over three thousand trials. Services extend across Alberta, including Calgary, Grande Prairie and Fort McMurray. The firm''s process starts with guidance on what to do after a charge, including knowing your rights and staying silent. Fees are arranged under a contingency fee arrangement, and questions about fees and areas served are addressed in a frequently asked questions section.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('vallillee-family-lawyers-london','Vallillee Family Lawyers','London','ON','southwestern',0,4.6,42,42.9856912,-81.2487404,'{"name":"Vallillee Family Lawyers","city":"London","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"southwestern","province":"ON","lat":42.9856912,"lng":-81.2487404,"address":"200 Queens Ave Ste 440, London, ON N6A 1J3","phone":"+15194885263","rating":4.6,"count":42,"slug":"vallillee-family-lawyers-london","mapsUrl":"https://www.google.com/maps/search/Vallillee+Family+Lawyers+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=200+Queens+Ave+Ste+440%2C+London%2C+ON+N6A+1J3","website":"https://www.valaw.ca","blurb":"Family Law in London. Rated 4.6 from 42 Google reviews.","type":"logo","src":"images/logos/vallillee-family-lawyers-london.png","details":{"lawyers":[{"name":"Eric Vallillee"},{"name":"David Vallillee"}],"areas":["Separation agreements","Court and litigation","Voice of the child reports","Parenting, custody and access","Child support","Spousal support","Property and equalization","Pensions and retirement","Child protection"],"serving":["London","Southwestern Ontario"]}}',NULL,'Vallillee Family Lawyers is a London, Ontario boutique handling separation, divorce, parenting, support, property and Children''s Aid Society matters.

The firm accepts family cases at the London and St. Thomas courthouses, including motions to change and contempt motions, and matters involving the Children''s Aid Society of London & Middlesex. Services include separation agreements, court litigation, and Voice of the Child reports for children aged seven to fifteen, or older with special needs. Lawyer David is a Western University law graduate who also flies for the animal rescue charity Pilots4Paws. The firm acts for parents, grandparents and other family members.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('nichols-law-professional-corporation-markham','Nichols Law Professional Corporation','Markham','ON','york-durham',0,4.6,42,43.8799253,-79.2608577,'{"name":"Nichols Law Professional Corporation","city":"Markham","featured":false,"tags":["Real Estate","Wills & Estates","Business Law"],"caseTypes":["realestate","wills","business"],"region":"york-durham","province":"ON","lat":43.8799253,"lng":-79.2608577,"address":"161 Main Street Markham N, Markham, ON L3P 1Y2","phone":"+19052947780","rating":4.6,"count":42,"slug":"nichols-law-professional-corporation-markham","mapsUrl":"https://www.google.com/maps/search/Nichols+Law+Professional+Corporation+Markham+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=161+Main+Street+Markham+N%2C+Markham%2C+ON+L3P+1Y2","website":"https://www.markhamlaw.com","blurb":"Real Estate / Wills & Estates in Markham. Rated 4.6 from 42 Google reviews.","type":"logo","src":"images/logos/nichols-law-professional-corporation-markham.png","bioImage":"images/bio/nichols-law-professional-corporation-markham.webp","details":{"lawyers":[{"name":"Graham Nichols","title":"Partner"},{"name":"Keith Nichols","title":"Partner"},{"name":"Zeinab Khan","title":"Associate Lawyer"},{"name":"Ryan Dzingala","title":"Associate Lawyer"}],"areas":["Real estate law","Wills and estates","Business, corporate and commercial law","Notary public services","Estate administration","Powers of attorney","Home refinancing and private lending","Buying or selling a business"],"serving":["Markham"]}}',NULL,'Nichols Law Professional Corporation is a Markham firm covering real estate, wills, powers of attorney, business law and notary services.

The firm has served clients since 1983 and is run by partners Graham Nichols and Keith Nichols, with associates Zeinab Khan and Ryan Dzingala. Graham Nichols was admitted to the bar in 1983, served as president of the Markham Board of Trade, and chaired the Markham Stouffville Hospital board in 2001. He has practised on Markham Main Street since 1993. Its work covers home refinancing, private lending, executor duties, and starting a business, with clients ranging from young families to growing companies.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('family-lawyers-collective-llp-london','Family Lawyers Collective LLP','London','ON','southwestern',0,4.8,40,42.9856912,-81.2487404,'{"name":"Family Lawyers Collective LLP","city":"London","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"southwestern","province":"ON","lat":42.9856912,"lng":-81.2487404,"address":"200 Queens Ave Ste 301, London, ON N6A 1J3","phone":"+12267853130","rating":4.8,"count":40,"slug":"family-lawyers-collective-llp-london","mapsUrl":"https://www.google.com/maps/search/Family+Lawyers+Collective+LLP+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=200+Queens+Ave+Ste+301%2C+London%2C+ON+N6A+1J3","website":"https://flco.ca","blurb":"Family Law in London. Rated 4.8 from 40 Google reviews.","type":"logo","src":"images/logos/family-lawyers-collective-llp-london.png","details":{"lawyers":[{"name":"Jelena Buac"},{"name":"Louise M. Mimnagh"},{"name":"Alice Rho"}],"areas":["Domestic contracts and agreements","Divorce and common law separation","Decision-making and parenting time","Property claims and division","Spousal support","Child support"],"serving":["London"]}}',NULL,'Family Lawyers Collective LLP is a London, Ontario family law firm covering separation, divorce, parenting time, property division and domestic contracts.

Its lawyers are Jelena Buac, Louise M. Mimnagh and Alice Rho. Ms. Buac has practised only family law since 2015 and co-founded the firm as a partner. She has a particular interest in matters involving professional corporations, self-employed people and family businesses, and favours negotiation and mediation before court. The firm also serves clients with high net worth assets and income, and its articles explain separation agreements and what child support covers.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('nora-law-professional-corporation-london','Nora Law Professional Corporation','London','ON','southwestern',0,4.9,39,42.9811124,-81.2511519,'{"name":"Nora Law Professional Corporation","city":"London","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"southwestern","province":"ON","lat":42.9811124,"lng":-81.2511519,"address":"341 Talbot St, London, ON N6A 2R5","phone":"+15192000065","rating":4.9,"count":39,"slug":"nora-law-professional-corporation-london","mapsUrl":"https://www.google.com/maps/search/Nora+Law+Professional+Corporation+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=341+Talbot+St%2C+London%2C+ON+N6A+2R5","website":"https://www.noralaw.ca","blurb":"Family Law in London. Rated 4.9 from 39 Google reviews.","type":"logo","src":"images/logos/nora-law-professional-corporation-london.png","details":{"lawyers":[{"name":"Nora Eze"}],"areas":["Family law","Immigration and refugee matters","Child protection","Business law","Refugee claims","H&C and PRRA applications","Misrepresentation and refusals","Humanitarian and compassionate applications"],"serving":["London","Southwestern Ontario"]}}',NULL,'Nora Law Professional Corporation is a London, Ontario firm covering family, immigration and refugee, child protection and business law.

The firm acts for parents and caregivers in Children''s Aid Society proceedings, and handles refugee protection cases, humanitarian applications, PRRA matters, sponsorships, work and study permits and permanent residence applications. Business services include incorporations, shareholder agreements and contract drafting. Nora Eze is licensed in Ontario and Nigeria and has anti-money laundering compliance certification, and Krupa Patel is also on the team. The firm offers direct access to counsel and careful preparation.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('dominion-criminal-defence-london','Dominion Criminal Defence','London','ON','southwestern',0,4.9,39,42.9885538,-81.2382522,'{"name":"Dominion Criminal Defence","city":"London","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"southwestern","province":"ON","lat":42.9885538,"lng":-81.2382522,"address":"458 Queens Ave Second Floor, London, ON N6B 1X9","phone":"+12266675767","rating":4.9,"count":39,"slug":"dominion-criminal-defence-london","mapsUrl":"https://www.google.com/maps/search/Dominion+Criminal+Defence+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=458+Queens+Ave+Second+Floor%2C+London%2C+ON+N6B+1X9","website":"https://dominioncd.com","blurb":"Criminal Defence in London. Rated 4.9 from 39 Google reviews.","type":"logo","src":"images/logos/dominion-criminal-defence-london.png","details":{"areas":["Impaired driving","Sexual offences","Assault and domestic assault","Child offences","Youth criminal justice","Dangerous driving","Bail hearings","Drug offences"],"serving":["London","Kitchener","Brantford","Guelph","Southwestern Ontario"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Dominion Criminal Defence is a boutique London, Ontario firm practising only criminal law across London, Kitchener, Brantford and Guelph.

It was founded by lawyer Phillip P. Dinis and licensed paralegal Dallas Thompson, and the team includes Christina Hamp and legal clerk Madison Thompson. Its areas include impaired driving, assault and domestic assault, sexual offences and youth criminal law. It also represents clients in Woodstock and Cambridge, its lawyers have appeared at every level of court in Ontario, including the Court of Appeal, and an urgent line is answered at all hours. The office is in downtown London.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('maam-law-mississauga','Maam Law','Mississauga','ON','peel-halton',0,5,38,43.5923772,-79.6380369,'{"name":"Maam Law","city":"Mississauga","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"peel-halton","province":"ON","lat":43.5923772,"lng":-79.6380369,"address":"east Tower, 77 City Centre Dr Ste 501, Mississauga, ON L5B 1M5","phone":"+12898854786","rating":5,"count":38,"slug":"maam-law-mississauga","mapsUrl":"https://www.google.com/maps/search/Maam+Law+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=east+Tower%2C+77+City+Centre+Dr+Ste+501%2C+Mississauga%2C+ON+L5B+1M5","website":"https://maamlaw.com","blurb":"Real Estate in Mississauga. Rated 5.0 from 38 Google reviews.","type":"logo","src":"images/logos/maam-law-mississauga.webp","details":{"languages":["English","Urdu","Punjabi","Hindi"],"areas":["Family law","Wills and power of attorney","Real estate law","Immigration law","Elder abuse prevention","Notarization services"]}}',NULL,'Maam Law is a Mississauga firm offering family law, wills and powers of attorney, real estate, immigration, elder abuse prevention and notarization services.

Lawyer Nishtha Wadhwa moved to Canada in February 2018, passed the Ontario bar exams through the National Committee on Accreditation process, and was admitted to the Bar of Ontario on August 28, 2020. She also completed a postgraduate diploma in immigration law at Anderson College in North York. The office provides services in English, Urdu, Punjabi and Hindi, and Ms. Wadhwa works with culturally and ethnically diverse clients. Each practice area is set out in plain terms.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('pathfinder-law-abbotsford','Pathfinder Law','Abbotsford','BC','bc-fraser',0,5,37,49.0392256,-122.2937442,'{"name":"Pathfinder Law","city":"Abbotsford","featured":false,"tags":["Family Law","Civil Litigation"],"caseTypes":["family","litigation"],"region":"bc-fraser","province":"BC","lat":49.0392256,"lng":-122.2937442,"address":"2001 McCallum Rd #104, Abbotsford, BC V2S 3N3","phone":"+16048504685","rating":5,"count":37,"slug":"pathfinder-law-abbotsford","mapsUrl":"https://www.google.com/maps/search/Pathfinder+Law+Abbotsford+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2001+McCallum+Rd+%23104%2C+Abbotsford%2C+BC+V2S+3N3","website":"https://www.pathfinderlaw.ca","blurb":"Family Law / Civil Litigation in Abbotsford. Rated 5.0 from 37 Google reviews.","type":"logo","src":"images/logos/pathfinder-law-abbotsford.png","details":{"lawyers":[{"name":"Jas Boparai","title":"Associate Lawyer"}],"areas":["Divorce and separation","Child custody and parenting arrangements","Child and spousal support","Property division","Prenuptial and cohabitation agreements","Civil litigation","Wills and estates","Construction law","Strata law","Business law"],"serving":["Abbotsford","Langley","Chilliwack"]}}',NULL,'Pathfinder Law is an Abbotsford firm handling family law, divorce, civil litigation, construction, employment, wills and business matters.

Founder Timothy S. Bhullar has appeared in the Supreme Court of British Columbia, the Provincial Court and the British Columbia Court of Appeal, as well as before administrative tribunals. The firm serves families in Abbotsford, Langley, Chilliwack and surrounding areas on divorce, child and spousal support, custody and property division, and serves all of British Columbia. Construction work includes builders'' lien and delay matters.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('sirois-avocat-quebec-city','Sirois Avocat','Quebec City','QC','qc-quebec',0,4.9,37,46.7678109,-71.2888069,'{"name":"Sirois Avocat","city":"Quebec City","featured":false,"tags":["Immigration","Civil Litigation"],"caseTypes":["immigration","litigation"],"region":"qc-quebec","province":"QC","lat":46.7678109,"lng":-71.2888069,"address":"2828 Boul Laurier Bureaux 700, Québec City, Quebec G1V 0B9","phone":"+14185201036","rating":4.9,"count":37,"slug":"sirois-avocat-quebec-city","mapsUrl":"https://www.google.com/maps/search/Sirois+Avocat+Quebec+City+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2828+Boul+Laurier+Bureaux+700%2C+Qu%C3%A9bec+City%2C+Quebec+G1V+0B9","website":"https://www.siroisavocat.com","blurb":"Immigration / Civil Litigation in Quebec City. Rated 4.9 from 37 Google reviews.","type":"logo","src":"images/logos/sirois-avocat-quebec-city.webp","details":{"founded":2021,"lawyers":[{"name":"Me Émile Sirois"}],"areas":["Droit de l''immigration","Droit des affaires","Droit civil"]}}',NULL,'Sirois Avocat is a Quebec City firm practising immigration, business and civil law, founded in 2021 by Me Sirois.

He earned an LL.B. from Université Laval in 2019, has belonged to the Barreau du Québec since February 2020, and has focused on immigration in private practice. The firm''s approach rests on efficiency, personal service and information technology. Me Sirois received the 2021 firm start-up grant of the Jeune Barreau de Québec and has been a member of the Association québécoise des avocats et avocates en droit de l''immigration since 2020. He guides clients through temporary and permanent residence applications and helps entrepreneurs meet their legal obligations.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('red-booth-law-toronto','Red Booth Law','Toronto','ON','toronto',0,5,36,43.8113838,-79.2580452,'{"name":"Red Booth Law","city":"Toronto","featured":false,"tags":["Wills & Estates","Civil Litigation"],"caseTypes":["wills","litigation"],"region":"toronto","province":"ON","lat":43.8113838,"lng":-79.2580452,"address":"585 Middlefield Rd #15A, Scarborough, ON M1V 4Y5","phone":"+14169530040","rating":5,"count":36,"slug":"red-booth-law-toronto","mapsUrl":"https://www.google.com/maps/search/Red+Booth+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=585+Middlefield+Rd+%2315A%2C+Scarborough%2C+ON+M1V+4Y5","website":"https://www.redboothlaw.com","blurb":"Wills & Estates / Civil Litigation in Toronto. Rated 5.0 from 36 Google reviews.","type":"logo","src":"images/logos/red-booth-law-toronto.png","details":{"areas":["Estate litigation","Probate and estate administration","Wills and trusts","Powers of attorney","Guardianship","Estate planning"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Red Booth Law is a Toronto-area estates practice handling estate litigation, probate, wills, trusts and powers of attorney across Ontario.

The litigation side covers disputes over estate administration, the passing of estate trustee accounts, conflicts among beneficiaries, undue influence, upholding or challenging a will, and dependant''s relief. The firm also deals with probate and the appointment of estate trustees, and a Certificate of Appointment typically issues within two to three months. Guardianship appointments and living trusts are handled as well, and the firm publishes plain-language guides on the Ontario estate administration tax and on guardianship. The office is in Scarborough.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mark-chiu-law-kelowna','Mark Chiu Law','Kelowna','BC','bc-okanagan',0,5,36,49.8848348,-119.4953366,'{"name":"Mark Chiu Law","city":"Kelowna","featured":false,"tags":["Family Law","Criminal Defence"],"caseTypes":["family","criminal"],"region":"bc-okanagan","province":"BC","lat":49.8848348,"lng":-119.4953366,"address":"1630 Pandosy St #204, Kelowna, BC V1Y 1P7","phone":"+17789401425","rating":5,"count":36,"slug":"mark-chiu-law-kelowna","mapsUrl":"https://www.google.com/maps/search/Mark+Chiu+Law+Kelowna+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1630+Pandosy+St+%23204%2C+Kelowna%2C+BC+V1Y+1P7","website":"https://www.markchiu.com","blurb":"Family Law / Criminal Defence in Kelowna. Rated 5.0 from 36 Google reviews.","type":"logo","src":"images/logos/mark-chiu-law-kelowna.png","heroImage":"images/hero/mark-chiu-law-kelowna.webp","details":{"founded":2014,"lawyers":[{"name":"Mark J. Chiu"}],"areas":["Family law","Criminal law","Family law mediation","Division of family property","Parenting disputes","Support issues"],"serving":["Kelowna","British Columbia"]}}',NULL,'Mark Chiu Law is a Kelowna practice handling family law and criminal law matters in the Okanagan, the Kootenays and elsewhere in British Columbia.

The lawyer behind Mark J. Chiu Law Corp, Mark Chiu, has practised in British Columbia since 2014 and holds degrees in psychology from the University of Calgary and law from the University of Saskatchewan. He is also certified as a family law mediator through the Law Society of British Columbia. He has acted for the Public Prosecution Service of Canada, as defence counsel in serious matters, and in family cases involving the Family Maintenance Enforcement Program and the Ministry of Children and Family Development. Family work includes dividing property held through corporations or trusts and parenting disputes involving alienation.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('munro-and-crawford-vancouver','Munro & Crawford','Vancouver','BC','bc-vancouver',0,4.8,37,49.2351609,-123.1574071,'{"name":"Munro & Crawford","city":"Vancouver","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"bc-vancouver","province":"BC","lat":49.2351609,"lng":-123.1574071,"address":"5670 Yew St, Vancouver, BC V6M 3Y3","phone":"+16042667174","rating":4.8,"count":37,"slug":"munro-and-crawford-vancouver","mapsUrl":"https://www.google.com/maps/search/Munro+%26+Crawford+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5670+Yew+St%2C+Vancouver%2C+BC+V6M+3Y3","website":"https://munrocrawford.ca","blurb":"Wills & Estates in Vancouver. Rated 4.8 from 37 Google reviews.","type":"logo","src":"images/logos/munro-and-crawford-vancouver.png","details":{"founded":1952,"lawyers":[{"name":"Andrew Beesley"},{"name":"Peter Crawford"},{"name":"Katarina Tagliafero"},{"name":"Sabina Beesley"},{"name":"Cecelia Cheung"},{"name":"Winnie Tang"}],"areas":["Probate and estate administration","Wills and trusts","Business law","Real estate","Elder care"],"serving":["Vancouver","Kerrisdale","Richmond"]}}',NULL,'Munro & Crawford is a Kerrisdale firm in Vancouver handling wills, trusts, probate, real estate and business law since 1952.

The firm began as a single office opened by founding partner William Munro, and Peter Crawford joined him in 1973. Its client base has since spread across the Lower Mainland and to other provinces. Estate services include guidance for executors, wills and trusts, and elder care matters. On the business side it handles incorporation, acting as registered and records office, minute books, shareholder and joint venture agreements, and advice on purchases, sales and reorganizations.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('brett-mcgarry-criminal-law-ottawa','Brett McGarry Criminal Law','Ottawa','ON','eastern',0,4.9,36,45.4193633,-75.6905281,'{"name":"Brett McGarry Criminal Law","city":"Ottawa","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"eastern","province":"ON","lat":45.4193633,"lng":-75.6905281,"address":"116 Lisgar St #300, Ottawa, ON K2P 0C2","phone":"+16138848576","rating":4.9,"count":36,"slug":"brett-mcgarry-criminal-law-ottawa","mapsUrl":"https://www.google.com/maps/search/Brett+McGarry+Criminal+Law+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=116+Lisgar+St+%23300%2C+Ottawa%2C+ON+K2P+0C2","website":"https://www.mcgarrylaw.ca","blurb":"Criminal Defence / Civil Litigation in Ottawa. Rated 4.9 from 36 Google reviews.","type":"logo","src":"images/logos/brett-mcgarry-criminal-law-ottawa.png","details":{"languages":["English","French"],"lawyers":[{"name":"Brett McGarry"}],"areas":["Impaired driving","Domestic assault","Sexual assault","Drug offences","Firearms and weapons charges","Fraud and white collar crime","Theft and property offences","Bail hearings"],"serving":["Ottawa","Nepean","Kanata","Gloucester","Orleans","Barrhaven","Vanier","Gatineau"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Brett McGarry Criminal Law is an Ottawa defence firm handling impaired driving, sexual assault, drug and bail matters in Eastern Ontario.

Brett McGarry has been licensed by the Law Society of Ontario since 2008 and has more than 18 years of criminal defence practice in Ottawa and across the province. He acts for many clients who are professionals with no earlier involvement in the criminal justice system. The firm publishes case summaries involving Charter rulings and trials in the Superior Court, and its work on Ottawa impaired driving charges covers over 80, refusing a breath sample and care-and-control offences.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('grewal-law-firm-ottawa','Grewal Law Firm','Ottawa','ON','eastern',0,5,35,45.3479833,-75.9249665,'{"name":"Grewal Law Firm","city":"Ottawa","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"eastern","province":"ON","lat":45.3479833,"lng":-75.9249665,"address":"603 March Rd #200S, Kanata, ON K2K 2M5","phone":"+16132619897","rating":5,"count":35,"slug":"grewal-law-firm-ottawa","mapsUrl":"https://www.google.com/maps/search/Grewal+Law+Firm+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=603+March+Rd+%23200S%2C+Kanata%2C+ON+K2K+2M5","website":"https://grewallawfirm.ca","blurb":"Family Law in Ottawa. Rated 5.0 from 35 Google reviews.","type":"logo","src":"images/logos/grewal-law-firm-ottawa.webp","details":{"founded":2021,"areas":["Family law","Child protection","Court assistance","Relationship agreements","Mediation"],"serving":["Ottawa","Lanark County","Prescott","Russell","Cornwall","Embrun","Hawkesbury","Casselman"]}}',NULL,'Grewal Law Firm provides family law services in Ottawa and nearby areas, including separation, divorce, child support and parenting time.

Manraj (Manny) Grewal has practised since 2019 and founded the firm in 2021. Clients come from Ottawa, Lanark County, Prescott, Russell, Cornwall, L''Orignal, Embrun, Hawkesbury and Casselman. Services include decision-making authority, extraordinary expenses, division of assets, child protection matters involving the children''s aid society, court assistance, mediation, and cohabitation, prenuptial and postnuptial agreements. The firm tries to resolve matters through negotiation first and moves to court only when that is not possible. Its office is in Kanata.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('blw-injury-law-waterloo','BLW Injury Law','Waterloo','ON','waterloo-guelph',0,5,35,43.5115114,-80.5352254,'{"name":"BLW Injury Law","city":"Waterloo","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"waterloo-guelph","province":"ON","lat":43.5115114,"lng":-80.5352254,"address":"86 Rankin St Unit 2, Waterloo, ON N2V 1V9","phone":"+12264995287","rating":5,"count":35,"slug":"blw-injury-law-waterloo","mapsUrl":"https://www.google.com/maps/search/BLW+Injury+Law+Waterloo+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=86+Rankin+St+Unit+2%2C+Waterloo%2C+ON+N2V+1V9","website":"https://blwlaw.ca","blurb":"Personal Injury in Waterloo. Rated 5.0 from 35 Google reviews.","type":"logo","src":"images/logos/blw-injury-law-waterloo.png","details":{"areas":["Car accidents","Orthopaedic injuries","Slip and fall accidents","Motorcycle accidents","Public transit accidents","Pedestrian accidents","Dog bite incidents","Brain and spinal cord injuries","Personal injury"],"serving":["Waterloo"]}}','{"1":[["06:00","23:00"]],"2":[["06:00","23:00"]],"3":[["06:00","23:00"]],"4":[["06:00","23:00"]],"5":[["06:00","23:00"]],"6":[["06:00","23:00"]],"7":[["06:00","23:00"]]}','BLW Injury Law is a Waterloo personal injury firm handling car accidents, slip and falls, motorcycle and pedestrian injuries, and public transit accidents.

The firm is a member of the Barapp Law Alliance. Its practice also includes orthopaedic injuries and traumatic brain and spinal cord injuries, each with its own area of work. Clients are assigned a case manager and work on a contingency fee basis, meaning no fees are owed unless the case succeeds. Time limits apply to filing a public transit accident lawsuit, and several kinds of compensation may be available.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('modern-family-law-llp-toronto','Modern Family Law LLP','Toronto','ON','toronto',0,4.8,36,43.7306205,-79.419399,'{"name":"Modern Family Law LLP","city":"Toronto","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"toronto","province":"ON","lat":43.7306205,"lng":-79.419399,"address":"1810 Avenue Rd Ste 300, Toronto, ON M5M 3Z2","phone":"+16473486723","rating":4.8,"count":36,"slug":"modern-family-law-llp-toronto","mapsUrl":"https://www.google.com/maps/search/Modern+Family+Law+LLP+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1810+Avenue+Rd+Ste+300%2C+Toronto%2C+ON+M5M+3Z2","website":"https://modernfamilylaw.ca","blurb":"Family Law in Toronto. Rated 4.8 from 36 Google reviews.","type":"logo","src":"images/logos/modern-family-law-llp-toronto.png","details":{"areas":["Family law","Divorce"],"serving":["Toronto","Greater Toronto Area"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Modern Family Law LLP is a Toronto boutique handling divorce, separation agreements, parenting, support and property division across the GTA.

Practice areas include parenting time and decision-making, child and spousal support, common-law property disputes and family law appeals. The firm''s lawyers negotiate settlements, work through mediation and litigate in court. The team includes Stephanie Pasternak, Michael H. Tweyman, Rachel Nusinoff, Farzana Jiwani, Zachary Biggs and Gary Stern. Service areas include North York, Scarborough, Newmarket, Oshawa, Vaughan, Markham and Richmond Hill, and meetings can take place by video or audio link.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('nuraney-law-group-vancouver','Nuraney Law Group','Vancouver','BC','bc-vancouver',0,4.9,35,49.2847895,-123.1154251,'{"name":"Nuraney Law Group","city":"Vancouver","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"bc-vancouver","province":"BC","lat":49.2847895,"lng":-123.1154251,"address":"700 W Pender St Ste 303, Vancouver, BC V6C 1G8","phone":"+17789971104","rating":4.9,"count":35,"slug":"nuraney-law-group-vancouver","mapsUrl":"https://www.google.com/maps/search/Nuraney+Law+Group+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=700+W+Pender+St+Ste+303%2C+Vancouver%2C+BC+V6C+1G8","website":"https://nuraneylawgroup.com","blurb":"Wills & Estates in Vancouver. Rated 4.9 from 35 Google reviews.","type":"logo","src":"images/logos/nuraney-law-group-vancouver.webp","bioImage":"images/bio/nuraney-law-group-vancouver.webp","details":{"founded":2016,"lawyers":[{"name":"Arif S. Nuraney"}],"areas":["Corporate law","Small business law","Tax law","Wills and estates"],"serving":["Vancouver","West Vancouver","Lower Mainland","Metro Vancouver"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Nuraney Law Group is a boutique Vancouver firm handling corporate and commercial law, tax, and wills and estates for small businesses and individuals.

Managing partner Arif S. Nuraney established the firm in 2016. His work includes mergers and acquisitions, reorganizations, joint ventures, financings and due diligence for clients in hospitality, manufacturing, technology, construction, mining and infrastructure. He also acts for private equity and venture capital firms on investments. The firm has offices in downtown Vancouver and West Vancouver and serves clients across the Lower Mainland, including help with starting and incorporating a new business.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('pacific-legal-professional-corporation-toronto','Pacific Legal Professional Corporation','Toronto','ON','toronto',0,4.9,35,43.6489445,-79.3781401,'{"name":"Pacific Legal Professional Corporation","city":"Toronto","featured":false,"tags":["Business Law"],"caseTypes":["business"],"region":"toronto","province":"ON","lat":43.6489445,"lng":-79.3781401,"address":"1 King St W Suite 4800 -189, Toronto, ON M5H 1A1","phone":"+14166885567","rating":4.9,"count":35,"slug":"pacific-legal-professional-corporation-toronto","mapsUrl":"https://www.google.com/maps/search/Pacific+Legal+Professional+Corporation+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1+King+St+W+Suite+4800+-189%2C+Toronto%2C+ON+M5H+1A1","website":"https://pacificlegal.ca","blurb":"Business Law in Toronto. Rated 4.9 from 35 Google reviews.","type":"logo","src":"images/logos/pacific-legal-professional-corporation-toronto.webp","details":{"founded":2021,"lawyers":[{"name":"Avi Khanna","title":"Corporate Lawyer and Founder"}],"areas":["Corporate structuring and incorporation","Mergers and acquisitions","Commercial contracts","Corporate governance","Commercial real estate","Shareholder and partner agreements","Contract review","Artificial intelligence"],"serving":["Toronto","Ontario"]}}',NULL,'Pacific Legal is a Toronto corporate and commercial firm handling incorporations, shareholder agreements, acquisitions and real estate.

The firm was founded in 2021 by Avi Khanna, who worked at Toronto corporate firms on mergers and financings before starting it. Yash Mehrotra is also on the team. Work includes start-up representation, asset purchase agreements, creditors'' rights, contracts, shareholder and partnership agreements, buy-sell agreements, franchise matters and commercial technology transactions. It serves clients across Ontario in technology, real estate, e-commerce and professional services, from incorporation through to exit.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('la-rosee-avocat-inc-montreal','LA ROSÉE AVOCAT INC.','Montreal','QC','qc-montreal',0,5,34,45.5587247,-73.6673206,'{"name":"LA ROSÉE AVOCAT INC.","city":"Montreal","featured":false,"tags":["Family Law","Civil Litigation","Criminal Defence","Immigration"],"caseTypes":["family","litigation","criminal","immigration"],"region":"qc-montreal","province":"QC","lat":45.5587247,"lng":-73.6673206,"address":"815 Boulevard Henri-Bourassa E bureau 15, Montreal, Quebec H2C 1G1","phone":"+14389852286","rating":5,"count":34,"slug":"la-rosee-avocat-inc-montreal","mapsUrl":"https://www.google.com/maps/search/LA+ROS%C3%89E+AVOCAT+INC.+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=815+Boulevard+Henri-Bourassa+E+bureau+15%2C+Montreal%2C+Quebec+H2C+1G1","website":"https://laroseeavocatinc.com","blurb":"Family Law / Civil Litigation in Montreal. Rated 5.0 from 34 Google reviews.","type":"logo","src":"images/logos/la-rosee-avocat-inc-montreal.webp","details":{"areas":["Droit familial","Droit des obligations","Droit civil","Droit criminel","Droit d''immigration","Médiation aux petites créances"]}}',NULL,'La Rosée Avocat is a Montreal firm handling family, civil, criminal, housing and immigration law from Boulevard Henri-Bourassa Est.

The firm works in French and covers divorce, child custody and support, contract drafting and disputes, civil liability, criminal defence, visa applications and citizenship procedures. It also handles youth law, housing law, and mediation of small-amount disputes. Its values are transparency, integrity and respect, and it gives weight to the human side of legal work. It also gives private courses in law for people who need help in several subject areas.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('aftermath-law-criminal-defence-mississauga','Aftermath Law: Criminal Defence','Mississauga','ON','peel-halton',0,5,34,43.5749094,-79.621898,'{"name":"Aftermath Law: Criminal Defence","city":"Mississauga","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.5749094,"lng":-79.621898,"address":"250 Dundas St W Ste 402, Mississauga, ON L5B 1J2","phone":"+16472231980","rating":5,"count":34,"slug":"aftermath-law-criminal-defence-mississauga","mapsUrl":"https://www.google.com/maps/search/Aftermath+Law%3A+Criminal+Defence+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=250+Dundas+St+W+Ste+402%2C+Mississauga%2C+ON+L5B+1J2","website":"https://www.aftermathlaw.ca","blurb":"Criminal Defence in Mississauga. Rated 5.0 from 34 Google reviews.","type":"logo","src":"images/logos/aftermath-law-criminal-defence-mississauga.png","details":{"languages":["English","Punjabi","Hindi"],"lawyers":[{"name":"Dildeep Sahi"}],"areas":["Domestic assault","Bail hearings","Impaired driving","Intimate partner violence","Gun charges","Fraud","Assault with a weapon","Criminal defence"],"serving":["Mississauga","Brampton","Ontario"]}}',NULL,'Aftermath Law is a Mississauga criminal defence practice led by Dildeep Sahi, handling assault, domestic assault and sexual assault charges in Peel Region.

Dildeep Sahi trained at an Ontario Crown Attorney''s Office, and the firm takes urgent matters around the clock. Charges handled include assault with a weapon or causing bodily harm and aggravated assault. From its Mississauga office the firm serves thirteen Ontario communities, including Brampton, accepts Legal Aid and offers flat fees. Languages are English, Punjabi and Hindi, and a charge can affect release conditions, a record, travel and immigration status.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('barapp-law-firm-and-associates-ottawa','Barapp Law Firm and Associates','Ottawa','ON','eastern',0,4.8,35,45.3299815,-75.7055953,'{"name":"Barapp Law Firm and Associates","city":"Ottawa","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"eastern","province":"ON","lat":45.3299815,"lng":-75.7055953,"address":"43 Auriga Dr Ste 128, Nepean, ON K2E 7Y8","phone":"+18882145428","rating":4.8,"count":35,"slug":"barapp-law-firm-and-associates-ottawa","mapsUrl":"https://www.google.com/maps/search/Barapp+Law+Firm+and+Associates+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=43+Auriga+Dr+Ste+128%2C+Nepean%2C+ON+K2E+7Y8","website":"https://barappinjurylaw.ca","blurb":"Personal Injury in Ottawa. Rated 4.8 from 35 Google reviews.","type":"logo","src":"images/logos/barapp-law-firm-and-associates-ottawa.webp","details":{"areas":["Car accidents","Orthopaedic injuries","Slip and fall accidents","Motorcycle accidents","Public transit accidents","Pedestrian accidents","Dog bite incidents","Brain and spinal cord injuries","Personal injury"],"serving":["Grimsby","Nepean","Timmins"]}}',NULL,'Barapp Law Firm and Associates is a personal injury practice in Nepean, near Ottawa, also serving Grimsby and Timmins.

The firm is a member of the Barapp Law Alliance and handles car accidents, orthopaedic injuries, slip and fall, motorcycle, public transit and pedestrian cases. Eric Barapp, a graduate of Osgoode Hall Law School, leads a team that also includes Lorne Weinstock, Eti Taylor, Nabeel Sera, Michael Brill, Albert Wong and Aurora Mancuso. Each client has a case manager who stays involved throughout, and fees are payable only if the case succeeds.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ayoun-law-mississauga','Ayoun Law','Mississauga','ON','peel-halton',0,4.8,35,43.6217615,-79.6723364,'{"name":"Ayoun Law","city":"Mississauga","featured":false,"tags":["Family Law","Civil Litigation","Real Estate"],"caseTypes":["family","litigation","realestate"],"region":"peel-halton","province":"ON","lat":43.6217615,"lng":-79.6723364,"address":"25 Watline Ave GR 21, Mississauga, ON L4Z 2Z1","phone":"+19052322793","rating":4.8,"count":35,"slug":"ayoun-law-mississauga","mapsUrl":"https://www.google.com/maps/search/Ayoun+Law+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=25+Watline+Ave+GR+21%2C+Mississauga%2C+ON+L4Z+2Z1","website":"https://ayounlaw.com","blurb":"Family Law / Civil Litigation in Mississauga. Rated 4.8 from 35 Google reviews.","type":"logo","src":"images/logos/ayoun-law-mississauga.png","details":{"languages":["English","Urdu","Punjabi","Hindi","Polish"],"lawyers":[{"name":"Ayoun Haroon"},{"name":"Sabeeya Akram"}],"areas":["Family law","Real estate law","Immigration law","Estate planning","Civil litigation","Landlord and Tenant Board","Traffic tickets","Independent legal advice","Notary public"],"serving":["Mississauga","Greater Toronto Area","Ontario"]}}','{"1":[["09:30","19:00"]],"2":[["09:30","19:00"]],"3":[["09:30","19:00"]],"4":[["09:30","19:00"]],"5":[["09:30","19:00"]]}','Ayoun Law is a Mississauga firm handling family law, real estate, immigration, estate planning and civil litigation across the GTA.

Styled Ayoun & Sabeeya LLP, the firm was founded by Ayoun Haroon and Sabeeya Akram in 2018, and a licensed paralegal and notary later joined it for tribunal matters and notarizations. Landlord and Tenant Board matters, traffic tickets, independent legal advice and notary services are handled alongside its main practice areas. Lawyers advise in English, Urdu, Punjabi and Hindi, with an assistant supporting Polish-speaking clients. Fees are stated openly at $199 per half-hour after an introductory 15-minute intake, and service areas include Brampton, Oakville, Milton and Toronto.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('hansra-law-toronto','Hansra Law','Toronto','ON','toronto',0,4.9,34,43.6558668,-79.3819145,'{"name":"Hansra Law","city":"Toronto","featured":false,"tags":["Business Law"],"caseTypes":["business"],"region":"toronto","province":"ON","lat":43.6558668,"lng":-79.3819145,"address":"1 Dundas St W Suite 2500, Toronto, ON M5G 1Z3","phone":"+14165800345","rating":4.9,"count":34,"slug":"hansra-law-toronto","mapsUrl":"https://www.google.com/maps/search/Hansra+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1+Dundas+St+W+Suite+2500%2C+Toronto%2C+ON+M5G+1Z3","website":"https://www.hansralaw.ca","blurb":"Business Law in Toronto. Rated 4.9 from 34 Google reviews.","type":"logo","src":"images/logos/hansra-law-toronto.webp","details":{"lawyers":[{"name":"Sukhi Hansra","title":"Business & Franchise Lawyer"},{"name":"Daniel Rizzi","title":"Senior Corporate Lawyer"}],"areas":["Business law","Corporate law","Franchise law","Technology law","Raising capital","Partnerships and joint ventures","Software licensing","Private equity"],"serving":["Toronto","Ontario"]}}','{"1":[["09:00","18:00"]],"2":[["09:00","18:00"]],"3":[["09:00","18:00"]],"4":[["09:00","18:00"]],"5":[["09:00","18:00"]]}','Hansra Law is a Toronto business firm acting on incorporations, business sales and purchases, franchise agreements and commercial contracts.

The firm is led by Sukhi Hansra, a business and franchise lawyer who is a four-time entrepreneur with a background in restaurants, technology and AI. Daniel Rizzi is senior corporate lawyer, working on corporate and commercial law, business sales and acquisitions, and technology and SaaS matters. Its approach, business first, legal second, gives clients the scope, risks and cost in writing before they proceed. It handles Ontario matters for clients across Canada and abroad.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('pelsmakher-law-toronto','Pelsmakher Law','Toronto','ON','toronto',0,5,33,43.6547091,-79.3598465,'{"name":"Pelsmakher Law","city":"Toronto","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"toronto","province":"ON","lat":43.6547091,"lng":-79.3598465,"address":"507 King St E, Toronto, ON M5A 1M3","phone":"+16479920296","rating":5,"count":33,"slug":"pelsmakher-law-toronto","mapsUrl":"https://www.google.com/maps/search/Pelsmakher+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=507+King+St+E%2C+Toronto%2C+ON+M5A+1M3","website":"https://www.pelslaw.ca","blurb":"Employment Law in Toronto. Rated 5.0 from 33 Google reviews.","type":"logo","src":"images/logos/pelsmakher-law-toronto.png","details":{"lawyers":[{"name":"Simon Pelsmakher","title":"Founder & Principal Lawyer"}],"areas":["Wrongful dismissal","Constructive dismissal","Executive compensation","Human rights","Privacy","Occupational health and safety","Pensions and benefits","Severance review and negotiation","Employment contracts and policies","Employment standards"],"serving":["Toronto","North York","Scarborough","Etobicoke","Ontario"]}}',NULL,'Pelsmakher Law is a Toronto employment and labour firm acting for employees and employers on dismissal, human rights and contract matters.

Founder Simon Pelsmakher also advises on executive compensation, privacy, occupational health and safety, and pensions and benefits. For employees, work includes severance assessment and negotiation, employment contract analysis, employment standards issues such as unpaid wages and overtime, pregnancy and parental leave, and termination rules for federally regulated employees under the Canada Labour Code. For employers it helps manage workplace risk and policies. Acting for both sides shapes the firm''s strategy, and clients deal directly with their lawyer.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('robert-legal-montreal','Robert Légal','Montreal','QC','qc-montreal',0,4.9,33,45.5043685,-73.5576354,'{"name":"Robert Légal","city":"Montreal","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"qc-montreal","province":"QC","lat":45.5043685,"lng":-73.5576354,"address":"500 Place d''Armes Ste 2350, Montreal, Quebec H2Y 2W2","phone":"+15147556378","rating":4.9,"count":33,"slug":"robert-legal-montreal","mapsUrl":"https://www.google.com/maps/search/Robert+L%C3%A9gal+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=500+Place+d%27Armes+Ste+2350%2C+Montreal%2C+Quebec+H2Y+2W2","website":"https://www.robertlegal.ca","blurb":"Criminal Defence / Civil Litigation in Montreal. Rated 4.9 from 33 Google reviews.","type":"logo","src":"images/logos/robert-legal-montreal.jpg","details":{"lawyers":[{"name":"Me Anne-Geneviève Robert"}],"areas":["Droit criminel et pénal","Infractions d''ordre sexuel","Violence conjugale","Crimes économiques","Infractions liées aux stupéfiants","Conduite avec facultés affaiblies"],"serving":["Montréal"]}}','{"1":[["00:00","23:59"]],"2":[["00:00","23:59"]],"3":[["00:00","23:59"]],"4":[["00:00","23:59"]],"5":[["00:00","23:59"]],"6":[["00:00","23:59"]],"7":[["00:00","23:59"]]}','Robert Légal is a Montreal criminal and penal defence firm founded by Me Anne-Geneviève Robert, a graduate of the Université de Montréal.

The practice works in French and is devoted exclusively to criminal and penal defence, representing people charged at every stage, from the police investigation to trial. Files include offences against the person, sexual offences, domestic violence, economic crimes and drug offences. Me Robert sits on the board of the Association des avocats de la défense de Montréal-Longueuil-Laval and writes regularly on the blog of the Jeune Barreau. The firm''s office is on Place d''Armes, and its lawyers are available at any time.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('one-family-law-edmonton-divorce-law-edmonton','One Family Law Edmonton Divorce Law','Edmonton','AB','ab-edmonton',0,5,31,53.5511756,-113.5361656,'{"name":"One Family Law Edmonton Divorce Law","city":"Edmonton","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"ab-edmonton","province":"AB","lat":53.5511756,"lng":-113.5361656,"address":"10706 124 St Ste 205, Edmonton, AB T5M 0H1","phone":"+17809155735","rating":5,"count":31,"slug":"one-family-law-edmonton-divorce-law-edmonton","mapsUrl":"https://www.google.com/maps/search/One+Family+Law+Edmonton+Divorce+Law+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10706+124+St+Ste+205%2C+Edmonton%2C+AB+T5M+0H1","website":"https://www.onefamily.law","blurb":"Family Law in Edmonton. Rated 5.0 from 31 Google reviews.","type":"logo","src":"images/logos/one-family-law-edmonton-divorce-law-edmonton.png","details":{"lawyers":[{"name":"Melissa Bourgeois","title":"Family Lawyer, Founder"}],"areas":["Separation agreements","Child support","Spousal support","Parenting plans","Property and asset division","Divorce"],"serving":["Edmonton"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','One Family Law is an Edmonton family firm that helps separating couples reach a flat-fee separation agreement through one shared, neutral lawyer.

Founder Melissa Bourgeois created what the firm calls the One Lawyer Divorce Method, in which a single lawyer advises both spouses instead of each hiring opposing counsel. The model followed a two-year regulatory process and an 18-month pilot. A seven-step process takes most clients from first meeting to signed agreement in six to eight weeks, and the firm also handles uncontested divorce in Alberta. Cody Dub and Ashley Goodnough work alongside Melissa Bourgeois.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('chinook-law-calgary','Chinook Law','Calgary','AB','ab-calgary',0,5,30,51.076332,-114.0067966,'{"name":"Chinook Law","city":"Calgary","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"ab-calgary","province":"AB","lat":51.076332,"lng":-114.0067966,"address":"2750 22 St NE #208, Calgary, AB T2E 7L9","phone":"+15873553168","rating":5,"count":30,"slug":"chinook-law-calgary","mapsUrl":"https://www.google.com/maps/search/Chinook+Law+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2750+22+St+NE+%23208%2C+Calgary%2C+AB+T2E+7L9","website":"https://chinook.law","blurb":"Personal Injury in Calgary. Rated 5.0 from 30 Google reviews.","type":"logo","src":"images/logos/chinook-law-calgary.webp","details":{"areas":["Car accident claims","Personal injury litigation"]}}',NULL,'Chinook Law is a Calgary firm whose practice is limited to personal injury litigation arising from motor vehicle accidents in Alberta.

Car accident injury cases are the only area of law it handles. Clients include injured drivers, vehicle passengers, motorcyclists, cyclists, pedestrians, transit riders, and ride share and taxi passengers. Compensation categories include pain and suffering, loss of income and earning opportunity, out-of-pocket and housekeeping expenses, and medical costs. The firm keeps a limited case load, follows a digital-first policy and works on a contingency basis, so nothing is owed if no funds are recovered.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mtl-avocat-inc-montreal','MTL Avocat Inc.','Montreal','QC','qc-montreal',0,5,30,45.5029902,-73.5560243,'{"name":"MTL Avocat Inc.","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.5029902,"lng":-73.5560243,"address":"204 Rue du St.-Sacrement #300, Montreal, Quebec H2Y 2S9","phone":"+15144182636","rating":5,"count":30,"slug":"mtl-avocat-inc-montreal","mapsUrl":"https://www.google.com/maps/search/MTL+Avocat+Inc.+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=204+Rue+du+St.-Sacrement+%23300%2C+Montreal%2C+Quebec+H2Y+2S9","website":"https://www.mtl-avocats.ca","blurb":"Immigration in Montreal. Rated 5.0 from 30 Google reviews.","type":"logo","src":"images/logos/mtl-avocat-inc-montreal.png","details":{"lawyers":[{"name":"Mehdi Tenouri"}],"areas":["Immigration","Droit des affaires","Incorporation"]}}',NULL,'MTL Avocat Inc., also known as Mehdi Tenouri Legal, is a Montreal firm handling immigration to Canada and business law for individuals and companies.

The immigration side covers permanent residence, investor files, study permits and work permits, and the business side covers incorporation, shareholder disputes, commercial disputes, dissolution, bankruptcy and insolvency. The firm works in French and also offers guidance on cybersecurity and cybercrime for small businesses. Me Mehdi Tenouri practised for 12 years in France and taught business and banking law at the Paris bar school. He is an accredited mediator for small-amount civil disputes, and the firm has offices in Montreal and the Montérégie.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('nicola-circelli-law-london','Nicola Circelli Law','London','ON','southwestern',0,5,30,42.9884706,-81.2550018,'{"name":"Nicola Circelli Law","city":"London","featured":false,"tags":["Criminal Defence","Wills & Estates","Civil Litigation"],"caseTypes":["criminal","wills","litigation"],"region":"southwestern","province":"ON","lat":42.9884706,"lng":-81.2550018,"address":"585 Talbot St, London, ON N6A 2T2","phone":"+15196019977","rating":5,"count":30,"slug":"nicola-circelli-law-london","mapsUrl":"https://www.google.com/maps/search/Nicola+Circelli+Law+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=585+Talbot+St%2C+London%2C+ON+N6A+2T2","website":"https://nicolacircellilaw.com","blurb":"Criminal Defence / Wills & Estates in London. Rated 5.0 from 30 Google reviews.","type":"logo","src":"images/logos/nicola-circelli-law-london.webp","details":{"founded":2019,"lawyers":[{"name":"Nicola Circelli"}],"areas":["Impaired driving","Assault","Drug offences","Theft and fraud","Weapons offences","Bail hearings","Mental health law","Estate administration","Wills and powers of attorney","Ontario Review Board"]}}',NULL,'Nicola Circelli Law is a London, Ontario criminal defence practice handling impaired driving, assault, drug and fraud charges.

Nicola Circelli was admitted to the Ontario bar in 2016 after articling with Circelli Law. She holds a history degree from McGill, a law degree from the University of Leicester, and a master''s in international human rights law from the National University of Ireland, Galway. Practice areas also include weapons offences, bail hearings, mental health law, hearings for people found not criminally responsible, and the Consent and Capacity Board. The firm takes urgent matters at any hour, and impaired driving cases involve licence suspensions, impoundment and mandatory minimum penalties.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('haxell-law-oakville','Haxell Law','Oakville','ON','peel-halton',0,4.8,31,43.4719239,-79.6652489,'{"name":"Haxell Law","city":"Oakville","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"peel-halton","province":"ON","lat":43.4719239,"lng":-79.6652489,"address":"1276 Cornwall Rd C, Oakville, ON L6J 7W5","phone":"+19058450767","rating":4.8,"count":31,"slug":"haxell-law-oakville","mapsUrl":"https://www.google.com/maps/search/Haxell+Law+Oakville+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1276+Cornwall+Rd+C%2C+Oakville%2C+ON+L6J+7W5","website":"https://www.haxelllaw.com","blurb":"Real Estate / Wills & Estates in Oakville. Rated 4.8 from 31 Google reviews.","type":"logo","src":"images/logos/haxell-law-oakville.jpg","details":{"founded":1993,"lawyers":[{"name":"Jameson Glas"}],"areas":["Real estate law","Wills and estates","Estate planning","Probate","Notary and commissioner services"],"serving":["Oakville","Southern Ontario"]}}',NULL,'Haxell Law is an Oakville firm handling real estate transactions, wills, powers of attorney, probate applications and estate planning, with notary services.

The firm has served the Oakville community since 1993 and sits close to the QEW. Its lawyer Jameson Glas, who grew up in Oakville, holds a Juris Doctor from the University of Toronto, was admitted to the Ontario bar in 2014, and earlier practised civil litigation in Toronto with a focus on real estate, private loans and employment. The practice is barrister, solicitor and notary public work for clients in Oakville and the surrounding area.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('maana-law-mississauga','Maana Law','Mississauga','ON','peel-halton',0,4.9,29,43.6181961,-79.6732124,'{"name":"Maana Law","city":"Mississauga","featured":false,"tags":["Personal Injury","Civil Litigation"],"caseTypes":["injury","litigation"],"region":"peel-halton","province":"ON","lat":43.6181961,"lng":-79.6732124,"address":"90 Matheson Blvd W Ste 101, Mississauga, ON L5R 3R3","phone":"+14379794878","rating":4.9,"count":29,"slug":"maana-law-mississauga","mapsUrl":"https://www.google.com/maps/search/Maana+Law+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=90+Matheson+Blvd+W+Ste+101%2C+Mississauga%2C+ON+L5R+3R3","website":"https://www.maanalaw.com","blurb":"Personal Injury / Civil Litigation in Mississauga. Rated 4.9 from 29 Google reviews.","type":"logo","src":"images/logos/maana-law-mississauga.png","details":{"areas":["Car accident","Slip and fall accidents","Pedestrian accidents","Catastrophic accident","Motorcycle accidents","Dog bite incidents","Public transit accidents","Soft tissue and chronic pain","Brain injury","Civil litigation"],"serving":["Mississauga"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Maana Law is a Mississauga personal injury firm handling car accidents, slip and falls, pedestrian and motorcycle injuries.

The firm has more than ten years of experience, and Aman Kalra is its lead lawyer. Its practice also covers catastrophic accidents, dog bites, public transit accidents, soft tissue and chronic pain, and long-term disability matters. Meetings can be held virtually, and home or hospital visits are possible. It works on a contingency fee basis and serves neighbourhoods such as Erin Mills, Cooksville, Churchill Meadows, Meadowvale and City Centre.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lions-gate-law-corporation-vancouver','Lions Gate Law Corporation','Vancouver','BC','bc-vancouver',0,5,28,49.286722,-123.1252665,'{"name":"Lions Gate Law Corporation","city":"Vancouver","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"bc-vancouver","province":"BC","lat":49.286722,"lng":-123.1252665,"address":"1188 W Georgia St #950, Vancouver, BC V6E 4A2","phone":"+16046870023","rating":5,"count":28,"slug":"lions-gate-law-corporation-vancouver","mapsUrl":"https://www.google.com/maps/search/Lions+Gate+Law+Corporation+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1188+W+Georgia+St+%23950%2C+Vancouver%2C+BC+V6E+4A2","website":"https://lionsgatelaw.com","blurb":"Wills & Estates in Vancouver. Rated 5.0 from 28 Google reviews.","type":"logo","src":"images/logos/lions-gate-law-corporation-vancouver.png","details":{"areas":["Real estate","Conveyancing","Mortgage refinances","Incorporations","Corporate governance","Commercial transactions","Notarial services"]}}',NULL,'Lions Gate Law Corporation is a Vancouver firm handling real estate conveyancing, mortgage refinances, incorporations, and wills and estates.

Services include commercial conveyancing and mortgage refinances, and its lawyers are mobile. The firm''s office is on West Georgia Street in downtown Vancouver. Its lawyers hold degrees from the University of British Columbia, the London School of Economics and McGill University.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('s-athwal-law-professional-corporation-mississauga','S. Athwal Law Professional Corporation','Mississauga','ON','peel-halton',0,5,28,43.6597924,-79.6010213,'{"name":"S. Athwal Law Professional Corporation","city":"Mississauga","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.6597924,"lng":-79.6010213,"address":"2601 Matheson Blvd E Ste 38, Mississauga, ON L4W 5A8","phone":"+12895011851","rating":5,"count":28,"slug":"s-athwal-law-professional-corporation-mississauga","mapsUrl":"https://www.google.com/maps/search/S.+Athwal+Law+Professional+Corporation+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2601+Matheson+Blvd+E+Ste+38%2C+Mississauga%2C+ON+L4W+5A8","website":"https://athwallaw.ca","blurb":"Criminal Defence in Mississauga. Rated 5.0 from 28 Google reviews.","type":"logo","src":"images/logos/s-athwal-law-professional-corporation-mississauga.png","heroImage":"images/hero/s-athwal-law-professional-corporation-mississauga.webp","details":{"languages":["English","Hindi","Punjabi","Urdu"],"lawyers":[{"name":"Sahej Athwal"}],"areas":["Criminal defence","Domestic assault","Aggravated assault","Impaired driving","Sexual assault","Weapons and firearms","Drug offences","Property offences","Youth criminal justice"],"serving":["Ontario","Toronto"]}}','{"1":[["00:00","23:59"]],"2":[["00:00","23:59"]],"3":[["00:00","23:59"]],"4":[["00:00","23:59"]],"5":[["00:00","23:59"]],"6":[["00:00","23:59"]],"7":[["00:00","23:59"]]}','S.Athwal Law is a Mississauga criminal defence practice handling assault, impaired driving, sexual offence and weapons charges.

Sahej Athwal holds a Master of Laws from Osgoode Hall Law School and belongs to the Law Society of Ontario and the Criminal Lawyers'' Association. He appears at trial in the Ontario Court of Justice and the Superior Court of Justice and works in English, Hindi, Punjabi and Urdu. Practice areas also include drug offences, bail, property offences and youth criminal justice. The firm serves Toronto, Brampton, Vaughan, North York, Richmond Hill, Newmarket and Markham, and is available around the clock.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('avocat-criminel-montreal-montreal','Avocat Criminel Montréal','Montreal','QC','qc-montreal',0,4.8,29,45.5052109,-73.5536422,'{"name":"Avocat Criminel Montréal","city":"Montreal","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"qc-montreal","province":"QC","lat":45.5052109,"lng":-73.5536422,"address":"20 Rue St-Paul Ouest Bureau 203, Montreal, Quebec H2Y 1Y6","phone":"+15147005212","rating":4.8,"count":29,"slug":"avocat-criminel-montreal-montreal","mapsUrl":"https://www.google.com/maps/search/Avocat+Criminel+Montr%C3%A9al+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=20+Rue+St-Paul+Ouest+Bureau+203%2C+Montreal%2C+Quebec+H2Y+1Y6","website":"https://avocatcriminelmtl.ca","blurb":"Criminal Defence in Montreal. Rated 4.8 from 29 Google reviews.","type":"logo","src":"images/logos/avocat-criminel-montreal-montreal.png","bioImage":"images/bio/avocat-criminel-montreal-montreal.webp","details":{"lawyers":[{"name":"Me Julien Lespérance Hudon"},{"name":"Me Marilie Ouellet"},{"name":"Me Margot Boucaut"}],"areas":["Droit criminel","Violence conjugale","Proxénétisme","Crimes économiques","Crimes sexuels","Pornographie juvénile","Drogues","Crimes violents","Armes à feu","Meurtre"],"serving":["Montréal","Gatineau","Maniwaki","Québec"]}}',NULL,'Lespérance Avocats, operating as Avocat Criminel Montréal, is a criminal defence firm serving Montreal, Laval, Gatineau and Maniwaki in French and English.

The main office is in Old Montreal near Notre-Dame Basilica, with a second office in Gatineau and meetings in Maniwaki by appointment. The firm acts in criminal cases involving firearms, drugs, violence and domestic violence, and handles offences tied to sexual services and human trafficking. It accepts legal aid and takes a collaborative, organized approach to each file, with an administrative team that manages communication and case handling.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mcelroy-law-ottawa','McElroy Law','Ottawa','ON','eastern',0,4.9,27,45.4178355,-75.6907736,'{"name":"McElroy Law","city":"Ottawa","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"eastern","province":"ON","lat":45.4178355,"lng":-75.6907736,"address":"185 Somerset St W #305, Ottawa, ON K2P 1L9","phone":"+16134215058","rating":4.9,"count":27,"slug":"mcelroy-law-ottawa","mapsUrl":"https://www.google.com/maps/search/McElroy+Law+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=185+Somerset+St+W+%23305%2C+Ottawa%2C+ON+K2P+1L9","website":"https://www.mcelroylaw.ca","blurb":"Criminal Defence in Ottawa. Rated 4.9 from 27 Google reviews.","type":"logo","src":"images/logos/mcelroy-law-ottawa.webp","details":{"founded":2015,"lawyers":[{"name":"Anne-Marie McElroy"},{"name":"Dawn Dickinson","title":"Associate"}],"areas":["Criminal defence"]}}',NULL,'McElroy Law is an Ottawa criminal defence firm acting for people charged with offences, from bail hearings through trials and appeals.

Anne-Marie McElroy founded the firm in 2015, and associate Dawn Dickinson has since joined. Anne-Marie graduated from the University of Ottawa law school in 2009, was admitted to the bar in 2010 and has practised criminal law exclusively since. Her experience includes impaired driving, assault, theft and sexual offences. Outside the firm she supervises Pro Bono Students Canada projects, sits on the board of Circles of Support and Accountability, has taught first-year criminal law at the University of Ottawa, and mentors women in criminal defence. The firm also maintains a blog on new cases and legislation.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lydia-h-thomson-law-corporation-kelowna','Lydia H. Thomson Law Corporation','Kelowna','BC','bc-okanagan',0,4.7,28,49.8802815,-119.4612693,'{"name":"Lydia H. Thomson Law Corporation","city":"Kelowna","featured":false,"tags":["Family Law","Real Estate","Wills & Estates"],"caseTypes":["family","realestate","wills"],"region":"bc-okanagan","province":"BC","lat":49.8802815,"lng":-119.4612693,"address":"1631 Dickson Ave #540, Kelowna, BC V1Y 0B5","phone":"+12507170711","rating":4.7,"count":28,"slug":"lydia-h-thomson-law-corporation-kelowna","mapsUrl":"https://www.google.com/maps/search/Lydia+H.+Thomson+Law+Corporation+Kelowna+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1631+Dickson+Ave+%23540%2C+Kelowna%2C+BC+V1Y+0B5","website":"https://www.lydiathomsonlaw.ca","blurb":"Family Law / Real Estate in Kelowna. Rated 4.7 from 28 Google reviews.","type":"logo","src":"images/logos/lydia-h-thomson-law-corporation-kelowna.png","details":{"areas":["Family law","Family mediation","Wills and estates","Committeeship","Wills and powers of attorney","Probate and estate administration"],"serving":["Kelowna","West Kelowna","Lake Country"]}}',NULL,'Thomson Law is a small Kelowna firm centred on family law and family mediation, serving Kelowna, West Kelowna and Lake Country.

Lydia Thomson, whose practice operates as Lydia H. Thomson Law Corporation, opened the firm in the summer of 2007 after years at a local firm. She graduated from the University of Saskatchewan College of Law, has practised in Kelowna for 18 years and is accredited by the Law Society of British Columbia as a family law mediator. Other services are wills and estates, committeeship and residential conveyancing, along with help for parents involved with the Ministry. Brandon is another lawyer on the team, and many referrals come from past clients.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('sankoff-criminal-law-edmonton','Sankoff Criminal Law','Edmonton','AB','ab-edmonton',0,5,25,53.5235338,-113.4943152,'{"name":"Sankoff Criminal Law","city":"Edmonton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-edmonton","province":"AB","lat":53.5235338,"lng":-113.4943152,"address":"10171 Saskatchewan Dr NW Unit 414, Edmonton, AB T6E 6K3","phone":"+15873379133","rating":5,"count":25,"slug":"sankoff-criminal-law-edmonton","mapsUrl":"https://www.google.com/maps/search/Sankoff+Criminal+Law+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10171+Saskatchewan+Dr+NW+Unit+414%2C+Edmonton%2C+AB+T6E+6K3","website":"https://sankoffcriminallaw.com","blurb":"Criminal Defence in Edmonton. Rated 5.0 from 25 Google reviews.","type":"logo","src":"images/logos/sankoff-criminal-law-edmonton.jpg","details":{"areas":["Criminal trials","Criminal appeals","Consulting for lawyers","Jury charge reviews"]}}',NULL,'Sankoff Criminal Law is a boutique Edmonton criminal firm that handles complex trials and appeals for clients and supports other defence lawyers.

Its work includes criminal trials, criminal appeals, leave applications, jury charge analysis and consulting for lawyers, including preparing legal applications and strategic advice. Charges it handles include sexual assault, murder, fraud and theft, regulatory offences, drug offences, firearms offences, serious violent offences and youth criminal justice matters. Peter Sankoff is a lawyer other criminal counsel turn to on difficult points of evidence and appellate strategy. Steven Penney is Professor in Residence, assisting with research, and the team includes student lawyers.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('holmes-stephen-a-brampton','Holmes Stephen A','Brampton','ON','peel-halton',0,4.8,26,43.6815662,-79.7646979,'{"name":"Holmes Stephen A","city":"Brampton","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"peel-halton","province":"ON","lat":43.6815662,"lng":-79.7646979,"address":"180 Queen, Brampton, ON L6X 1A8","phone":"+19057963030","rating":4.8,"count":26,"slug":"holmes-stephen-a-brampton","mapsUrl":"https://www.google.com/maps/search/Holmes+Stephen+A+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=180+Queen%2C+Brampton%2C+ON+L6X+1A8","website":"https://www.stephenholmeslawoffice.com","blurb":"Real Estate in Brampton. Rated 4.8 from 26 Google reviews.","type":"logo","src":"images/logos/holmes-stephen-a-brampton.png","details":{"areas":["Real estate","Wills and estates","Wills and powers of attorney","Business law"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Stephen Holmes Law Office is a Brampton practice offering real estate, wills and estates, and business law in Peel, Halton and the GTA.

Listed in directories as Holmes Stephen A, the practice is led by a lawyer with 20 years of experience in residential purchases, sales and refinances, and 30 years in commercial real estate. Real estate is the first practice area, followed by wills and estates and business law.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('jason-wuttunee-criminal-defence-lawyer-calgary','Jason Wuttunee Criminal Defence Lawyer','Calgary','AB','ab-calgary',0,4.7,26,51.0466733,-114.0757746,'{"name":"Jason Wuttunee Criminal Defence Lawyer","city":"Calgary","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-calgary","province":"AB","lat":51.0466733,"lng":-114.0757746,"address":"645 7 Ave SW #2650, Calgary, AB T2P 4G8","phone":"+15876020970","rating":4.7,"count":26,"slug":"jason-wuttunee-criminal-defence-lawyer-calgary","mapsUrl":"https://www.google.com/maps/search/Jason+Wuttunee+Criminal+Defence+Lawyer+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=645+7+Ave+SW+%232650%2C+Calgary%2C+AB+T2P+4G8","website":"https://jwcriminaldefence.com","blurb":"Criminal Defence in Calgary. Rated 4.7 from 26 Google reviews.","type":"logo","src":"images/logos/jason-wuttunee-criminal-defence-lawyer-calgary.png","details":{"lawyers":[{"name":"Jason Wuttunee","title":"Barrister & Solicitor"}],"areas":["Criminal law","Homicide","Murder","Infanticide","Financial crimes","White-collar crimes","Appellate litigation"],"serving":["Calgary","Vancouver"]}}',NULL,'Jason Wuttunee is a Calgary criminal defence lawyer who represents people accused of homicide, drug offences, impaired driving and financial crimes.

Before opening his defence practice he spent eleven years as a Crown Prosecutor with Alberta Justice, handling hundreds of criminal matters including high-profile cases, and acted as appellate counsel before the Alberta Court of Appeal. He practises trial and appellate litigation in all areas of criminal law and in select civil matters. Separate practice areas cover first and second degree murder and infanticide, and white-collar offences such as embezzlement, tax evasion, securities fraud, money laundering and mortgage fraud.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('brass-law-office-ottawa','Brass Law Office','Ottawa','ON','eastern',0,4.7,26,45.4178355,-75.6907736,'{"name":"Brass Law Office","city":"Ottawa","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"eastern","province":"ON","lat":45.4178355,"lng":-75.6907736,"address":"185 Somerset St W #204, Ottawa, ON K2P 1L9","phone":"+16132385757","rating":4.7,"count":26,"slug":"brass-law-office-ottawa","mapsUrl":"https://www.google.com/maps/search/Brass+Law+Office+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=185+Somerset+St+W+%23204%2C+Ottawa%2C+ON+K2P+1L9","website":"https://www.brasslawoffice.ca","blurb":"Criminal Defence in Ottawa. Rated 4.7 from 26 Google reviews.","type":"logo","src":"images/logos/brass-law-office-ottawa.png","details":{"lawyers":[{"name":"Alan Brass"},{"name":"Shira Brass"}],"areas":["Criminal defence","Quasi-criminal offences"],"serving":["Ottawa"]}}',NULL,'Brass Law Office is an Ottawa criminal defence firm acting for people accused of criminal and quasi-criminal offences.

Its lawyers have practised for over 25 years. The firm defends allegations including murder, assault, mischief, robbery, fraud, sexual offences and driving charges. It retains outside professionals such as private investigators, DNA analysts, pathologists, toxicologists, blood spatter analysts and forensic accountants to support a case. It also seeks remedies for Charter breaches, including unlawful detentions and arrests, unreasonable searches and seizures, and violations of the right to counsel. The firm is on Somerset Street West.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('samy-ziada-avocat-montreal','Samy Ziada Avocat','Montreal','QC','qc-montreal',0,5,24,45.5044461,-73.5576923,'{"name":"Samy Ziada Avocat","city":"Montreal","featured":false,"tags":["Immigration","Civil Litigation","Business Law"],"caseTypes":["immigration","litigation","business"],"region":"qc-montreal","province":"QC","lat":45.5044461,"lng":-73.5576923,"address":"500 Place d''Armes, Montreal, Quebec H2Y 2W2","phone":"+14387388678","rating":5,"count":24,"slug":"samy-ziada-avocat-montreal","mapsUrl":"https://www.google.com/maps/search/Samy+Ziada+Avocat+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=500+Place+d%27Armes%2C+Montreal%2C+Quebec+H2Y+2W2","website":"https://www.zsavocats.com","blurb":"Immigration / Civil Litigation in Montreal. Rated 5.0 from 24 Google reviews.","type":"logo","src":"images/logos/samy-ziada-avocat-montreal.png","bioImage":"images/bio/samy-ziada-avocat-montreal.webp","details":{"lawyers":[{"name":"Me Samy Ziada"}],"areas":["Immobilier","Litige civil et commercial","Immigration","Droit des affaires"],"serving":["Montréal","Québec"]}}','{"1":[["09:00","20:00"]],"2":[["09:00","20:00"]],"3":[["09:00","20:00"]],"4":[["09:00","20:00"]],"5":[["09:00","20:00"]],"6":[["09:00","20:00"]],"7":[["09:00","20:00"]]}','Samy Ziada Avocat, also known as ZS Avocats, is a Montreal practice handling civil and commercial litigation, immigration and business law.

The firm works in French. Me Samy Ziada, a member of the Barreau du Québec, is one of the few Montreal lawyers combining immigration with civil and commercial litigation. Litigation work spans housing, employment, real estate and insurance disputes. Immigration files include sponsorship, asylum applications and temporary or permanent residence. The firm serves Montréal, Laval and the Rive-Nord and Rive-Sud, with an office on Place d''Armes, and meetings can be held in person or online.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kraska-law-mississauga','Kraska Law','Mississauga','ON','peel-halton',0,4.8,25,43.5998268,-79.6402613,'{"name":"Kraska Law","city":"Mississauga","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.5998268,"lng":-79.6402613,"address":"4310 Sherwoodtowne Blvd #102, Mississauga, ON L4Z 2G6","phone":"+14165545442","rating":4.8,"count":25,"slug":"kraska-law-mississauga","mapsUrl":"https://www.google.com/maps/search/Kraska+Law+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=4310+Sherwoodtowne+Blvd+%23102%2C+Mississauga%2C+ON+L4Z+2G6","website":"https://kraskalaw.ca","blurb":"Criminal Defence in Mississauga. Rated 4.8 from 25 Google reviews.","type":"logo","src":"images/logos/kraska-law-mississauga.jpg","details":{"lawyers":[{"name":"Robert Kraska"}],"areas":["Criminal defence","Criminal appeals","Notary public","Bail hearings","Traffic charges"]}}',NULL,'Kraska Law is a Mississauga firm led by former federal prosecutor Robert S. Kraska, offering criminal defence, criminal appeals and notary services.

Robert Kraska worked with the Public Prosecution Service of Canada before focusing his practice on criminal law, and the firm has over 40 years of combined defence and prosecution experience. Charges range from assault, impaired driving and theft to large frauds and traffic offences. Other services include wills, independent legal advice, record suspension applications, victim compensation applications and civil litigation. Services are offered in English and Polish, and the firm is available for bail hearings at all hours.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('iqbal-law-professional-corporation-mississauga','Iqbal Law Professional Corporation','Mississauga','ON','peel-halton',0,5,23,43.600829,-79.641196,'{"name":"Iqbal Law Professional Corporation","city":"Mississauga","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"peel-halton","province":"ON","lat":43.600829,"lng":-79.641196,"address":"55 Village Centre Pl #200, Mississauga, ON L4Z 1V9","phone":"+12896520529","rating":5,"count":23,"slug":"iqbal-law-professional-corporation-mississauga","mapsUrl":"https://www.google.com/maps/search/Iqbal+Law+Professional+Corporation+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=55+Village+Centre+Pl+%23200%2C+Mississauga%2C+ON+L4Z+1V9","website":"https://iqbalslaw.com","blurb":"Family Law in Mississauga. Rated 5.0 from 23 Google reviews.","type":"logo","src":"images/logos/iqbal-law-professional-corporation-mississauga.webp","details":{"languages":["English","Urdu","Punjabi","Hindi"],"lawyers":[{"name":"Nasar Iqbal","title":"Barrister & Solicitor"}],"areas":["Divorce","Spousal support","Family mediation","Independent legal advice","Separation agreements","Prenuptial agreements","Child custody and access","Marriage contracts","Cohabitation agreements","Child support"],"serving":["Mississauga","Greater Toronto Area","Oakville","Toronto"]}}',NULL,'Iqbal Law is a Mississauga family law practice led by Nasar Iqbal, handling divorce, custody, support and property division across the GTA.

Nasar Iqbal works as a sole practitioner after earlier work with downtown firms and the Ministry of the Attorney General. He speaks English, Urdu, Punjabi and Hindi and appears at all levels of Ontario courts. The firm acts for clients in Oakville, Hamilton, Newmarket, Oshawa, Barrie, Kitchener, Woodstock, Sarnia and London, and also offers unbundled services for self-represented people. Its work includes high-value asset division and parenting disputes, and it maintains a family law blog.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kedgeanchor-law-calgary','KedgeAnchor Law','Calgary','AB','ab-calgary',0,5,22,51.0473612,-114.0846058,'{"name":"KedgeAnchor Law","city":"Calgary","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"ab-calgary","province":"AB","lat":51.0473612,"lng":-114.0846058,"address":"1000 7 Ave SW #900, Calgary, AB T2P 5L5","phone":"+15873169777","rating":5,"count":22,"slug":"kedgeanchor-law-calgary","mapsUrl":"https://www.google.com/maps/search/KedgeAnchor+Law+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1000+7+Ave+SW+%23900%2C+Calgary%2C+AB+T2P+5L5","website":"https://kedgeanchorlaw.ca","blurb":"Employment Law in Calgary. Rated 5.0 from 22 Google reviews.","type":"logo","src":"images/logos/kedgeanchor-law-calgary.png","details":{"languages":["English","French","Hindi","Punjabi","Urdu","Spanish"],"areas":["Employment law and workplace disputes","Corporate and commercial advisory","Family law and separation planning","Real estate and property transactions","Wrongful dismissal","Constructive dismissal","Severance reviews","Workplace investigations","Shareholder agreements","Separation agreements"],"serving":["Calgary","Airdrie","Okotoks","Rural Alberta"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','KedgeAnchor Law is a Calgary firm handling employment law and workplace disputes, plus corporate, family, real estate and estate matters.

The firm draws on more than 23 years of practice across the United Kingdom, Nigeria and Canada, and Christie Eze is the lawyer behind it. Its employment practice covers severance, wrongful dismissal and workplace rights for Alberta professionals and employers. It operates as a modern law collective, and its practice areas include corporate and commercial advisory, family law and separation planning, real estate transactions, estate planning and administration, civil litigation and immigration.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('grayer-law-office-family-lawyer-vancouver','Grayer Law Office (Family Lawyer','Vancouver','BC','bc-vancouver',0,4.8,22,49.2718395,-123.0693101,'{"name":"Grayer Law Office (Family Lawyer","city":"Vancouver","featured":false,"tags":["Family Law","Business Law"],"caseTypes":["family","business"],"region":"bc-vancouver","province":"BC","lat":49.2718395,"lng":-123.0693101,"address":"1416 Commercial Dr #101, Vancouver, BC V5L 3X9","phone":"+16046282241","rating":4.8,"count":22,"slug":"grayer-law-office-family-lawyer-vancouver","mapsUrl":"https://www.google.com/maps/search/Grayer+Law+Office+%28Family+Lawyer+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1416+Commercial+Dr+%23101%2C+Vancouver%2C+BC+V5L+3X9","website":"https://www.grayerlaw.com","blurb":"Family Law / Business Law in Vancouver. Rated 4.8 from 22 Google reviews.","type":"logo","src":"images/logos/grayer-law-office-family-lawyer-vancouver.webp","details":{"areas":["Family law","Family mediation","Collaborative law","Negotiation","Divorce","Separation","Property division","Child and spousal support"],"serving":["East Vancouver"]}}',NULL,'Grayer Law Office is an East Vancouver family law firm on Commercial Drive offering family mediation, collaborative law, negotiation and litigation.

The aim is to settle cohabitation, separation and divorce issues with as little conflict and expense as possible, including parenting and children, property division, and child and spousal support. Patrick is a fully trained and accredited family mediator and a member of the Mediate BC Roster. In mediation, the participants shape the outcome rather than a court, with or without lawyers present.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('van-looyen-and-fallon-law-professional-corporation-hamilton','Van Looyen and Fallon Law Professional Corporation','Hamilton','ON','hamilton-niagara',0,4.8,22,43.2553707,-79.8710712,'{"name":"Van Looyen and Fallon Law Professional Corporation","city":"Hamilton","featured":false,"tags":["Family Law","Civil Litigation"],"caseTypes":["family","litigation"],"region":"hamilton-niagara","province":"ON","lat":43.2553707,"lng":-79.8710712,"address":"25 Main St W Suite 601, Hamilton, ON L8N 1E8","phone":"+13653249370","rating":4.8,"count":22,"slug":"van-looyen-and-fallon-law-professional-corporation-hamilton","mapsUrl":"https://www.google.com/maps/search/Van+Looyen+and+Fallon+Law+Professional+Corporation+Hamilton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=25+Main+St+W+Suite+601%2C+Hamilton%2C+ON+L8N+1E8","website":"https://www.vanlooyenandfallon.com","blurb":"Family Law / Civil Litigation in Hamilton. Rated 4.8 from 22 Google reviews.","type":"logo","src":"images/logos/van-looyen-and-fallon-law-professional-corporation-hamilton.webp","details":{"lawyers":[{"name":"Emily Van Looyen","title":"Partner"},{"name":"Patrick Fallon"}],"areas":["Family law","Separation agreements","Cohabitation agreements","Marriage contracts","Family litigation","Child protection"],"serving":["Hamilton","Brantford","Greater Hamilton Area"]}}',NULL,'Van Looyen and Fallon is a Hamilton family law firm that also serves Brantford and surrounding areas, practising family law exclusively.

The firm is run by a wife and husband team, Emily Van Looyen and Patrick Fallon. Emily has practised family law for eight years and appears in the Ontario Court of Justice, the Superior Court of Justice and Unified Family Courts. She is a trained Collaborative Practice professional, acts as an agent for the Office of the Children''s Lawyer, supervises for Pro Bono Students Canada and sits on the board of a Hamilton community agency. The team also includes a legal assistant and a law clerk, and the firm takes an organized, personal approach to each matter.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ebpc-personal-injury-lawyer-ottawa','EBPC Personal Injury Lawyer','Ottawa','ON','eastern',0,5,21,45.4561856,-75.5844856,'{"name":"EBPC Personal Injury Lawyer","city":"Ottawa","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"eastern","province":"ON","lat":45.4561856,"lng":-75.5844856,"address":"1010 Polytek St Unit 2, Gloucester, ON K1J 9H8","phone":"+18888444763","rating":5,"count":21,"slug":"ebpc-personal-injury-lawyer-ottawa","mapsUrl":"https://www.google.com/maps/search/EBPC+Personal+Injury+Lawyer+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1010+Polytek+St+Unit+2%2C+Gloucester%2C+ON+K1J+9H8","website":"https://ebpclaw.ca","blurb":"Personal Injury in Ottawa. Rated 5.0 from 21 Google reviews.","type":"logo","src":"images/logos/ebpc-personal-injury-lawyer-ottawa.png","details":{"areas":["Car accidents","Orthopaedic injuries","Slip and fall accidents","Motorcycle accidents","Public transit accidents","Pedestrian accidents","Dog bite incidents","Brain and spinal cord injuries","Personal injury"],"serving":["London","Belleville","Gloucester","Fergus"]}}',NULL,'EBPC Personal Injury Lawyer is a personal injury firm with an Ottawa-area office in Gloucester, also serving Fergus, London and Belleville.

The firm is a member of the Barapp Law Alliance and handles car accidents, orthopaedic injuries, slip and fall, motorcycle and public transit cases. Lorne Weinstock holds a psychology degree from York University and a law degree from Windsor, and was admitted to the Law Society of Upper Canada in 2002. He handles spinal and brain injuries from motor vehicle accidents and occupiers'' liability cases. Fees are payable only if the case succeeds.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('goldwyn-law-professional-corporation-markham','Goldwyn Law Professional Corporation','Markham','ON','york-durham',0,5,21,43.818985,-79.3487467,'{"name":"Goldwyn Law Professional Corporation","city":"Markham","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"york-durham","province":"ON","lat":43.818985,"lng":-79.3487467,"address":"7225 Woodbine Ave #1, Markham, ON L3R 1A3","phone":"+14168932723","rating":5,"count":21,"slug":"goldwyn-law-professional-corporation-markham","mapsUrl":"https://www.google.com/maps/search/Goldwyn+Law+Professional+Corporation+Markham+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7225+Woodbine+Ave+%231%2C+Markham%2C+ON+L3R+1A3","website":"https://www.goldwynlaw.ca","blurb":"Real Estate in Markham. Rated 5.0 from 21 Google reviews.","type":"logo","src":"images/logos/goldwyn-law-professional-corporation-markham.png","details":{"lawyers":[{"name":"Tushaar Kalra","title":"Managing Partner"},{"name":"Raman Saini","title":"Partner"}],"areas":["Real estate","Corporate and commercial","Secured lending","Wills and estates","Mortgage enforcement","Notarial services"]}}',NULL,'Goldwyn Law is a Markham firm handling real estate, corporate and commercial, secured lending, wills and estates, and mortgage enforcement.

Its work includes residential and commercial real estate closings, incorporations and start-up planning, financial services and secured lending transactions, and estate planning. It also addresses mortgage defaults from both the borrower and the lender side. Notary services for affidavits and statutory declarations are available, in person or virtually. The firm acts across Ontario, and its mission is to be a friendly and practical presence for first-time homebuyers, investors and entrepreneurs.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('muldoon-and-company-vancouver','Muldoon & Company','Vancouver','BC','bc-vancouver',0,4.8,21,49.2874901,-123.1170948,'{"name":"Muldoon & Company","city":"Vancouver","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"bc-vancouver","province":"BC","lat":49.2874901,"lng":-123.1170948,"address":"355 Burrard St #1205, Vancouver, BC V6C 2G8","phone":"+16049749749","rating":4.8,"count":21,"slug":"muldoon-and-company-vancouver","mapsUrl":"https://www.google.com/maps/search/Muldoon+%26+Company+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=355+Burrard+St+%231205%2C+Vancouver%2C+BC+V6C+2G8","website":"https://www.muldoonandcompany.com","blurb":"Criminal Defence in Vancouver. Rated 4.8 from 21 Google reviews.","type":"logo","src":"images/logos/muldoon-and-company-vancouver.png","details":{"areas":["Drug charges","Weapons and firearm offences","Assault charges","Sexual assault","Driving prohibitions"],"serving":["Vancouver","Lower Mainland"]}}',NULL,'Muldoon & Company are Vancouver trial lawyers handling criminal law, impaired driving, drug charges and personal injury.

The offices are in the historic Marine Building. Don Muldoon has practised since 1981. In 1982 he and Michael Bolton started the criminal firm Bolton & Muldoon, and that tradition continues. Work includes drug possession, trafficking and production, assault including spousal and sexual assault, Immediate Roadside Prohibitions and Administrative Driving Prohibitions. The firm is based in downtown Vancouver and handles cases throughout British Columbia, and its recent cases include a civil forfeiture matter.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('snow-lawyers-professional-corporation-london','Snow Lawyers Professional Corporation','London','ON','southwestern',0,5,20,42.9882996,-81.2533049,'{"name":"Snow Lawyers Professional Corporation","city":"London","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"southwestern","province":"ON","lat":42.9882996,"lng":-81.2533049,"address":"135 Albert St, London, ON N6A 1L9","phone":"+15194347669","rating":5,"count":20,"slug":"snow-lawyers-professional-corporation-london","mapsUrl":"https://www.google.com/maps/search/Snow+Lawyers+Professional+Corporation+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=135+Albert+St%2C+London%2C+ON+N6A+1L9","website":"https://snowlawyers.ca","blurb":"Criminal Defence in London. Rated 5.0 from 20 Google reviews.","type":"logo","src":"images/logos/snow-lawyers-professional-corporation-london.png","details":{"lawyers":[{"name":"Geoff Snow"},{"name":"Danielle D’Alonzo"}],"areas":["Impaired driving","Drugs","Guns and weapons","Assault","Domestic assault","Sexual assault"],"serving":["London","Southwestern Ontario"]}}',NULL,'Snow Lawyers is a London trial law firm defending impaired driving, drug, weapons and assault charges across southwestern Ontario.

The firm was established in 2019 and handles over 80, guns and weapons, domestic assault and sexual assault matters. Geoff Snow focuses on complex trials and applications in the Ontario Court of Justice and the Superior Court of Justice, and holds a Master of Laws in criminal law and procedure. The team also includes Danielle D''Alonzo and Delia Matias. The firm keeps clients'' privacy in mind and prepares for trials that last from hours to months.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lakeshore-law-oakville','Lakeshore Law','Oakville','ON','peel-halton',0,5,20,43.4472434,-79.6668841,'{"name":"Lakeshore Law","city":"Oakville","featured":false,"tags":["Business Law"],"caseTypes":["business"],"region":"peel-halton","province":"ON","lat":43.4472434,"lng":-79.6668841,"address":"277 Lakeshore Rd E #408, Oakville, ON L6J 6J3","phone":"+16479827714","rating":5,"count":20,"slug":"lakeshore-law-oakville","mapsUrl":"https://www.google.com/maps/search/Lakeshore+Law+Oakville+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=277+Lakeshore+Rd+E+%23408%2C+Oakville%2C+ON+L6J+6J3","website":"https://lakeshore.law","blurb":"Business Law in Oakville. Rated 5.0 from 20 Google reviews.","type":"logo","src":"images/logos/lakeshore-law-oakville.png","details":{"lawyers":[{"name":"Arjun Sekhon"},{"name":"Daniel Ibrahim"}],"areas":["Corporate and commercial law","Construction law","Criminal law","Family law","Civil litigation","Wills and estates","Immigration law","Employment law","Landlord and tenant law","Small claims matters"],"serving":["Oakville","Toronto","Halton Hills"]}}',NULL,'Lakeshore Law is an Oakville firm covering corporate and commercial law, construction, criminal, family and civil litigation, and immigration matters.

Arjun Sekhon graduated from the University of Windsor in 2021 and was admitted to the Ontario bar in 2022, with corporate, commercial, criminal, family and immigration work. Daniel Ibrahim, of counsel, practises litigation before the Ontario Court of Justice and Superior Court of Justice, with municipal, criminal, family and civil work, plus probate applications, wills and powers of attorney. The team has backgrounds in larger firms and in-house roles, and the firm takes on pro bono work and mentorship.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('fox-mcnevin-mackay-llp-lawyers-windsor','Fox McNevin MacKay LLP Lawyers','Windsor','ON','southwestern',0,4.8,20,42.28762,-83.0205065,'{"name":"Fox McNevin MacKay LLP Lawyers","city":"Windsor","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"southwestern","province":"ON","lat":42.28762,"lng":-83.0205065,"address":"2485 Ouellette Ave Ste 104, Windsor, ON N8X 1L5","phone":"+15192591820","rating":4.8,"count":20,"slug":"fox-mcnevin-mackay-llp-lawyers-windsor","mapsUrl":"https://www.google.com/maps/search/Fox+McNevin+MacKay+LLP+Lawyers+Windsor+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2485+Ouellette+Ave+Ste+104%2C+Windsor%2C+ON+N8X+1L5","website":"https://www.foxmcnevinmackay.com","blurb":"Family Law in Windsor. Rated 4.8 from 20 Google reviews.","type":"logo","src":"images/logos/fox-mcnevin-mackay-llp-lawyers-windsor.webp","details":{"lawyers":[{"name":"Tanya McNevin"}],"areas":["Separation and divorce","Child custody","Property division","Child and spousal support","Mediation and litigation"],"serving":["Windsor"]}}',NULL,'Fox McNevin MacKay LLP is a Windsor family law firm handling divorce, separation, property division, custody, access and support.

Its services include collaborative family law, marriage, separation and cohabitation agreements, uncontested divorce, mediation and arbitration, litigation and appeals. Tanya McNevin earned her law degree from the University of Windsor in 2010, was admitted to the Ontario bar in 2011 and spent ten years in the legal field beforehand. Thomas MacKay and Mary Fox are also part of the team. The firm develops a custom strategy with each client and uses mediation, collaborative processes and litigation.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('edh-law-peterborough','EDH Law','Peterborough','ON','simcoe-central',0,4.7,144,44.3004849,-78.3215171,'{"name":"EDH Law","city":"Peterborough","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"simcoe-central","province":"ON","lat":44.3004849,"lng":-78.3215171,"address":"195 Sherbrooke St, Peterborough, ON K9J 2N2","phone":"+17057483012","rating":4.7,"count":144,"slug":"edh-law-peterborough","mapsUrl":"https://www.google.com/maps/search/EDH+Law+Peterborough+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=195+Sherbrooke+St%2C+Peterborough%2C+ON+K9J+2N2","website":"https://edhlaw.ca","blurb":"Law firm in Peterborough. Rated 4.7 from 144 Google reviews.","type":"logo","src":"images/logos/edh-law-peterborough.png","bioImage":"images/bio/edh-law-peterborough.webp","details":{"founded":2015,"lawyers":[{"name":"Carly Ladouceur","title":"Lawyer"},{"name":"Nathan Higgins"},{"name":"Douglas F. Walker"}],"areas":["Real estate law","Wills and estates","Family law","Immigration law","Corporate law","Notarizing and commissioning"],"serving":["Bradford","Peterborough","The Kawarthas"]}}',NULL,'EDH Law is a general practice in Peterborough and Bradford covering real estate, wills, family, immigration and corporate law.

Formally Evans de Vries Higgins LLP, the firm is the successor to Evans & Evans, established in Bradford in 1894, and to the Peterborough practice of Douglas F. Walker, which has served the Kawarthas since 1974. Robert Evans, Jenivieve de Vries and Nathan Higgins merged their practices in April 2015, and Robert Evans retired at the end of 2019. The firm acts for buyers and sellers in mortgage and title matters, offers notarizing and commissioning, and holds original wills and powers of attorney prepared by lawyers of both earlier practices.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lamprey-law-professional-corporation-barrie','Lamprey Law Professional Corporation','Barrie','ON','simcoe-central',0,4.9,110,44.3945609,-79.6949704,'{"name":"Lamprey Law Professional Corporation","city":"Barrie","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"simcoe-central","province":"ON","lat":44.3945609,"lng":-79.6949704,"address":"174 Bayfield St, Barrie, ON L4M 3B5","phone":"+17057221114","rating":4.9,"count":110,"slug":"lamprey-law-professional-corporation-barrie","mapsUrl":"https://www.google.com/maps/search/Lamprey+Law+Professional+Corporation+Barrie+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=174+Bayfield+St%2C+Barrie%2C+ON+L4M+3B5","website":"https://lampreylaw.ca","blurb":"Real Estate / Wills & Estates in Barrie. Rated 4.9 from 110 Google reviews.","type":"logo","src":"images/logos/lamprey-law-professional-corporation-barrie.png","details":{"lawyers":[{"name":"Peter Lamprey"}],"areas":["Real estate","Wills and estates","Powers of attorney"],"serving":["Barrie","Simcoe County"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Lamprey Law is a Barrie firm handling real estate, mortgages, wills, powers of attorney and estate administration for clients in Barrie and Simcoe County.

Peter Lamprey graduated from Osgoode Hall Law School in 1979, began practising in 1981 and has worked exclusively in the Barrie area since. Jenna Goorts, an Osgoode graduate of 2017 who first worked at the firm as a summer student, practises real estate and wills and estates, and serves on a Simcoe County board for MADD Canada. After years in an early twentieth-century house on Worsley Street, the firm moved to Bayfield Street, where the office has parking and is wheelchair accessible.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('cootauco-law-office-st-catharines','Cootauco Law Office','St. Catharines','ON','hamilton-niagara',0,4.9,109,43.1600375,-79.2465686,'{"name":"Cootauco Law Office","city":"St. Catharines","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"hamilton-niagara","province":"ON","lat":43.1600375,"lng":-79.2465686,"address":"110 James St #206, St. Catharines, ON L2R 7E8","phone":"+12268848114","rating":4.9,"count":109,"slug":"cootauco-law-office-st-catharines","mapsUrl":"https://www.google.com/maps/search/Cootauco+Law+Office+St.+Catharines+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=110+James+St+%23206%2C+St.+Catharines%2C+ON+L2R+7E8","website":"https://www.cootauco.com","blurb":"Family Law in St. Catharines. Rated 4.9 from 109 Google reviews.","type":"logo","src":"images/logos/cootauco-law-office-st-catharines.webp","details":{"lawyers":[{"name":"Jerzy Cootauco","title":"Barrister, Solicitor & Notary"}],"areas":["Divorce and separation","Custody and access","Support issues","Child protection","Motions to change","Family law"],"serving":["Niagara Region","St. Catharines","Welland","Niagara Falls"]}}',NULL,'Cootauco Law Office is a Niagara family law firm that practises only divorce and family law, from child custody to separation agreements.

The office sits across from the courthouse in St. Catharines and also serves Welland and Niagara Falls. Jerzy Cootauco, who holds a J.D. from the University of Windsor and a B.A. from Western University, is empanelled with Legal Aid Ontario to accept certificates for family law and child protection matters. Areas include parenting time, child and spousal support, equalization, motions to change, uncontested divorce and foreign divorce opinion letters. The firm prefers settlement but litigates when needed, and uses technology to keep costs down.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bussey-ainsworth-lawyers-peterborough','Bussey Ainsworth Lawyers','Peterborough','ON','simcoe-central',0,5,106,44.295771,-78.3254893,'{"name":"Bussey Ainsworth Lawyers","city":"Peterborough","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"simcoe-central","province":"ON","lat":44.295771,"lng":-78.3254893,"address":"294 Rink St Ste 101, Peterborough, ON K9J 2K2","phone":"+17057490628","rating":5,"count":106,"slug":"bussey-ainsworth-lawyers-peterborough","mapsUrl":"https://www.google.com/maps/search/Bussey+Ainsworth+Lawyers+Peterborough+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=294+Rink+St+Ste+101%2C+Peterborough%2C+ON+K9J+2K2","website":"https://busseyainsworth.ca","blurb":"Real Estate / Wills & Estates in Peterborough. Rated 5.0 from 106 Google reviews.","type":"logo","src":"images/logos/bussey-ainsworth-lawyers-peterborough.png","details":{"founded":1988,"lawyers":[{"name":"Barry W. Bussey"}],"areas":["Real estate","Wills and estates","Charity and non-profit law","Powers of attorney","Business law","Farm and business succession","Civil litigation","Notarial services","Constitutional law"],"serving":["Peterborough","Kawarthas"]}}','{"1":[["08:00","17:30"]],"2":[["08:00","17:30"]],"3":[["08:00","17:30"]],"4":[["08:00","17:30"]],"5":[["08:00","15:00"]]}','Bussey Ainsworth Lawyers is a Peterborough firm serving the Kawarthas since 1988 in real estate, wills, estates, business and charity law.

A small, local firm, it has closed property purchases and sales across the Kawarthas for four decades, including homes, cottages and farms. Barry Bussey has appeared before the Supreme Court of Canada, holds a doctorate in law from Leiden University and has written on constitutional rights and religious liberty. The firm also advises charities on incorporation, governance and the Ontario Not-for-Profit Corporations Act transition, and its lawyers act as notaries public and commissioners of oaths.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('houlihan-law-sarnia','Houlihan Law','Sarnia','ON','southwestern',0,5,89,43.0045838,-82.3887166,'{"name":"Houlihan Law","city":"Sarnia","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"southwestern","province":"ON","lat":43.0045838,"lng":-82.3887166,"address":"640 Cathcart Blvd Unit 2, Sarnia, ON N7V 2N4","phone":"+15194912136","rating":5,"count":89,"slug":"houlihan-law-sarnia","mapsUrl":"https://www.google.com/maps/search/Houlihan+Law+Sarnia+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=640+Cathcart+Blvd+Unit+2%2C+Sarnia%2C+ON+N7V+2N4","website":"https://houlihanlaw.ca","blurb":"Real Estate / Wills & Estates in Sarnia. Rated 5.0 from 89 Google reviews.","type":"logo","src":"images/logos/houlihan-law-sarnia.png","details":{"areas":["Wills and trusts","Probate","Powers of attorney","Last will and testament"]}}',NULL,'Houlihan Law is a downtown Sarnia practice focused on real estate, mortgages, wills, powers of attorney and estate administration.

Spencer Houlihan was born and raised in Sarnia. He earned a law degree from Griffith University in 2014 after an honours degree in political science at Laurier, and was admitted to the Ontario bar in June 2017. The office also provides notary public services and uses technology to save clients time. Outside the office he has been a long-standing member of the Sarnia Saints Rugby and Football Club, serving on its board and as president in 2021.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('norton-law-pc-oshawa','Norton Law PC','Oshawa','ON','york-durham',0,5,87,43.8970379,-78.8629025,'{"name":"Norton Law PC","city":"Oshawa","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"york-durham","province":"ON","lat":43.8970379,"lng":-78.8629025,"address":"21 Simcoe St S, Oshawa, ON L1H 4G1","phone":"+16476167667","rating":5,"count":87,"slug":"norton-law-pc-oshawa","mapsUrl":"https://www.google.com/maps/search/Norton+Law+PC+Oshawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=21+Simcoe+St+S%2C+Oshawa%2C+ON+L1H+4G1","website":"https://norton-law.ca","blurb":"Criminal Defence in Oshawa. Rated 5.0 from 87 Google reviews.","type":"logo","src":"images/logos/norton-law-pc-oshawa.png","details":{"lawyers":[{"name":"Steve Norton"}],"areas":["Criminal defence"],"serving":["Ajax","Barrie","Richmond Hill"]}}','{"1":[["00:00","23:59"]],"2":[["00:00","23:59"]],"3":[["00:00","23:59"]],"4":[["00:00","23:59"]],"5":[["00:00","23:59"]],"6":[["00:00","23:59"]],"7":[["00:00","23:59"]]}','Norton Law PC is an Oshawa criminal defence practice led by Steve Norton, representing people charged with offences across the Greater Toronto Area.

Steve Norton earned a Juris Doctor at Bond University while completing a master''s in business administration in Australia, where he also clerked at criminal and commercial litigation firms. He holds a B.A. with honours from York University and is in good standing with the Law Society of Ontario and the Criminal Lawyers Association. Topics covered include bail hearings, police questioning, the presumption of innocence and the right to a bail hearing within 24 hours, with material for charges in Ajax and Richmond Hill.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('10-b-criminal-law-center-st-catharines','10(B) Criminal Law Center','St. Catharines','ON','hamilton-niagara',0,4.7,90,43.160038,-79.246569,'{"name":"10(B) Criminal Law Center","city":"St. Catharines","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"hamilton-niagara","province":"ON","lat":43.160038,"lng":-79.246569,"address":"110 James St 2nd floor, St. Catharines, ON L2R 7E8","phone":"+18888861022","rating":4.7,"count":90,"slug":"10-b-criminal-law-center-st-catharines","mapsUrl":"https://www.google.com/maps/search/10%28B%29+Criminal+Law+Center+St.+Catharines+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=110+James+St+2nd+floor%2C+St.+Catharines%2C+ON+L2R+7E8","website":"https://www.10blaw.com","blurb":"Criminal Defence in St. Catharines. Rated 4.7 from 90 Google reviews.","type":"logo","src":"images/logos/10-b-criminal-law-center-st-catharines.png","details":{"lawyers":[{"name":"Sidney Zarabi"}],"areas":["Criminal law","Bail hearings","Resolutions and diversion","Youth criminal justice","Mental health court","Indigenous Peoples Court"],"serving":["St. Catharines","Niagara Region","Hamilton","Halton Region"]}}',NULL,'10(B) Criminal Law Center is a Niagara criminal defence practice handling bail hearings, trials, youth court and impaired driving charges.

The office is in St. Catharines, and the practice is exclusively criminal defence, led by Sidney Zarabi. Areas of work include bail hearings, resolution and diversion, youth criminal justice, mental health and drug treatment court, Indigenous peoples court and trials. The firm also helps clients reach counselling, housing and employment programs. Zarabi has written commentary on Niagara''s justice system, including its detention centre and treatment court, and the firm is a member of the Ontario Trial Lawyers Association.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('white-macgillivray-lester-llp-thunder-bay','White Macgillivray Lester LLP','Thunder Bay','ON','northern',0,4.9,82,48.4345565,-89.2194275,'{"name":"White Macgillivray Lester LLP","city":"Thunder Bay","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"northern","province":"ON","lat":48.4345565,"lng":-89.2194275,"address":"1 Cumberland St S, Thunder Bay, ON P7B 2T1","phone":"+18073441000","rating":4.9,"count":82,"slug":"white-macgillivray-lester-llp-thunder-bay","mapsUrl":"https://www.google.com/maps/search/White+Macgillivray+Lester+LLP+Thunder+Bay+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1+Cumberland+St+S%2C+Thunder+Bay%2C+ON+P7B+2T1","website":"https://www.tbayinjurylaw.com","blurb":"Personal Injury in Thunder Bay. Rated 4.9 from 82 Google reviews.","type":"logo","src":"images/logos/white-macgillivray-lester-llp-thunder-bay.png","details":{"areas":["Personal injury","Slip and falls","Insurance disputes","Vehicle collisions","Long term disability"],"serving":["Northwestern Ontario"]}}',NULL,'White Macgillivray Lester LLP is a Thunder Bay personal injury firm serving clients across Northwestern Ontario.

Its areas of work include slip and falls, vehicle collisions, insurance disputes and long term disability, and its team consists of injury lawyers and agents. Its lawyers and staff live in the region, unlike firms headquartered in Toronto, and it has helped people from the Manitoba border in the west to Marathon in the east, as well as in the far northern communities. The office is at 1 Cumberland Street South, and Dan Lester is among its lawyers.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('miskin-law-peterborough','Miskin Law','Peterborough','ON','simcoe-central',0,4.6,75,44.3028218,-78.3286273,'{"name":"Miskin Law","city":"Peterborough","featured":false,"tags":["Personal Injury","Real Estate","Wills & Estates"],"caseTypes":["injury","realestate","wills"],"region":"simcoe-central","province":"ON","lat":44.3028218,"lng":-78.3286273,"address":"351 Charlotte St, Peterborough, ON K9J 2W1","phone":"+17057557363","rating":4.6,"count":75,"slug":"miskin-law-peterborough","mapsUrl":"https://www.google.com/maps/search/Miskin+Law+Peterborough+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=351+Charlotte+St%2C+Peterborough%2C+ON+K9J+2W1","website":"https://www.miskinlaw.ca","blurb":"Personal Injury / Real Estate in Peterborough. Rated 4.6 from 75 Google reviews.","type":"logo","src":"images/logos/miskin-law-peterborough.png","bioImage":"images/bio/miskin-law-peterborough.webp","details":{"founded":1981,"lawyers":[{"name":"Murray H. Miskin","title":"Personal Injury Lawyer"},{"name":"Chris Goddard"},{"name":"Daniel Miskin"},{"name":"Phil Ugnat"}],"areas":["Personal injury","Wills and estates","Corporate and commercial law","Real estate law","Class actions","Mesothelioma claims","Nursing home negligence","Business formation","Mergers and acquisitions"],"serving":["Peterborough","Toronto","Oshawa"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Miskin Law is a Peterborough firm handling personal injury, asbestos and mesothelioma matters, class actions, real estate, corporate law and estates.

The firm has served Canadians since 1981 and keeps offices in Peterborough, Toronto and Oshawa. Personal injury work is aimed at Ontario residents, while mesothelioma and class action matters are taken on for people across the country. Mesothelioma compensation in Canada generally comes through asbestos trusts, and the firm publishes articles on work history affidavits. Founder Murray Miskin is a plaintiff''s personal injury lawyer with more than 40 years of practice and involvement with the Canadian Bar Association and the ADR Institute of Canada. Injury cases are handled on contingency, and the firm also prepares wills and estate plans.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('tlc-family-law-prince-george','TLC Family Law','Prince George','BC','bc-north',0,4.8,67,53.9199902,-122.7556322,'{"name":"TLC Family Law","city":"Prince George","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"bc-north","province":"BC","lat":53.9199902,"lng":-122.7556322,"address":"1896 3rd Ave, Prince George, BC V2M 1G4","phone":"+12505633630","rating":4.8,"count":67,"slug":"tlc-family-law-prince-george","mapsUrl":"https://www.google.com/maps/search/TLC+Family+Law+Prince+George+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1896+3rd+Ave%2C+Prince+George%2C+BC+V2M+1G4","website":"https://www.tlc-law.ca","blurb":"Family Law in Prince George. Rated 4.8 from 67 Google reviews.","type":"logo","src":"images/logos/tlc-family-law-prince-george.webp","details":{"lawyers":[{"name":"Tracy L. Clark"}],"areas":["Family law","Divorce","Child and spousal support"],"serving":["Prince George"]}}',NULL,'TLC Family Law Practice is a Prince George firm handling divorce, parenting arrangements, support and property division under British Columbia family law.

The practice also has offices in Parksville and serves the Nanaimo and Qualicum area. Tracy L. Clark is a family lawyer with over 30 years in practice. The firm''s primary aim is to settle matters by agreement quickly and efficiently, while taking cases to court when that is necessary. Services include flat fee agreements, uncontested divorces, guardianship, parenting time and access, child and spousal support, variation of existing orders, pension and property division, family debt, and cohabitation, marriage and prenuptial agreements.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('andrews-donnelly-llp-kingston','Andrews Donnelly LLP','Kingston','ON','eastern',0,4.7,66,44.2595867,-76.5203935,'{"name":"Andrews Donnelly LLP","city":"Kingston","featured":false,"tags":["Family Law","Civil Litigation"],"caseTypes":["family","litigation"],"region":"eastern","province":"ON","lat":44.2595867,"lng":-76.5203935,"address":"1471 John Counter Blvd #302, Kingston, ON K7M 8S8","phone":"+16135313032","rating":4.7,"count":66,"slug":"andrews-donnelly-llp-kingston","mapsUrl":"https://www.google.com/maps/search/Andrews+Donnelly+LLP+Kingston+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1471+John+Counter+Blvd+%23302%2C+Kingston%2C+ON+K7M+8S8","website":"https://www.andrewsdonnellylaw.ca","blurb":"Family Law / Civil Litigation in Kingston. Rated 4.7 from 66 Google reviews.","type":"logo","src":"images/logos/andrews-donnelly-llp-kingston.png","details":{"areas":["Family law","Civil litigation","Estate litigation","Dispute resolution"],"serving":["Kingston","Brockville","Napanee","Belleville","Picton","Prince Edward County"]}}',NULL,'Andrews Donnelly LLP is a Kingston boutique firm handling family law, estate litigation and civil litigation.

Its dispute resolution services are available in Kingston, Frontenac County, Prince Edward County and surrounding areas, including Brockville, Napanee, Belleville and Picton. Family work covers custody, access, child and spousal support and division of property. Estate litigation covers will challenges, power of attorney disputes, capacity questions and the passing of fiduciary accounts. Its lawyers include Paul and Whitney, and fees can be arranged as fixed-fee or project-based billing, hourly engagements, or monthly retainers.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('le-cabinet-m-saint-jerome','Le Cabinet M','Saint-Jerome','QC','qc-laval-laurentides',0,4.7,61,45.7813845,-74.0070234,'{"name":"Le Cabinet M","city":"Saint-Jerome","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"qc-laval-laurentides","province":"QC","lat":45.7813845,"lng":-74.0070234,"address":"484 Rue Laviolette, Saint-Jérôme, QC J7Y 2T9","phone":"+15143853876","rating":4.7,"count":61,"slug":"le-cabinet-m-saint-jerome","mapsUrl":"https://www.google.com/maps/search/Le+Cabinet+M+Saint-Jerome+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=484+Rue+Laviolette%2C+Saint-J%C3%A9r%C3%B4me%2C+QC+J7Y+2T9","website":"https://www.lecabinetm.com","blurb":"Law firm in Saint-Jerome. Rated 4.7 from 61 Google reviews.","type":"logo","src":"images/logos/le-cabinet-m-saint-jerome.webp","details":{"areas":["Dommages corporels","Accident de la route","Accident de travail","Maladie professionnelle","Victime d’acte criminel","Erreur médicale","Assurance invalidité","Demande de rente"],"serving":["Saint-Jérôme","Laval","Longueuil","Montréal"]}}',NULL,'Le Cabinet M is a Saint-Jerome firm that acts for people seeking compensation after an accident, a crime or a disability.

Founded in 1980, the firm works only on compensation matters: road accidents handled through the SAAQ, workplace accidents and occupational diseases before the CNESST, victims of crime (IVAC), pension applications to Retraite Québec, medical errors, disability insurance and childhood family violence. Its lawyers and their team act across Quebec, including the Greater Montreal area, and the firm works in French.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('casselman-legal-sarnia','Casselman Legal','Sarnia','ON','southwestern',0,4.9,58,43.0045838,-82.3887166,'{"name":"Casselman Legal","city":"Sarnia","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"southwestern","province":"ON","lat":43.0045838,"lng":-82.3887166,"address":"640 Cathcart Blvd Unit 2, Sarnia, ON N7V 2N4","phone":"+12267849804","rating":4.9,"count":58,"slug":"casselman-legal-sarnia","mapsUrl":"https://www.google.com/maps/search/Casselman+Legal+Sarnia+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=640+Cathcart+Blvd+Unit+2%2C+Sarnia%2C+ON+N7V+2N4","website":"https://casselmanlegal.com","blurb":"Real Estate in Sarnia. Rated 4.9 from 58 Google reviews.","type":"logo","src":"images/logos/casselman-legal-sarnia.png","details":{"areas":["Real estate","Wills","Powers of attorney","Estate planning","Business law"],"serving":["Sarnia"]}}',NULL,'Casselman Legal is a Sarnia firm handling residential and commercial real estate, wills and powers of attorney, and business law.

The firm serves Sarnia and the surrounding area. On the business side it handles company formation and corporate governance, and on the estates side it prepares wills under Ontario''s Succession Law Reform Act, including guardianship provisions for children and the distribution of property. The team uses modern legal technology to streamline processes and lower costs, and communication and integrity are the foundations of the practice. The office is at 640 Cathcart Boulevard in Sarnia.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lemieux-litigation-barrie','Lemieux Litigation','Barrie','ON','simcoe-central',0,4.7,57,44.4122757,-79.688691,'{"name":"Lemieux Litigation","city":"Barrie","featured":false,"tags":["Personal Injury","Family Law","Employment Law","Civil Litigation"],"caseTypes":["injury","family","employment","litigation"],"region":"simcoe-central","province":"ON","lat":44.4122757,"lng":-79.688691,"address":"190 Cundles Rd E #204, Barrie, ON L4M 4S5","phone":"+17059994998","rating":4.7,"count":57,"slug":"lemieux-litigation-barrie","mapsUrl":"https://www.google.com/maps/search/Lemieux+Litigation+Barrie+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=190+Cundles+Rd+E+%23204%2C+Barrie%2C+ON+L4M+4S5","website":"https://lemieuxlaw.ca","blurb":"Personal Injury / Family Law in Barrie. Rated 4.7 from 57 Google reviews.","type":"logo","src":"images/logos/lemieux-litigation-barrie.png","details":{"lawyers":[{"name":"Antonio Meringolo"},{"name":"Nicole Meringolo"}],"areas":["Personal injury","Employment law","Family law","Motor vehicle accidents","Slip and falls","Brain injuries","Dog bites","Long-term disability","Wrongful deaths","Divorce and child support"],"serving":["Barrie","Simcoe County","Innisfil","Orillia","Midland","Alliston","Bradford","Newmarket"]}}',NULL,'Lemieux Litigation is a Barrie boutique litigation firm handling personal injury, employment and family law matters.

Its local lawyers serve all of Simcoe County, including Barrie, Innisfil, Orillia, Midland and Alliston, as well as Bradford, Newmarket and Collingwood. Injury work covers motor vehicle accidents, slip and falls and long-term disability. On the employment side the firm handles wrongful termination and workplace sexual harassment. Family law matters include divorce, child and spousal support, custody and access, and separation and parenting agreements. Nicole Meringolo and Melissa Ritter are the lawyers featured.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mkc-law-office-peterborough','MKC Law Office','Peterborough','ON','simcoe-central',0,4.6,54,44.3070807,-78.3240889,'{"name":"MKC Law Office","city":"Peterborough","featured":false,"tags":["Family Law","Real Estate","Wills & Estates"],"caseTypes":["family","realestate","wills"],"region":"simcoe-central","province":"ON","lat":44.3070807,"lng":-78.3240889,"address":"254 Brock St, Peterborough, ON K9H 2P7","phone":"+17057482241","rating":4.6,"count":54,"slug":"mkc-law-office-peterborough","mapsUrl":"https://www.google.com/maps/search/MKC+Law+Office+Peterborough+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=254+Brock+St%2C+Peterborough%2C+ON+K9H+2P7","website":"https://www.mkclaw.ca","blurb":"Family Law / Real Estate in Peterborough. Rated 4.6 from 54 Google reviews.","type":"logo","src":"images/logos/mkc-law-office-peterborough.webp","details":{"founded":1974,"lawyers":[{"name":"Ian Keay","title":"Managing Partner"},{"name":"Oliver S. Cooper"},{"name":"Jackson Wiltshire"}],"areas":["Real estate","Family law","Wills and estates","Business law","Litigation"],"serving":["Peterborough","Cottage Country"]}}',NULL,'MKC Law Office is a Peterborough firm handling family law, real estate, wills and estates, business law and litigation.

The practice has been the city''s law firm since 1974, serving Peterborough and Cottage Country from 254 Brock Street. Its real estate team handles closings, title transfers and mortgage details, while family lawyers deal with custody, support and separation agreements. Wills, powers of attorney, probate forms and estate matters are also part of the work. Ian Keay, Oliver S. Cooper and Jackson Wiltshire are among its lawyers, and Julie Kirkpatrick is associated with wills and powers of attorney. The firm also publishes blog posts for executors and beneficiaries.','dynamic','live',NULL);
