INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mclaren-bryan-law-professional-corporation-peterborough','McLaren Bryan Law Professional Corporation','Peterborough','ON','simcoe-central',0,5,25,44.3094825,-78.3310917,'{"name":"McLaren Bryan Law Professional Corporation","city":"Peterborough","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"simcoe-central","province":"ON","lat":44.3094825,"lng":-78.3310917,"address":"398 McDonnel St Unit# 4, Peterborough, ON K9H 2X4","phone":"+16479016815","rating":5,"count":25,"slug":"mclaren-bryan-law-professional-corporation-peterborough","mapsUrl":"https://www.google.com/maps/search/McLaren+Bryan+Law+Professional+Corporation+Peterborough+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=398+McDonnel+St+Unit%23+4%2C+Peterborough%2C+ON+K9H+2X4","website":"https://mclarenbryanlaw.com","blurb":"Law firm in Peterborough. Rated 5.0 from 25 Google reviews.","type":"logo","src":"images/logos/mclaren-bryan-law-professional-corporation-peterborough.webp","details":{"lawyers":[{"name":"Chantal McLaren Bryan"}],"areas":["Residential and commercial real estate","Immigration","Estate planning and administration","Family law","Separation and divorce","Notary appointments"]}}',NULL,'McLaren Bryan Law is a Peterborough practice handling residential and commercial real estate, immigration, wills and estates, and family law.

