INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('collaborative-law-corporation-nanaimo','Collaborative Law Corporation','Nanaimo','BC','bc-island',0,4.7,24,49.1648853,-123.9405858,'{"name":"Collaborative Law Corporation","city":"Nanaimo","featured":false,"tags":["Family Law","Employment Law"],"caseTypes":["family","employment"],"region":"bc-island","province":"BC","lat":49.1648853,"lng":-123.9405858,"address":"348 Wesley St, Nanaimo, BC V9R 2T6","phone":"+12508241255","rating":4.7,"count":24,"slug":"collaborative-law-corporation-nanaimo","mapsUrl":"https://www.google.com/maps/search/Collaborative+Law+Corporation+Nanaimo+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=348+Wesley+St%2C+Nanaimo%2C+BC+V9R+2T6","website":"https://collaborativelegal.ca","blurb":"Family Law / Employment Law in Nanaimo. Rated 4.7 from 24 Google reviews.","type":"logo","src":"images/logos/collaborative-law-corporation-nanaimo.png","details":{"lawyers":[{"name":"Nick Greer"},{"name":"Kevin Cantelon"}],"areas":["Separation and cohabitation agreements","Independent legal advice","Desk order divorce","Mediation and arbitration","Family law litigation","Divorce and separation","Property disputes","Child custody","1-Day divorce"],"serving":["Nanaimo","Vancouver","Central Vancouver Island"]}}',NULL,'Collaborative Law Corporation is a Nanaimo family law and mediation firm offering collaborative negotiation, mediation, arbitration and litigation.

Most family law issues can be settled collaboratively, saving cost, time and stress, and the firm serves Nanaimo, Vancouver and clients online across British Columbia. Services include separation and cohabitation agreements, independent legal advice, a 1 Day Divorce program, desk order divorces and med-arb. It also hosts a family and business mediation and arbitration centre. The team includes Nick Greer, Kevin Cantelon, Muadi Kalambay and Amanda Ferguson, and the office at 348 Wesley Street is downtown next to the Nanaimo courts.','dynamic','live',NULL);
