INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('vilkhov-law-professional-corporation-toronto','Vilkhov Law Professional Corporation','Toronto','ON','toronto',0,5,185,43.6502777,-79.3841614,'{"name":"Vilkhov Law Professional Corporation","city":"Toronto","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"toronto","province":"ON","lat":43.6502777,"lng":-79.3841614,"address":"121 Richmond St W Suite 1100, Toronto, ON M5H 2K1","phone":"+16479775852","rating":5,"count":185,"slug":"vilkhov-law-professional-corporation-toronto","mapsUrl":"https://www.google.com/maps/search/Vilkhov+Law+Professional+Corporation+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=121+Richmond+St+W+Suite+1100%2C+Toronto%2C+ON+M5H+2K1","website":"https://vilkhovlaw.ca","blurb":"General practice law firm in Toronto. Rated 5.0 from 185 Google reviews.","type":"logo","src":"images/logos/vilkhov-law-professional-corporation-toronto.png","details":{"lawyers":[{"name":"Igor Vilkhov"}],"areas":["Criminal defence","Sexual assault","Impaired driving offences","Assault","Fraud charges","Money laundering","Firearm possession","Drug offences","Bail hearings and release"],"serving":["Toronto","Greater Toronto Area"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Downtown Toronto criminal defence is the focus of Vilkhov Law Professional Corporation, led by lawyer Igor Vilkhov. The firm defends charges including sexual assault, impaired driving, assault, drug possession and fraud, and clients deal with Igor Vilkhov directly rather than with an associate or paralegal.

