INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('horra-family-law-markham','Horra Family Law','Markham','ON','york-durham',0,4.8,186,43.8322889,-79.3303489,'{"name":"Horra Family Law","city":"Markham","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"york-durham","province":"ON","lat":43.8322889,"lng":-79.3303489,"address":"500 Hood Rd Ste 400, Markham, ON L3R 9Z3","phone":"+14168401475","rating":4.8,"count":186,"slug":"horra-family-law-markham","mapsUrl":"https://www.google.com/maps/search/Horra+Family+Law+Markham+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=500+Hood+Rd+Ste+400%2C+Markham%2C+ON+L3R+9Z3","website":"https://www.horrafamilylaw.com","blurb":"Family Law in Markham. Rated 4.8 from 186 Google reviews.","type":"logo","src":"images/logos/horra-family-law-markham.png","heroImage":"images/hero/horra-family-law-markham.webp","details":{"lawyers":[{"name":"Ritu Horra"}],"areas":["Family law","Child custody","Collaborative law","Mediation"],"serving":["Markham","Mississauga","Waterloo","Guelph"]}}',NULL,'Horra Family Law is a Markham firm handling divorce, separation, child custody and access, support and adoption matters. Founded by sisters Ritu and Reena Horra, it offers mediation, collaboration and litigation, and its approach is built around keeping families first.

Mediation begins with a private pre-mediation meeting and can be closed (private) or open (admissible in court). The main office is on Hood Road in Markham, with appointment-only offices in Mississauga, Waterloo and Guelph. The firm works with families across the Greater Toronto Area.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('titan-law-toronto','Titan Law','Toronto','ON','toronto',0,4.7,186,43.6704825,-79.387325,'{"name":"Titan Law","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.6704825,"lng":-79.387325,"address":"2 Bloor St W Ste 762, Toronto, ON M4W 3E2","phone":"+16476179754","rating":4.7,"count":186,"slug":"titan-law-toronto","mapsUrl":"https://www.google.com/maps/search/Titan+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2+Bloor+St+W+Ste+762%2C+Toronto%2C+ON+M4W+3E2","website":"https://www.titanlaw.ca","blurb":"Immigration in Toronto. Rated 4.7 from 186 Google reviews.","type":"logo","src":"images/logos/titan-law-toronto.png","bioImage":"images/bio/titan-law-toronto.webp","details":{"areas":["Visitor visa","Study permit","Work visa","Family sponsorship","Business immigration","Permanent residency","Inadmissibility","Refugee"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Titan Law runs immigration and corporate law offices in Toronto and Vancouver. Immigration work covers visitor visas, study permits, work visas, family sponsorship, business immigration, permanent residency, inadmissibility, previously refused applications and refugee matters, and the firm also advises on incorporations, reorganizations and cross-border corporate structures.

Its lawyers offer one-hour appointments in English, French, Spanish, Mandarin, Cantonese, Russian, Ukrainian, Korean and Japanese. The Toronto office is on Bloor Street West, and the team includes Stanley Chiu, Sameera Ismail, Leo Chan, Karen Jantzen and Anneka Oh.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kmh-lawyers-ottawa','KMH Lawyers','Ottawa','ON','eastern',0,4.7,182,45.385959,-75.679521,'{"name":"KMH Lawyers","city":"Ottawa","featured":false,"tags":["Family Law","Real Estate","Wills & Estates"],"caseTypes":["family","realestate","wills"],"region":"eastern","province":"ON","lat":45.385959,"lng":-75.679521,"address":"2323 Riverside Dr. b0001, Ottawa, ON K1H 7X6","phone":"+16137333000","rating":4.7,"count":182,"slug":"kmh-lawyers-ottawa","mapsUrl":"https://www.google.com/maps/search/KMH+Lawyers+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2323+Riverside+Dr.+b0001%2C+Ottawa%2C+ON+K1H+7X6","website":"https://www.kmhlawyers.ca","blurb":"Family Law / Real Estate in Ottawa. Rated 4.7 from 182 Google reviews.","type":"logo","src":"images/logos/kmh-lawyers-ottawa.png","details":{"languages":["English","French"],"lawyers":[{"name":"Nancie-Anne Heaphy"},{"name":"Miriam Vale Peters","title":"Partner"},{"name":"Elisha M.E. Kelly"},{"name":"Ashley Amanda Wilson"},{"name":"Gabriel Laidlaw-Bale"},{"name":"Erin White"}],"areas":["Real estate","Civil litigation","Wills, estates and trusts","Estate litigation","Family law","Business and corporate","Small claims court"],"serving":["Ottawa"]}}',NULL,'KMH Lawyers act in real estate, commercial, family, wills and estates, and civil and estate litigation matters in Ottawa. The firm''s lawyers have more than 100 years of combined experience and have served the Ottawa community for over 40 years, from the Billings Bridge Plaza on Riverside Drive, acting for clients throughout the National Capital Region.

Real estate work ranges from first home purchases to retail and office acquisitions, and the firm appears in Small Claims Court, which handles amounts up to $25,000. Miriam Vale Peters is a partner with a general litigation practice, and Elisha Kelly serves clients in English and French.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kalfa-law-markham','Kalfa Law','Markham','ON','york-durham',0,4.9,170,43.8477676,-79.3246478,'{"name":"Kalfa Law","city":"Markham","featured":false,"tags":["Business Law"],"caseTypes":["business"],"region":"york-durham","province":"ON","lat":43.8477676,"lng":-79.3246478,"address":"10 Aviva Way #200, Markham, ON L6G 0G1","phone":"+14166317227","rating":4.9,"count":170,"slug":"kalfa-law-markham","mapsUrl":"https://www.google.com/maps/search/Kalfa+Law+Markham+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10+Aviva+Way+%23200%2C+Markham%2C+ON+L6G+0G1","website":"https://www.kalfalaw.com","blurb":"Business Law in Markham. Rated 4.9 from 170 Google reviews.","type":"logo","src":"images/logos/kalfa-law-markham.webp","details":{"founded":2018,"lawyers":[{"name":"Shira Kalfa","title":"Founder"},{"name":"Ghazal Hamedani"}],"areas":["Private M&A","Corporate-commercial law","Tax planning"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Private M&A and corporate-commercial law are the focus of Kalfa Law, a boutique firm in Markham serving small and mid-sized businesses. Founder and principal lawyer Shira Kalfa works on buy-sell transactions, incorporations, shareholder agreements, employment and independent contractor agreements, and employee stock option and incentive plans, with a background in tax law informing the work.

The firm has handled hundreds of small and medium-sized private M&A transactions and also advises on professional corporations. Its clients are entrepreneurs, business owners and investors in Toronto and across Ontario, and it publishes articles on topics such as non-solicitation versus non-compete terms and section 85 rollovers in a business sale.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('angeles-and-de-jesus-law-llp-toronto','Angeles & De Jesus Law LLP','Toronto','ON','toronto',0,4.9,168,43.7079739,-79.3936422,'{"name":"Angeles & De Jesus Law LLP","city":"Toronto","featured":false,"tags":["Family Law","Immigration","Criminal Defence"],"caseTypes":["family","immigration","criminal"],"region":"toronto","province":"ON","lat":43.7079739,"lng":-79.3936422,"address":"160 Eglinton Ave E Ste 406, Toronto, ON M4P 3B5","phone":"+14164095991","rating":4.9,"count":168,"slug":"angeles-and-de-jesus-law-llp-toronto","mapsUrl":"https://www.google.com/maps/search/Angeles+%26+De+Jesus+Law+LLP+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=160+Eglinton+Ave+E+Ste+406%2C+Toronto%2C+ON+M4P+3B5","website":"https://ajlawpartners.ca","blurb":"Family Law / Immigration in Toronto. Rated 4.9 from 168 Google reviews.","type":"logo","src":"images/logos/angeles-and-de-jesus-law-llp-toronto.jpg","bioImage":"images/bio/angeles-and-de-jesus-law-llp-toronto.webp","details":{"languages":["English","Tagalog"],"lawyers":[{"name":"Fatima Angeles","title":"Barrister, Solicitor & Notary Public"}],"areas":["Immigration law","Family law","Estate law and wills","Real estate law","Criminal law","Paralegal services","Provincial offences","Landlord and tenant disputes","Small claims"],"serving":["Toronto"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["10:00","14:00"]]}','Angeles & De Jesus Law LLP is a Toronto general practice firm serving the Filipino-Canadian community in family, immigration and estate law. Also known as AJ Law LLP, it handles immigration, decision-making responsibility and parenting time, marriage and cohabitation contracts, property division, wills, residential and commercial real estate closings, criminal law and civil litigation, and offers paralegal and notary services.

The firm was started by Fatima, who completed a Master of Laws in Canadian common law at the University of Toronto, and Czarina, a licensed paralegal, with the aim of widening access to legal services for the Filipino community. Its office is on Eglinton Avenue East in Toronto.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('legal-solutions-law-firm-toronto','Legal Solutions Law Firm','Toronto','ON','toronto',0,4.7,175,43.7887857,-79.2357006,'{"name":"Legal Solutions Law Firm","city":"Toronto","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"toronto","province":"ON","lat":43.7887857,"lng":-79.2357006,"address":"10 Milner Business Ct #300, Scarborough, ON M1B 3C6","phone":"+14162742222","rating":4.7,"count":175,"slug":"legal-solutions-law-firm-toronto","mapsUrl":"https://www.google.com/maps/search/Legal+Solutions+Law+Firm+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10+Milner+Business+Ct+%23300%2C+Scarborough%2C+ON+M1B+3C6","website":"https://legalsolutionslawfirm.ca","blurb":"Family Law in Toronto. Rated 4.7 from 175 Google reviews.","type":"logo","src":"images/logos/legal-solutions-law-firm-toronto.webp","details":{"founded":2012,"lawyers":[{"name":"Ryan Manilla"}],"areas":["Criminal law","Family law","Traffic tickets","Small claims court","Civil litigation","Landlord and tenant","Regulatory proceedings","Divorce","Child custody","Separation agreements"],"serving":["Toronto","GTA","North York","Etobicoke","Scarborough"]}}','{"1":[["09:00","18:00"]],"2":[["09:00","18:00"]],"3":[["09:00","18:00"]],"4":[["09:00","18:00"]],"5":[["09:00","18:00"]]}','Legal Solutions Law Firm is a Toronto practice handling criminal, family, traffic, landlord-tenant and civil litigation matters. Founded in 2012 by Ryan Manilla, a barrister, solicitor and notary public, it also acts in regulatory proceedings and in disputes over unpaid goods and services, and serves Scarborough, North York, Mississauga, Brampton, Markham, Richmond Hill and Vaughan.

Manilla graduated from Osgoode Hall Law School and spent two years at a New York City law firm before returning to Toronto. The firm offers flat fees and payment plans, and its Scarborough office is on Milner Business Court.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('tailor-law-professional-corporation-mississauga','Tailor Law Professional Corporation','Mississauga','ON','peel-halton',0,4.6,176,43.5923146,-79.6381925,'{"name":"Tailor Law Professional Corporation","city":"Mississauga","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"peel-halton","province":"ON","lat":43.5923146,"lng":-79.6381925,"address":"77 City Centre Dr, Mississauga, ON L5B 1M5","phone":"+19053660202","rating":4.6,"count":176,"slug":"tailor-law-professional-corporation-mississauga","mapsUrl":"https://www.google.com/maps/search/Tailor+Law+Professional+Corporation+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=77+City+Centre+Dr%2C+Mississauga%2C+ON+L5B+1M5","website":"https://tailorlaw.com","blurb":"Family Law in Mississauga. Rated 4.6 from 176 Google reviews.","type":"logo","src":"images/logos/tailor-law-professional-corporation-mississauga.webp","details":{"lawyers":[{"name":"Deepa Tailor","title":"Founder & Managing Director"},{"name":"Daniel Boiani"},{"name":"Samantha Coomara"},{"name":"Nicole Hirtenfeld"},{"name":"Jasmine Sihota"}],"areas":["Divorce","Child custody and parenting","Child and spousal support","Property and asset division","Separation agreements","Domestic contracts","Family mediation","Collaborative family law"],"serving":["Mississauga","Toronto","Greater Toronto Area"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Tailor Law Professional Corporation is a Mississauga family law firm handling divorce, custody, support and property matters. Founded in 2016 and led by Deepa Tailor, it acts in contested and uncontested divorces in the Superior Court of Justice and also handles separation agreements, mediation, and wills and estates, for families in Mississauga, Toronto, Brampton, Oakville and across the Greater Toronto Area.

Offices are at 361 University Avenue in Toronto and 7755 Hurontario Street in Mississauga. The firm also offers limited-scope services, where a client hires a lawyer for a single task such as drafting documents, coaching for court or a limited appearance, and it has helped more than 2,000 families in Toronto, Mississauga and Brampton.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lee-and-company-north-york','Lee and Company','North York','ON','toronto',0,4.8,162,43.7603396,-79.4101047,'{"name":"Lee and Company","city":"North York","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.7603396,"lng":-79.4101047,"address":"4773 Yonge St #3F, North York, ON M2N 0G2","phone":"+14163210100","rating":4.8,"count":162,"slug":"lee-and-company-north-york","mapsUrl":"https://www.google.com/maps/search/Lee+and+Company+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=4773+Yonge+St+%233F%2C+North+York%2C+ON+M2N+0G2","website":"https://www.leecompany.ca","blurb":"Immigration in North York. Rated 4.8 from 162 Google reviews.","type":"logo","src":"images/logos/lee-and-company-north-york.jpg","details":{"areas":["Immigration litigation","Judicial reviews","Humanitarian and compassionate applications","Immigration Appeal Division","Temporary resident permits","Stay of removal"]}}',NULL,'Lee and Company is a North York boutique immigration firm focused on litigation, appeals and removals defence. Active since 2001, it acts for people whose cases were refused overseas or who face deportation in Canada, and has appeared before all divisions of the Immigration and Refugee Board, the Federal Court and the Federal Court of Appeal.

Humanitarian and compassionate applications, appeals to the Immigration Appeal Division and temporary resident permits to overcome inadmissibility are among the routes it pursues. Lawyer Wennie Lee appears regularly at the Federal Court, and the team includes immigration consultants Marko Vitorovich and Mohamed Abuzayed and Ray Radojevic, who retired from Citizenship and Immigration Canada as a Canada Immigration Centre Manager.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('moyal-immigration-lawyers-north-york','Moyal Immigration Lawyers','North York','ON','toronto',0,4.9,154,43.7807816,-79.4175069,'{"name":"Moyal Immigration Lawyers","city":"North York","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.7807816,"lng":-79.4175069,"address":"7 Hendon Ave, North York, ON M2M 4G8","phone":"+14167333193","rating":4.9,"count":154,"slug":"moyal-immigration-lawyers-north-york","mapsUrl":"https://www.google.com/maps/search/Moyal+Immigration+Lawyers+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7+Hendon+Ave%2C+North+York%2C+ON+M2M+4G8","website":"https://moyal.com","blurb":"Immigration in North York. Rated 4.9 from 154 Google reviews.","type":"logo","src":"images/logos/moyal-immigration-lawyers-north-york.png","details":{"lawyers":[{"name":"Henry Moyal"}],"areas":["Canadian immigration law"],"serving":["Toronto"]}}',NULL,'Moyal Immigration Lawyers, the Law Offices of Moyal & Moyal, is a North York firm practising only Canadian immigration law. Its work covers inland and overseas applications, including independent and skilled worker, humanitarian and compassionate, provincial nominee and Express Entry applications, sponsorships and work permits.

Lawyer Henry Moyal began working in immigration in 1988, before graduating from Osgoode Hall Law School, and has acted for many members of the Filipino community. He writes a weekly column called Immigration Newsweek for community newspapers and travels abroad to give seminars on Canadian immigration.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('art-of-law-professional-corporation-north-york','Art of Law Professional Corporation','North York','ON','toronto',0,5,150,43.7595989,-79.4100391,'{"name":"Art of Law Professional Corporation","city":"North York","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.7595989,"lng":-79.4100391,"address":"Procter and Gamble, Yonge and Sheppard, 4711 Yonge St 10th Floor, North York, ON M2N 7E4","phone":"+14168802400","rating":5,"count":150,"slug":"art-of-law-professional-corporation-north-york","mapsUrl":"https://www.google.com/maps/search/Art+of+Law+Professional+Corporation+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=Procter+and+Gamble%2C+Yonge+and+Sheppard%2C+4711+Yonge+St+10th+Floor%2C+North+York%2C+ON+M2N+7E4","website":"https://artoflaw.ca","blurb":"Real Estate in North York. Rated 5.0 from 150 Google reviews.","type":"logo","src":"images/logos/art-of-law-professional-corporation-north-york.png","details":{"areas":["Civil litigation","Family law","Wills and estate","Real estate"]}}',NULL,'Art of Law Professional Corporation is a North York firm handling civil litigation, family law, wills and estates and real estate. Civil work includes breach of contract, wrongful dismissal, debt collection, property damage and personal injury, while family matters include contested and uncontested divorce, child and spousal support, parenting, equalization of net family property and domestic contracts such as cohabitation, separation and marriage contracts.

Estates work covers wills and powers of attorney. Lawyer Ardeshir works in English and Farsi, focuses on family law, civil litigation, and wills and estates, and has experience from Greater Toronto Area firms. The office is at Yonge Street and Sheppard Avenue.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('visa-law-group-pc-north-york','Visa Law Group PC','North York','ON','toronto',0,4.9,153,43.766264,-79.412998,'{"name":"Visa Law Group PC","city":"North York","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.766264,"lng":-79.412998,"address":"5000 Yonge St Ste 1901, North York, ON M2N 7E9","phone":"+12897244150","rating":4.9,"count":153,"slug":"visa-law-group-pc-north-york","mapsUrl":"https://www.google.com/maps/search/Visa+Law+Group+PC+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5000+Yonge+St+Ste+1901%2C+North+York%2C+ON+M2N+7E9","website":"https://www.myvisa.law","blurb":"Immigration in North York. Rated 4.9 from 153 Google reviews.","type":"logo","src":"images/logos/visa-law-group-pc-north-york.jpg","details":{"languages":["English","Urdu","Hindi","French","Turkish","Farsi"],"lawyers":[{"name":"Zeynab Ziaie Moayyed"},{"name":"Fareha Shahzad"},{"name":"Veys Inci"}],"areas":["Express Entry","Family sponsorship","Work permits","Study permits","Visitor visas","Humanitarian and compassionate applications","Appeals and inadmissibility","Residency and citizenship","Start-up visa","Misrepresentation"]}}',NULL,'Visa Law Group PC is a North York immigration firm handling refusals, Federal Court litigation and Canada visa applications. It acts for applicants who have been refused, including study permit, Express Entry and start-up visa work permit refusals taken to Federal Court, and for people facing misrepresentation allegations.

The firm also assists individuals and businesses with temporary and permanent residence applications, appeals and inadmissibility issues, and with business immigration through the Start-up Visa Program, provincial nominee entrepreneur streams and the Global Talent Stream. Meetings can be held virtually.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bally-hundal-brampton','Bally Hundal','Brampton','ON','peel-halton',0,4.9,152,43.7238783,-79.7173326,'{"name":"Bally Hundal","city":"Brampton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.7238783,"lng":-79.7173326,"address":"104, 490 Bramalea Rd, Brampton, ON L6T 0G1","phone":"+14168880592","rating":4.9,"count":152,"slug":"bally-hundal-brampton","mapsUrl":"https://www.google.com/maps/search/Bally+Hundal+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=104%2C+490+Bramalea+Rd%2C+Brampton%2C+ON+L6T+0G1","website":"https://www.hundallawfirm.com","blurb":"Criminal Defence in Brampton. Rated 4.9 from 152 Google reviews.","type":"logo","src":"images/logos/bally-hundal-brampton.png","details":{"areas":["Murder defence","Assault defence","Criminal harassment","Drug possession","Kidnapping defence","Robbery defence","Arson"],"serving":["Brampton"]}}',NULL,'Bally Hundal is a Brampton criminal defence lawyer who has practised for over 24 years, defending charges from assault to murder. He was called to the Ontario bar in March 2002 and worked for over three years as criminal duty counsel with Legal Aid Ontario, then completed a Master of Laws at Osgoode Hall in 2019.

He has worked part-time as a staff lawyer on Charter litigation with the Justice Centre for Constitutional Freedoms and served as an adjudicator at the Ontario Licence Appeal Tribunal. His practice, Hundal Law Firm, appears in the Ontario Court of Justice, the Superior Court of Justice and the Court of Appeal, with trials and bail hearings across Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ghasemi-law-professional-corporation-richmond-hill','Ghasemi Law Professional Corporation','Richmond Hill','ON','york-durham',0,5,145,43.8499551,-79.3843825,'{"name":"Ghasemi Law Professional Corporation","city":"Richmond Hill","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"york-durham","province":"ON","lat":43.8499551,"lng":-79.3843825,"address":"9030 Leslie St #309, Richmond Hill, ON L4B 1G2","phone":"+14168879200","rating":5,"count":145,"slug":"ghasemi-law-professional-corporation-richmond-hill","mapsUrl":"https://www.google.com/maps/search/Ghasemi+Law+Professional+Corporation+Richmond+Hill+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=9030+Leslie+St+%23309%2C+Richmond+Hill%2C+ON+L4B+1G2","website":"https://www.ghasemilaw.com","blurb":"Immigration in Richmond Hill. Rated 5.0 from 145 Google reviews.","type":"logo","src":"images/logos/ghasemi-law-professional-corporation-richmond-hill.webp","details":{"lawyers":[{"name":"Sara Ghasemi","title":"Barrister and Solicitor"}],"areas":["Immigration","Refugee claims","Real estate","Humanitarian and compassionate applications"],"serving":["Richmond Hill"]}}',NULL,'Ghasemi Law Professional Corporation is a Richmond Hill firm handling immigration and real estate matters for clients in Toronto and the GTA. Founder and director Sara Ghasemi is a licensed barrister and solicitor with a background in both the legal and banking industries, and her real estate practice covers sales, purchases, refinancing, mortgages, title transfers, bridge financing, assignments, interim closings and lease agreements.

Ghasemi is a member of the Law Society of Ontario and the Iran Central Bar Association and is a licensing candidate with the State Bar of California. The firm works on a flat-rate fee structure with transparent charges and no unexpected closing costs.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mirian-law-firm-markham','Mirian Law Firm','Markham','ON','york-durham',0,4.8,150,43.803492,-79.4209027,'{"name":"Mirian Law Firm","city":"Markham","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"york-durham","province":"ON","lat":43.803492,"lng":-79.4209027,"address":"7191 Yonge St Unit 709, Thornhill, ON L3T 0C4","phone":"+16479305112","rating":4.8,"count":150,"slug":"mirian-law-firm-markham","mapsUrl":"https://www.google.com/maps/search/Mirian+Law+Firm+Markham+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7191+Yonge+St+Unit+709%2C+Thornhill%2C+ON+L3T+0C4","website":"https://mirianlaw.com","blurb":"Personal Injury in Markham. Rated 4.8 from 150 Google reviews.","type":"logo","src":"images/logos/mirian-law-firm-markham.png","details":{"languages":["Farsi","Arabic","Cantonese","Mandarin"],"areas":["Car accident","Brain injury","Slip and fall","Long-term disability","Motorcycle accident","Catastrophic injury","Dog bite injury","Personal injury","Disability denial"],"serving":["Greater Toronto Area","Ontario","California","Toronto"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Mirian Law Firm is a Markham personal injury firm handling car accidents, disability insurance denials and accident benefits. Its work covers long-term and short-term disability, brain and catastrophic injuries, slip and fall, motorcycle accidents, dog bites, accident benefits under Ontario''s Statutory Accident Benefits Schedule and tort actions, and the firm also serves clients in California.

Fees are contingency-based, taken as a percentage of any recovery and explained in writing, and each client is assigned a legal case manager who works with the lawyer. The firm offers hospital and home visits as well as evening and weekend appointments for clients in the Greater Toronto Area, from its office on Yonge Street in Thornhill.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('minken-employment-lawyers-markham','Minken Employment Lawyers','Markham','ON','york-durham',0,4.6,152,43.8663051,-79.3104433,'{"name":"Minken Employment Lawyers","city":"Markham","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"york-durham","province":"ON","lat":43.8663051,"lng":-79.3104433,"address":"145 Main St Unionville, Unionville, ON L3R 2G7","phone":"+19054777011","rating":4.6,"count":152,"slug":"minken-employment-lawyers-markham","mapsUrl":"https://www.google.com/maps/search/Minken+Employment+Lawyers+Markham+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=145+Main+St+Unionville%2C+Unionville%2C+ON+L3R+2G7","website":"https://www.minkenemploymentlawyers.com","blurb":"Employment Law in Markham. Rated 4.6 from 152 Google reviews.","type":"logo","src":"images/logos/minken-employment-lawyers-markham.png","details":{"founded":1990,"lawyers":[{"name":"Ronald S. Minken","title":"Founder"},{"name":"Sara A. Kauder","title":"Senior Employment Lawyer"}],"areas":["Wrongful dismissal","Constructive dismissal","Severance packages","Employment contracts","Harassment and discrimination","Human rights","Employment standards","Workplace policies","Temporary lay-offs","Employment law"],"serving":["Greater Toronto"]}}',NULL,'Minken Employment Lawyers is a Markham firm that acts only in employment law, for both employers and employees. Ronald Minken heads the firm, which was established in 1990 and has advised or represented more than 10,000 clients. Its work covers employment and executive contracts, independent contractor agreements, wrongful and constructive dismissal, cause terminations, temporary lay-offs, severance packages, workplace harassment and discrimination, and employment standards compliance.

Its lawyers have appeared at all levels of courts and tribunals across Canada. The Unionville office on Main Street serves Markham, Richmond Hill, Vaughan, Newmarket and the wider Greater Toronto Area, and some matters are offered on flat, fixed or deferred fees.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('smitiuch-injury-law-etobicoke','Smitiuch Injury Law','Etobicoke','ON','toronto',0,4.9,135,43.6454726,-79.5221911,'{"name":"Smitiuch Injury Law","city":"Etobicoke","featured":false,"tags":["Personal Injury","Civil Litigation"],"caseTypes":["injury","litigation"],"region":"toronto","province":"ON","lat":43.6454726,"lng":-79.5221911,"address":"Centre, 3280 Bloor St W Tower, Suite 800, Etobicoke, ON M8X 2X3","phone":"+14166211551","rating":4.9,"count":135,"slug":"smitiuch-injury-law-etobicoke","mapsUrl":"https://www.google.com/maps/search/Smitiuch+Injury+Law+Etobicoke+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=Centre%2C+3280+Bloor+St+W+Tower%2C+Suite+800%2C+Etobicoke%2C+ON+M8X+2X3","website":"https://www.sil.lawyer","blurb":"Personal Injury / Civil Litigation in Etobicoke. Rated 4.9 from 135 Google reviews.","type":"logo","src":"images/logos/smitiuch-injury-law-etobicoke.webp","details":{"areas":["Personal injury","Car accident","Slip and fall","Premises liability"],"serving":["Toronto","Brantford","Simcoe","Greater Toronto Area","Etobicoke"]}}',NULL,'Smitiuch Injury Law is an Etobicoke personal injury firm acting for people hurt in car, truck and motorcycle accidents. Founded in 2001 by Michael Smitiuch, it takes injury and wrongful death cases through to trial and has concluded matters by negotiated settlement and jury verdict. Investigation work includes gathering evidence, collecting police reports and medical records and interviewing witnesses.

Fees are contingency-based, so clients owe nothing unless compensation is recovered. The firm serves Toronto, Etobicoke and the wider Greater Toronto Area from its office on Bloor Street West.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('omar-hasan-al-zahid-toronto','Omar Hasan Al Zahid','Toronto','ON','toronto',0,4.9,131,43.7098243,-79.2481696,'{"name":"Omar Hasan Al Zahid","city":"Toronto","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.7098243,"lng":-79.2481696,"address":"2481 Kingston Rd Suite 201, Scarborough, ON M1N 1V4","phone":"+16473417877","rating":4.9,"count":131,"slug":"omar-hasan-al-zahid-toronto","mapsUrl":"https://www.google.com/maps/search/Omar+Hasan+Al+Zahid+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2481+Kingston+Rd+Suite+201%2C+Scarborough%2C+ON+M1N+1V4","website":"https://www.ozahidlaw.ca","blurb":"Real Estate in Toronto. Rated 4.9 from 131 Google reviews.","type":"logo","src":"images/logos/omar-hasan-al-zahid-toronto.webp","details":{"areas":["Real estate","Corporate","Wills and estates"]}}',NULL,'Omar Hasan Al Zahid leads Omar Zahid Law Professional Corporation, a Toronto real estate and business law practice. Zahid holds bachelor''s and master''s degrees in law from the University of Dhaka in Bangladesh and a Master of Laws from Osgoode Hall at York University, joined the Law Society of Ontario in 2017 and opened the firm shortly afterwards.

The practice handles real estate, property, corporate, commercial, business, and wills and estates matters, including urgent closings, and has completed thousands of transactions. It charges a flat rate for each type of service rather than hourly fees, and its office is on Kingston Road in Scarborough.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bromwich-smith-toronto','Bromwich+Smith','Toronto','ON','toronto',0,4.9,127,43.7770317,-79.2522848,'{"name":"Bromwich+Smith","city":"Toronto","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"toronto","province":"ON","lat":43.7770317,"lng":-79.2522848,"address":"100 Consilium Pl Ste 315, Scarborough, ON M1H 3E3","phone":"+18558849243","rating":4.9,"count":127,"slug":"bromwich-smith-toronto","mapsUrl":"https://www.google.com/maps/search/Bromwich%2BSmith+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=100+Consilium+Pl+Ste+315%2C+Scarborough%2C+ON+M1H+3E3","website":"https://www.bromwichandsmith.com","blurb":"General practice law firm in Toronto. Rated 4.9 from 127 Google reviews.","type":"logo","src":"images/logos/bromwich-smith-toronto.webp","details":{"areas":["Consumer proposal","Bankruptcy","Debt consolidation"],"serving":["Canada"]}}',NULL,'Bromwich+Smith is a firm of Licensed Insolvency Trustees serving Toronto and the rest of Canada with consumer proposals and bankruptcy. It offers government-regulated debt relief options, namely consumer proposals, bankruptcy and debt consolidation. A consumer proposal sets a monthly payment based on what the person can afford, while bankruptcy usually concludes within nine months.

The firm has helped Canadians with debt for more than 20 years and serves clients nationwide from an office on Consilium Place in Scarborough. Its Licensed Insolvency Trustees include Jeff Lewis, Karen Adler and Bonnie Bryan, and its core values are putting clients first, taking ownership, succeeding together and doing the right thing.','dynamic','live',NULL);
