INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('gagan-law-pc-mississauga','Gagan Law PC','Mississauga','ON','peel-halton',0,4.8,121,43.5829291,-79.7144693,'{"name":"Gagan Law PC","city":"Mississauga","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"peel-halton","province":"ON","lat":43.5829291,"lng":-79.7144693,"address":"8 Water St, Mississauga, ON L5M 1T9","phone":"+19059971666","rating":4.8,"count":121,"slug":"gagan-law-pc-mississauga","mapsUrl":"https://www.google.com/maps/search/Gagan+Law+PC+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=8+Water+St%2C+Mississauga%2C+ON+L5M+1T9","website":"https://gaganlaw.com","blurb":"Real Estate in Mississauga. Rated 4.8 from 121 Google reviews.","type":"logo","src":"images/logos/gagan-law-pc-mississauga.png","details":{"areas":["Real estate","Wills and estate","Business law","Immigration","Land development"],"serving":["Mississauga","Brampton","Streetsville"]}}',NULL,'Gagan Law PC is a Mississauga firm offering real estate, wills and estates, business law and immigration services. Principal lawyer Gagan Dadiala leads the firm from the Streetsville village area of Mississauga and serves clients in Mississauga and Brampton.

Business law work includes business name and sole proprietorship registrations, contracts, policies, terms of service and memoranda of understanding, as well as guidance on buying and selling dental practices. The firm works to keep its fee structure transparent and predictable and offers a range of billing arrangements.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('sarao-law-pro-corp-etobicoke','Sarao Law Pro. Corp.','Etobicoke','ON','toronto',0,4.8,121,43.7361458,-79.6020794,'{"name":"Sarao Law Pro. Corp.","city":"Etobicoke","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"toronto","province":"ON","lat":43.7361458,"lng":-79.6020794,"address":"130 Westmore Dr Suite# 5, Etobicoke, ON M9V 5E2","phone":"+14164754002","rating":4.8,"count":121,"slug":"sarao-law-pro-corp-etobicoke","mapsUrl":"https://www.google.com/maps/search/Sarao+Law+Pro.+Corp.+Etobicoke+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=130+Westmore+Dr+Suite%23+5%2C+Etobicoke%2C+ON+M9V+5E2","website":"https://www.saraolaw.ca","blurb":"Real Estate / Wills & Estates in Etobicoke. Rated 4.8 from 121 Google reviews.","type":"logo","src":"images/logos/sarao-law-pro-corp-etobicoke.webp","details":{"areas":["Real estate","Family law","Business law","Immigration","Notary public","Power of attorney","Wills and estate","Affidavits"],"serving":["Toronto"]}}',NULL,'Sarao Law Professional Corporation is an Etobicoke firm handling real estate transactions and wills and estate planning. On property transactions the firm conducts title and off-title searches to confirm that a buyer has the correct property, clear of liens and encumbrances, arranges title insurance for residential and commercial property, and helps clients understand land transfer tax, property tax, HST and income tax implications.

Estate planning services include wills, living wills and powers of attorney for property for clients in Toronto. Fees are stated upfront, and the firm works to the values of integrity, ethics and client-centredness from its office on Westmore Drive.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('landings-llp-toronto','Landings LLP','Toronto','ON','toronto',0,5,116,43.65048,-79.3773704,'{"name":"Landings LLP","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.65048,"lng":-79.3773704,"address":"25 Adelaide St E Ste 1414, Toronto, ON M5C 3A1","phone":"+14163631696","rating":5,"count":116,"slug":"landings-llp-toronto","mapsUrl":"https://www.google.com/maps/search/Landings+LLP+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=25+Adelaide+St+E+Ste+1414%2C+Toronto%2C+ON+M5C+3A1","website":"https://landingslaw.com","blurb":"Immigration in Toronto. Rated 5.0 from 116 Google reviews.","type":"logo","src":"images/logos/landings-llp-toronto.png","heroImage":"images/hero/landings-llp-toronto.webp","details":{"languages":["English","French","Spanish","Urdu","Hindi","Punjabi","Swahili"],"lawyers":[{"name":"Jacqueline Swaisland"},{"name":"Warda Shazadi Meighen"},{"name":"Erin V. Simpson"},{"name":"Allan Rock"},{"name":"Alison Imrie"},{"name":"Camille Bontems"}],"areas":["Refugee law","Immigration law","Constitutional law","Administrative law"],"serving":["Toronto"]}}',NULL,'Landings LLP is a downtown Toronto law firm acting in refugee, immigration, citizenship and human rights matters. It represents people seeking refugee protection and temporary or permanent status, handles appeals to the Immigration Appeal Division and Refugee Appeal Division, humanitarian and compassionate applications, pre-removal risk assessments, detention and inadmissibility issues, and acts in constitutional litigation, including at the Supreme Court of Canada.

Partners Jacqueline Swaisland, Warda Shazadi Meighen and Erin V. Simpson lead the team. Its lawyers include former adjudicators of the Immigration and Refugee Board, lawyers who have worked with the United Nations and law school adjunct faculty, and the firm also advises non-governmental organizations and works with clients internationally.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('posner-craig-stein-llp-toronto','Posner Craig Stein LLP','Toronto','ON','toronto',0,4.9,118,43.6679358,-79.3691456,'{"name":"Posner Craig Stein LLP","city":"Toronto","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"toronto","province":"ON","lat":43.6679358,"lng":-79.3691456,"address":"603 1/2 Parliament St, Toronto, ON M4X 1P9","phone":"+14163912118","rating":4.9,"count":118,"slug":"posner-craig-stein-llp-toronto","mapsUrl":"https://www.google.com/maps/search/Posner+Craig+Stein+LLP+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=603+1%2F2+Parliament+St%2C+Toronto%2C+ON+M4X+1P9","website":"https://pcslaw.ca","blurb":"Criminal Defence in Toronto. Rated 4.9 from 118 Google reviews.","type":"logo","src":"images/logos/posner-craig-stein-llp-toronto.png","details":{"lawyers":[{"name":"Richard Posner"},{"name":"Alison Craig","title":"Founding Partner"},{"name":"Gabriel Gross-Stein"},{"name":"Stefan Rinas"},{"name":"D’arcy Leitch"},{"name":"Sigma Khan"},{"name":"Travis Moore"},{"name":"Shelby Hohmann"},{"name":"Christa Wong"}],"areas":["Criminal defence","Assault","Sexual assault","Homicide","Firearms and weapons offences","Bail hearings","Criminal appeals","Professional discipline and regulatory defence"],"serving":["Toronto","Ontario"]}}',NULL,'Posner Craig Stein LLP is a Toronto criminal law firm defending serious charges, investigations, trials and appeals. The firm acts for individuals and organizations facing allegations such as homicide, sexual assault, assault, domestic assault, fraud and financial crime, firearms and weapons offences, drug offences, driving offences, arson and break and enter.

Its work spans police investigations, bail hearings, trials, sentencing and criminal appeals, and it also provides regulatory and professional discipline counsel. The office is on Parliament Street, and the firm acts in Toronto, the Greater Toronto Area and across Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('grechi-carter-professional-corporation-toronto','Grechi Carter Professional Corporation','Toronto','ON','toronto',0,4.6,119,43.7065792,-79.3978503,'{"name":"Grechi Carter Professional Corporation","city":"Toronto","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.7065792,"lng":-79.3978503,"address":"1 Eglinton Ave E #803, Toronto, ON M4P 3A1","phone":"+14169003865","rating":4.6,"count":119,"slug":"grechi-carter-professional-corporation-toronto","mapsUrl":"https://www.google.com/maps/search/Grechi+Carter+Professional+Corporation+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1+Eglinton+Ave+E+%23803%2C+Toronto%2C+ON+M4P+3A1","website":"https://gclaw.ca","blurb":"Real Estate in Toronto. Rated 4.6 from 119 Google reviews.","type":"logo","src":"images/logos/grechi-carter-professional-corporation-toronto.png","details":{"areas":["Real estate","Private mortgages","Mortgage enforcement"],"serving":["Toronto","Ontario"]}}',NULL,'Grechi Carter Professional Corporation is a boutique Midtown Toronto firm handling real estate, private mortgages and mortgage enforcement. It acts on the purchase, sale and refinancing of condominiums, houses, cottages and commercial or industrial property, and for private mortgage lenders in Ontario, closing hundreds of private mortgages per year.

The firm has also acted for both borrowers and lenders in contested and uncontested mortgage enforcement actions. Its office is at 1 Eglinton Avenue East, Suite 803, in Toronto.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('borders-law-firm-toronto','Borders Law Firm','Toronto','ON','toronto',0,4.7,116,43.708949,-79.3981182,'{"name":"Borders Law Firm","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.708949,"lng":-79.3981182,"address":"2345 Yonge St #910, Toronto, ON M4P 1T7","phone":"+14164815689","rating":4.7,"count":116,"slug":"borders-law-firm-toronto","mapsUrl":"https://www.google.com/maps/search/Borders+Law+Firm+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2345+Yonge+St+%23910%2C+Toronto%2C+ON+M4P+1T7","website":"https://www.borderslawfirm.com","blurb":"Immigration in Toronto. Rated 4.7 from 116 Google reviews.","type":"logo","src":"images/logos/borders-law-firm-toronto.png","details":{"lawyers":[{"name":"Devika Penekelapati","title":"Founding Partner"}],"areas":["Business immigration","Canadian personal immigration","US immigration","Notary public","Citizenship"]}}',NULL,'Immigration is the only area of law at Borders Law Firm, a Toronto firm handling Canadian and US work permits, residence and citizenship. Founded in 2004, the firm acts for multinational corporations, small businesses, families and individuals. Its Canadian work covers work permits, study permits, federal and provincial permanent residence, sponsorship, inadmissibility, citizenship applications and litigation appeals before the Immigration Appeal Division, the Immigration and Refugee Board and the Federal Court of Canada.

On the American side it prepares L and TN CUSMA work permit applications and Green Card applications. For corporate clients it can set up a single office or move an entire workforce, and it builds long-term strategies that extend beyond the validity of the first visa. Founders Devika Penekelapati and Andres Pelenur are also appointed notaries public for the Province of Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('arrow-law-north-york','Arrow Law','North York','ON','toronto',0,5,108,43.7596707,-79.4099442,'{"name":"Arrow Law","city":"North York","featured":false,"tags":["Family Law","Immigration","Real Estate"],"caseTypes":["family","immigration","realestate"],"region":"toronto","province":"ON","lat":43.7596707,"lng":-79.4099442,"address":"4711 Yonge St 10th Floor, North York, ON M2N 7E4","phone":"+16475350914","rating":5,"count":108,"slug":"arrow-law-north-york","mapsUrl":"https://www.google.com/maps/search/Arrow+Law+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=4711+Yonge+St+10th+Floor%2C+North+York%2C+ON+M2N+7E4","website":"https://www.arrowlaw.ca","blurb":"Family Law / Immigration in North York. Rated 5.0 from 108 Google reviews.","type":"logo","src":"images/logos/arrow-law-north-york.png","details":{"areas":["Immigration law","Real estate law","Family law","Notary services","Independent legal advice"],"serving":["Toronto","Hamilton","Durham Region"]}}',NULL,'Immigration, real estate, wills and estates, and family law are the practice areas of Arrow Law, a firm in North York serving Toronto and Durham. Its lawyers also act for clients in Whitby and the wider Durham Region, and the firm works from offices on Yonge Street in North York and on King Street West in Hamilton.

Clients receive timely updates at every step of a matter, and the firm uses technology and flexible service methods to deliver its services. Its lawyers practise in each of these areas, and a steady flow of its work comes from referred clients.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('stacey-r-ball-toronto','Stacey R. Ball','Toronto','ON','toronto',0,4.9,110,43.6720652,-79.3914511,'{"name":"Stacey R. Ball","city":"Toronto","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"toronto","province":"ON","lat":43.6720652,"lng":-79.3914511,"address":"82 Scollard St, Toronto, ON M5R 1G2","phone":"+14169217997","rating":4.9,"count":110,"slug":"stacey-r-ball-toronto","mapsUrl":"https://www.google.com/maps/search/Stacey+R.+Ball+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=82+Scollard+St%2C+Toronto%2C+ON+M5R+1G2","website":"https://www.wrongfuldismissal.ca","blurb":"Employment Law in Toronto. Rated 4.9 from 110 Google reviews.","type":"logo","src":"images/logos/stacey-r-ball-toronto.webp","details":{"lawyers":[{"name":"Stacey Reginald Ball"}],"areas":["Wrongful dismissal","Human rights","Sexual harassment","Bad faith discharge","Severance package","Constructive dismissal","Workplace disability","Exit agreements"],"serving":["Toronto","Ontario"]}}','{"1":[["09:00","18:00"]],"2":[["09:00","18:00"]],"3":[["09:00","18:00"]],"4":[["09:00","18:00"]],"5":[["09:00","17:00"]]}','Stacey Reginald Ball practises employment and labour law in Toronto, acting for employees, executives, professionals and employers. The practice dates from 1989 and operates as Ball Professional Corporation, and Mr. Ball has advised thousands of clients over more than 35 years. Matters include terminations, severance packages, resignations under pressure, allegations of just cause, employment agreements and wrongful dismissal, along with unfair labour practice complaints under the Canada Labour Code.

Mr. Ball is the author of Canadian Employment Law, a treatise published by Canada Law Book, and has acted as counsel in cases at every level of court, including the Supreme Court of Canada. He is called to the Ontario, Alberta and British Columbia bars and holds academic appointments at Osgoode Hall Law School and the University of Western Ontario''s Faculty of Law.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('imtiaz-ahmad-law-office-toronto','Imtiaz Ahmad Law Office','Toronto','ON','toronto',0,4.9,110,43.6811257,-79.3346725,'{"name":"Imtiaz Ahmad Law Office","city":"Toronto","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"toronto","province":"ON","lat":43.6811257,"lng":-79.3346725,"address":"1100 Danforth Ave, Toronto, ON M4J 1M3","phone":"+14164614747","rating":4.9,"count":110,"slug":"imtiaz-ahmad-law-office-toronto","mapsUrl":"https://www.google.com/maps/search/Imtiaz+Ahmad+Law+Office+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1100+Danforth+Ave%2C+Toronto%2C+ON+M4J+1M3","website":"https://www.ialaw.ca","blurb":"Family Law in Toronto. Rated 4.9 from 110 Google reviews.","type":"logo","src":"images/logos/imtiaz-ahmad-law-office-toronto.jpg"}',NULL,'Immigration, real estate and business law are handled at Imtiaz Ahmad Law Office, a Toronto firm on Danforth Avenue. Its immigration work covers the Federal Skilled Worker program, International Experience Canada, the Start-Up Visa Program and family sponsorship.

Real estate services include residential and commercial purchases, sales and leasing, development matters such as land acquisition and zoning, mortgages and refinancing, and title searches, for individuals, businesses and developers across Canada. Business law services extend from entity formation for start-ups to mergers and acquisitions for established corporations. The office, at 1100 Danforth Avenue, is open Monday to Friday from 11:00 AM to 6:00 PM.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('surya-law-toronto','Surya Law','Toronto','ON','toronto',0,5,107,43.7266907,-79.2314918,'{"name":"Surya Law","city":"Toronto","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.7266907,"lng":-79.2314918,"address":"3090 Kingston Rd Unit 202, Scarborough, ON M1M 1P2","phone":"+19052150793","rating":5,"count":107,"slug":"surya-law-toronto","mapsUrl":"https://www.google.com/maps/search/Surya+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=3090+Kingston+Rd+Unit+202%2C+Scarborough%2C+ON+M1M+1P2","website":"https://suryalaw.ca","blurb":"Real Estate in Toronto. Rated 5.0 from 107 Google reviews.","type":"logo","src":"images/logos/surya-law-toronto.webp","heroImage":"images/hero/surya-law-toronto.webp","details":{"languages":["Hindi","English","Gujarati","Swahili"],"lawyers":[{"name":"Surya Chakrabarti"},{"name":"Amin Sachedinas"}],"areas":["Real estate law","Immigration law","Family law","Wills and estates","Business and contract law","Notary services"],"serving":["Scarborough","Toronto","Mississauga","Brampton"]}}',NULL,'Surya Law serves Toronto, Scarborough and Brampton in real estate, immigration, family and wills and estates law. The firm was founded by Surya Chakrabarti, who practised at the Calcutta High Court in Kolkata and gained experience at Bose & Mitra in India before moving to Canada. It also handles business and contract law and notary services, and serves clients in Bangla, Hindi and English, among other languages.

Surya holds a Bachelor of Laws from the University of Burdwan and a Master of Laws from London Metropolitan University, articled with OWS Law, and built his real estate experience at Omar Zahid Law. He appears at courthouses across the GTA from an office on Kingston Road in Scarborough, and the team includes lawyer Amin Sachedinas and several legal associates.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lawpoint-north-york','Lawpoint','North York','ON','toronto',0,4.9,109,43.776033,-79.4141726,'{"name":"Lawpoint","city":"North York","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.776033,"lng":-79.4141726,"address":"5409 Yonge St #205, North York, ON M2N 5R6","phone":"+14162736646","rating":4.9,"count":109,"slug":"lawpoint-north-york","mapsUrl":"https://www.google.com/maps/search/Lawpoint+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5409+Yonge+St+%23205%2C+North+York%2C+ON+M2N+5R6","website":"https://lawpoint.ca","blurb":"Immigration in North York. Rated 4.9 from 109 Google reviews.","type":"logo","src":"images/logos/lawpoint-north-york.png","details":{"founded":2008,"areas":["Express Entry","Spousal and family sponsorship","Humanitarian and compassionate applications","Federal Court representation","Refugee claims","Work permits","Study permits","Immigration litigation","Citizenship applications"],"serving":["Toronto"]}}',NULL,'Lawpoint is a North York immigration firm handling visa refusal appeals, inadmissibility, permanent residence and work permits. Licensed in Ontario since 2008, it acts for individuals, families and businesses worldwide on matters from a first visitor visa to citizenship, including Express Entry, provincial nominee programs, study permits, LMIA applications and spousal and family sponsorship.

Litigation work includes inadmissibility hearings, mandamus applications and Federal Court proceedings after refusals, alongside humanitarian and compassionate applications, refugee matters and the restoration of permanent resident status. Immigration lawyer Tatiana Gulyaeva practises with the firm. Visits to the Yonge Street office near Finch Station are by appointment only.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('accord-law-professional-corporation-toronto','Accord Law Professional Corporation','Toronto','ON','toronto',0,5,106,43.784991,-79.255334,'{"name":"Accord Law Professional Corporation","city":"Toronto","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"toronto","province":"ON","lat":43.784991,"lng":-79.255334,"address":"1457 McCowan Rd Ste 209, Scarborough, ON M1S 5K7","phone":"+14162888000","rating":5,"count":106,"slug":"accord-law-professional-corporation-toronto","mapsUrl":"https://www.google.com/maps/search/Accord+Law+Professional+Corporation+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1457+McCowan+Rd+Ste+209%2C+Scarborough%2C+ON+M1S+5K7","website":"https://www.accordlaw.ca","blurb":"Real Estate / Wills & Estates in Toronto. Rated 5.0 from 106 Google reviews.","type":"logo","src":"images/logos/accord-law-professional-corporation-toronto.png","details":{"areas":["Real estate law","Immigration law","Wills and powers of attorney"],"serving":["Toronto","Scarborough","Markham","Richmond Hill","Pickering","Ajax","Mississauga","Brampton"]}}',NULL,'Real estate, immigration, wills and powers of attorney, and business law make up the work of Accord Law Professional Corporation in Toronto. Principal lawyer and founder Angat Saini worked for over 12 years as a real estate agent and has practised at a large Bay Street firm, where he handled immigration matters for clients ranging from individual applicants to multinational corporations.

The immigration group has advised on citizenship and business cases for more than 14 years, covering business immigration, resident permits, work permits and student visas for employers hiring from abroad and for individuals moving to Canada. The firm also provides notary public and commissioner of oaths services and offers its legal services in several languages.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('nav-law-firm-ottawa','NAV LAW FIRM','Ottawa','ON','eastern',0,4.9,108,45.417836,-75.690774,'{"name":"NAV LAW FIRM","city":"Ottawa","featured":false,"tags":["Family Law","Immigration","Real Estate"],"caseTypes":["family","immigration","realestate"],"region":"eastern","province":"ON","lat":45.417836,"lng":-75.690774,"address":"185 Somerset St W Ste 202, Ottawa, ON K2P 1L9","phone":"+16138903183","rating":4.9,"count":108,"slug":"nav-law-firm-ottawa","mapsUrl":"https://www.google.com/maps/search/NAV+LAW+FIRM+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=185+Somerset+St+W+Ste+202%2C+Ottawa%2C+ON+K2P+1L9","website":"https://www.navlaw.ca","blurb":"Family Law / Immigration in Ottawa. Rated 4.9 from 108 Google reviews.","type":"logo","src":"images/logos/nav-law-firm-ottawa.png","details":{"areas":["Real estate law","Family law","Wills and estates","Notary public"],"serving":["Ottawa"]}}',NULL,'NAV LAW FIRM is an Ottawa practice handling real estate, family law, wills and estates, immigration and notary public services. Navdeep Singh, its president, graduated from the G.N.D.U law school in Punjab, India in 2007 and practised there in real estate, family law, civil litigation, wills and immigration. After moving to Canada he passed the NCA licensing exam, was licensed in Ontario and became a partner at Ngieme & Associates Law Professional Corporation in Ottawa before opening his own firm.

He has appeared before the Superior Court of Justice in civil and family matters and has handled sales and purchases of residential property. The firm provides family law services to Ottawa and the surrounding area, along with mortgage work, from an office on Somerset Street West.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('deol-and-nagpal-law-firm-llp-brampton','Deol & Nagpal Law Firm LLP','Brampton','ON','peel-halton',0,4.6,114,43.7479403,-79.6990205,'{"name":"Deol & Nagpal Law Firm LLP","city":"Brampton","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"peel-halton","province":"ON","lat":43.7479403,"lng":-79.6990205,"address":"80 Maritime Ontario Blvd, Brampton, ON L6S 0E7","phone":"+19057960911","rating":4.6,"count":114,"slug":"deol-and-nagpal-law-firm-llp-brampton","mapsUrl":"https://www.google.com/maps/search/Deol+%26+Nagpal+Law+Firm+LLP+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=80+Maritime+Ontario+Blvd%2C+Brampton%2C+ON+L6S+0E7","website":"https://www.dnlawfirm.ca","blurb":"General practice law firm in Brampton. Rated 4.6 from 114 Google reviews.","type":"logo","src":"images/logos/deol-and-nagpal-law-firm-llp-brampton.png","details":{"lawyers":[{"name":"Birdavinder Singh Deol"},{"name":"Amanpreet Singh Nagpal"}],"areas":["Real estate law","Criminal law","Family law","Spousal sponsorship","Civil litigation","Immigration","Wrongful dismissal","Contract disputes","Small claims court","Business law"],"serving":["Greater Toronto"]}}',NULL,'In Brampton, Deol & Nagpal Law Firm LLP serves the GTA in real estate, criminal, family, immigration and civil litigation matters. The firm was founded by Birdavinder Singh Deol in partnership with Amanpreet Singh Nagpal. Its real estate practice covers purchases and sales of houses and condos, mortgages and refinancing, property transfers and taxes, and title insurance.

Criminal work includes bail, assault, theft, drug offences, impaired driving, fraud and youth criminal justice matters. The firm also acts in family law and spousal sponsorship, business law, powers of attorney, wills and estates, immigration and notary services, working from an office on Maritime Ontario Boulevard.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('east-law-hamilton','East Law','Hamilton','ON','hamilton-niagara',0,4.8,109,43.2549489,-79.8692775,'{"name":"East Law","city":"Hamilton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"hamilton-niagara","province":"ON","lat":43.2549489,"lng":-79.8692775,"address":"8 Main St E Ste 201, Hamilton, ON L8N 1E8","phone":"+18887197687","rating":4.8,"count":109,"slug":"east-law-hamilton","mapsUrl":"https://www.google.com/maps/search/East+Law+Hamilton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=8+Main+St+E+Ste+201%2C+Hamilton%2C+ON+L8N+1E8","website":"https://www.eastlaw.ca","blurb":"Criminal Defence in Hamilton. Rated 4.8 from 109 Google reviews.","type":"logo","src":"images/logos/east-law-hamilton.png","details":{"lawyers":[{"name":"John East"}],"areas":["Criminal defence","Drug offences","Property offences","Driving offences","Violent offences","Impaired driving","Weapons"]}}',NULL,'Criminal defence is all that East Law does in Hamilton, where it acts for people charged with drug, driving, violent and weapons offences. The firm litigates exclusively in criminal law and acts only for people who have been charged or have reason to believe that charges are pending.

Its practice covers drug offences, property offences, driving offences, violent offences, impaired driving and DUI charges, and weapons or firearms offences. John East is the lawyer behind the firm, and the office is located on Main Street East in Hamilton, Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('victoria-xu-law-office-toronto','​Victoria Xu Law Office','Toronto','ON','toronto',0,4.6,111,43.7881972,-79.2681072,'{"name":"​Victoria Xu Law Office","city":"Toronto","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"toronto","province":"ON","lat":43.7881972,"lng":-79.2681072,"address":"4438 Sheppard Ave E Unit 371,373,375, Scarborough, ON M1S 5V9","phone":"+16477485388","rating":4.6,"count":111,"slug":"victoria-xu-law-office-toronto","mapsUrl":"https://www.google.com/maps/search/%E2%80%8BVictoria+Xu+Law+Office+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=4438+Sheppard+Ave+E+Unit+371%2C373%2C375%2C+Scarborough%2C+ON+M1S+5V9","website":"https://www.victoriaxulaw.com","blurb":"Family Law in Toronto. Rated 4.6 from 111 Google reviews.","type":"logo","src":"images/logos/victoria-xu-law-office-toronto.png","details":{"lawyers":[{"name":"Victoria Xu"}],"areas":["Family law","Real estate","Wills and estates"],"serving":["Toronto"]}}',NULL,'Victoria Xu Law Office is a Toronto firm handling family law, wills and estates, and real estate matters across the GTA. Lawyer Victoria Xu has worked in family law, real estate, employment, immigration, wills and estates and contracts since 2015 and has appeared before several levels of court and administrative tribunals. She is an accredited mediator with OAFM and FDRIO, and family clients can proceed through litigation, mediation or limited scope services.

Other services include real estate transactions with mortgages and refinancing, wills, trusts and powers of attorney, civil litigation appearances, preparation of contracts and legal opinion letters, and document notarization and legalization. Ms. Xu belongs to the Ontario Bar Association, the Federation of Asian Canadian Lawyers and the Canadian Bar Association, and is also a member of the Law Society of Saskatchewan.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('satnam-grewal-criminal-defence-and-immigration-lawyer-kitchener','Satnam Grewal Criminal Defence and Immigration Lawyer','Kitchener','ON','waterloo-guelph',0,4.9,103,43.4533878,-80.4890375,'{"name":"Satnam Grewal Criminal Defence and Immigration Lawyer","city":"Kitchener","featured":false,"tags":["Immigration","Criminal Defence"],"caseTypes":["immigration","criminal"],"region":"waterloo-guelph","province":"ON","lat":43.4533878,"lng":-80.4890375,"address":"53 Roy St, Kitchener, ON N2H 4B4","phone":"+15195840769","rating":4.9,"count":103,"slug":"satnam-grewal-criminal-defence-and-immigration-lawyer-kitchener","mapsUrl":"https://www.google.com/maps/search/Satnam+Grewal+Criminal+Defence+and+Immigration+Lawyer+Kitchener+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=53+Roy+St%2C+Kitchener%2C+ON+N2H+4B4","website":"https://satnamgrewal.ca","blurb":"Immigration / Criminal Defence in Kitchener. Rated 4.9 from 103 Google reviews.","type":"logo","src":"images/logos/satnam-grewal-criminal-defence-and-immigration-lawyer-kitchener.png","details":{"lawyers":[{"name":"Satnam Singh Grewal","title":"Criminal & Immigration Lawyer"}],"areas":["Impaired driving","Dangerous driving","Assault","Family class sponsorship","Visitor visa","Work permit","Study permit","Humanitarian and compassionate grounds","Immigration detention review","Pre-removal risk assessment"]}}',NULL,'Satnam Grewal Criminal Defence and Immigration Lawyer practises in Kitchener, handling impaired driving cases, family sponsorships and work permits. The practice is led by Satnam Singh Grewal. On the criminal side it deals with impaired driving, driving under the influence and dangerous driving charges. On the immigration side it handles family class sponsorships for spouses, children and parents, as well as visitor visas, work permits and study permits.

Clients are served in Kitchener, Waterloo, Cambridge, Brantford, Woodstock, Hamilton and Milton. The office is on Roy Street in Kitchener, and fees are offered as flat rates or through flexible payment plans.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mor-fisher-llp-barrie','Mor Fisher LLP','Barrie','ON','simcoe-central',0,5,99,44.3909999,-79.6898659,'{"name":"Mor Fisher LLP","city":"Barrie","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"simcoe-central","province":"ON","lat":44.3909999,"lng":-79.6898659,"address":"31 Clapperton St, Barrie, ON L4M 3E6","phone":"+17057216642","rating":5,"count":99,"slug":"mor-fisher-llp-barrie","mapsUrl":"https://www.google.com/maps/search/Mor+Fisher+LLP+Barrie+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=31+Clapperton+St%2C+Barrie%2C+ON+L4M+3E6","website":"https://morfisher.ca","blurb":"Criminal Defence in Barrie. Rated 5.0 from 99 Google reviews.","type":"logo","src":"images/logos/mor-fisher-llp-barrie.png","details":{"lawyers":[{"name":"Jaime Mor"},{"name":"Jeffrey Fisher"}],"areas":["Criminal appeals","Assault defence","Bail hearings and reviews","Drug trafficking and possession","Firearms offences","Fraud and white-collar defence","Murder and manslaughter","Sexual assault defence","Youth criminal justice","Professional discipline and regulatory defence"],"serving":["Barrie","Orillia","Bradford","Collingwood","Midland","Parry Sound","Toronto"]}}',NULL,'Mor Fisher LLP, based in Barrie, defends people and businesses facing criminal, quasi-criminal and regulatory charges across Ontario. The firm does defence work only, covering impaired and dangerous driving, domestic and sexual assault, drug trafficking, firearms offences, fraud, robbery and youth criminal charges, as well as bail hearings, criminal appeals and dangerous offender applications. It also advises people and businesses under investigation and handles provincial offences and professional discipline.

The team includes Jaime Mor, Jeffrey Fisher, David Wilcox and David Lakie, who appear at courthouses across Central and Northern Ontario. The main office is in downtown Barrie, steps from the Superior Court of Justice, and the firm also serves Orillia, Collingwood, Midland, Bradford, Parry Sound and Toronto. Legal Aid certificates are accepted, and flat-fee billing is offered for most matters.','dynamic','live',NULL);
