INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('durno-and-shea-professional-corporation-toronto','Durno & Shea Professional Corporation','Toronto','ON','toronto',0,4.8,99,43.7620799,-79.2950176,'{"name":"Durno & Shea Professional Corporation","city":"Toronto","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.7620799,"lng":-79.2950176,"address":"505 Ellesmere Rd #3, Scarborough, ON M1R 4E5","phone":"+14167520720","rating":4.8,"count":99,"slug":"durno-and-shea-professional-corporation-toronto","mapsUrl":"https://www.google.com/maps/search/Durno+%26+Shea+Professional+Corporation+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=505+Ellesmere+Rd+%233%2C+Scarborough%2C+ON+M1R+4E5","website":"https://durnoandshea.ca","blurb":"Real Estate in Toronto. Rated 4.8 from 99 Google reviews.","type":"logo","src":"images/logos/durno-and-shea-professional-corporation-toronto.png","details":{"lawyers":[{"name":"Shannon Durno"},{"name":"Toloue Ghahraei"}],"areas":["Real estate transactions","Wills and powers of attorney","Estate administration","Status certificate review","New construction","Notary and commissioner services"]}}',NULL,'Founded in 1974, Durno & Shea Professional Corporation is a boutique firm in Toronto focused on residential real estate and estate law. Founding partners Robert Durno and Michael Shea began as a full-service practice covering everything from criminal law to real estate before narrowing to real estate and estate planning. Services include purchases, sales, refinancing, assignments, new construction and status certificates.

On the estate side the firm prepares wills and powers of attorney, assists with estate administration and offers notary and commissioner services. It handles assignment transactions, in which an original buyer transfers an agreement of purchase and sale to another buyer, most often for pre-built homes and condominiums. Shannon Durno is among its lawyers, and the office is in Scarborough on Ellesmere Road.','dynamic','live',NULL);
