INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('rohit-sharma-law-etobicoke','Rohit Sharma Law','Etobicoke','ON','toronto',0,4.7,97,43.7372207,-79.5645469,'{"name":"Rohit Sharma Law","city":"Etobicoke","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"toronto","province":"ON","lat":43.7372207,"lng":-79.5645469,"address":"1058a Albion Rd #200, Etobicoke, ON M9V 1A7","phone":"+14167411115","rating":4.7,"count":97,"slug":"rohit-sharma-law-etobicoke","mapsUrl":"https://www.google.com/maps/search/Rohit+Sharma+Law+Etobicoke+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1058a+Albion+Rd+%23200%2C+Etobicoke%2C+ON+M9V+1A7","website":"https://www.rohitlaw.ca","blurb":"General practice law firm in Etobicoke. Rated 4.7 from 97 Google reviews.","type":"logo","src":"images/logos/rohit-sharma-law-etobicoke.jpg","details":{"lawyers":[{"name":"Rohit Sharma"}],"areas":["Family law","Criminal law","Litigation"],"serving":["Toronto","GTA"]}}',NULL,'Rohit Sharma Law is an Etobicoke general practice serving Toronto and the GTA in family, criminal, real estate and civil litigation matters. Lawyer Rohit Sharma holds a Master''s degree in law, was called to the Ontario bar in 2019 and appears before the Ontario Court of Justice, the Superior Court of Justice, the Divisional Court and the Landlord Tenant Board. His matters have included contested custody and access, foreign divorce, real estate and employment disputes, and criminal cases.

Before practising in Ontario he spent three years as a litigation lawyer in the District Courts and High Court at Delhi, India, on criminal, family and civil matters. The firm''s services also include corporate law, notary public services and wills and estate law, and its office is on Albion Road.','dynamic','live',NULL);
