INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mitch-engel-criminal-lawyer-brampton-brampton','Mitch Engel Criminal Lawyer Brampton','Brampton','ON','peel-halton',0,4.7,29,43.662921,-79.727773,'{"name":"Mitch Engel Criminal Lawyer Brampton","city":"Brampton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.662921,"lng":-79.727773,"address":"2 County Ct Blvd Suite 400, Brampton, ON L6W 4V1","phone":"+14169448882","rating":4.7,"count":29,"slug":"mitch-engel-criminal-lawyer-brampton-brampton","mapsUrl":"https://www.google.com/maps/search/Mitch+Engel+Criminal+Lawyer+Brampton+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2+County+Ct+Blvd+Suite+400%2C+Brampton%2C+ON+L6W+4V1","website":"https://www.mitchengellaw.ca","blurb":"Criminal Defence in Brampton. Rated 4.7 from 29 Google reviews.","type":"logo","src":"images/logos/mitch-engel-criminal-lawyer-brampton-brampton.webp","details":{"lawyers":[{"name":"Mitch Engel"}],"areas":["Criminal defence","Driving offences","Property offences","Assault offences","Drug offences","Sexual offences","Weapons offences","Homicide offences"],"serving":["Brampton"]}}',NULL,'Since 1996, Mitch Engel has practised criminal defence from Brampton, serving the Oshawa, Brampton and Mississauga areas. He joined the Ontario bar in 1993, began at a small Toronto firm, and opened his own office, Mitch Engel, Barrister & Solicitor, three years later.

His practice is limited to criminal defence, with cases ranging from shoplifting and petty theft to white collar crime and murder investigations. Areas covered include driving offences such as impaired driving, property offences, assault, drug offences including possession for the purpose of trafficking, sexual offences, weapons offences, homicide and administration of justice offences. He is available 24 hours a day.','dynamic','live',NULL);
