INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('monique-j-charlebois-oakville','Monique J. Charlebois','Oakville','ON','peel-halton',0,5,25,43.4786904,-79.6580035,'{"name":"Monique J. Charlebois","city":"Oakville","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"peel-halton","province":"ON","lat":43.4786904,"lng":-79.6580035,"address":"Suite 205, 1540 Cornwall Rd, Oakville, ON L6J 7W5","phone":"+19058493939","rating":5,"count":25,"slug":"monique-j-charlebois-oakville","mapsUrl":"https://www.google.com/maps/search/Monique+J.+Charlebois+Oakville+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=Suite+205%2C+1540+Cornwall+Rd%2C+Oakville%2C+ON+L6J+7W5","website":"https://moniquecharlebois.ca","blurb":"Wills & Estates in Oakville. Rated 5.0 from 25 Google reviews.","type":"logo","src":"images/logos/monique-j-charlebois-oakville.png","bioImage":"images/bio/monique-j-charlebois-oakville.webp","details":{"lawyers":[{"name":"Monique Charlebois"}],"areas":["Wills and estates","Estate administration","Will drafting"]}}',NULL,'Estate administration, will drafting and dispute resolution are the practice of Monique Charlebois, a bilingual lawyer in Oakville. She has more than 20 years of experience in Ontario estates law and is a former Senior Estates Counsel with the Ontario Office of the Public Guardian and Trustee.

Services include advising estate trustees, obtaining a Certificate of Appointment of Estate Trustee with or without a will, acting as estate trustee, preparing wills, living wills and powers of attorney for property and personal care, and locating missing beneficiaries. She also helps beneficiaries understand the distribution of a deceased person''s assets. The office is on Cornwall Road in Oakville.','dynamic','live',NULL);
