INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('dimic-law-calgary','DIMIC LAW','Calgary','AB','ab-calgary',0,4.8,94,50.9688488,-114.0704283,'{"name":"DIMIC LAW","city":"Calgary","featured":false,"tags":["Civil Litigation","Business Law"],"caseTypes":["litigation","business"],"region":"ab-calgary","province":"AB","lat":50.9688488,"lng":-114.0704283,"address":"MACLEOD PLAZA #60, 180 94 Ave SE, Calgary, AB T2J 3G8","phone":"+14034575801","rating":4.8,"count":94,"slug":"dimic-law-calgary","mapsUrl":"https://www.google.com/maps/search/DIMIC+LAW+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=MACLEOD+PLAZA+%2360%2C+180+94+Ave+SE%2C+Calgary%2C+AB+T2J+3G8","website":"https://dimiclaw.ca","blurb":"Civil Litigation / Business Law in Calgary. Rated 4.8 from 94 Google reviews.","type":"logo","src":"images/logos/dimic-law-calgary.png","details":{"areas":["Personal injury","Slip and fall accidents","Motor vehicle accidents","Long term disability","Mergers and acquisitions","Incorporation services","Intellectual property","Real estate law","Commercial leases","Corporate financing"],"serving":["Calgary"]}}',NULL,'Dimic Law is a Calgary business and corporate law firm that also handles civil litigation, real estate, and wills and estates. The office is in Macleod Plaza on 94 Avenue SE.

