INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('zoe-arghandewal-nanaimo','Zoe Arghandewal','Nanaimo','BC','bc-island',0,4.7,52,49.167559,-123.9366491,'{"name":"Zoe Arghandewal","city":"Nanaimo","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"bc-island","province":"BC","lat":49.167559,"lng":-123.9366491,"address":"70 Church St Unit 2, Nanaimo, BC V9R 5H4","phone":"+12507139810","rating":4.7,"count":52,"slug":"zoe-arghandewal-nanaimo","mapsUrl":"https://www.google.com/maps/search/Zoe+Arghandewal+Nanaimo+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=70+Church+St+Unit+2%2C+Nanaimo%2C+BC+V9R+5H4","website":"https://arghandewal.ca","blurb":"Employment Law in Nanaimo. Rated 4.7 from 52 Google reviews.","type":"logo","src":"images/logos/zoe-arghandewal-nanaimo.webp","details":{"lawyers":[{"name":"Zoe Arghandewal"}],"areas":["Severance offers","Termination for cause","Employment contract review","Workplace discrimination and bullying","Human rights","Harassment in the workplace","Workplace investigations"],"serving":["Nanaimo","Vancouver Island"]}}',NULL,'Zoe Arghandewal is a Nanaimo lawyer handling wrongful dismissal, severance, human rights and workplace discrimination matters. A partner at Zargarian Litigation, she has more than seven years of experience, previously practised at her own firm, Arghandewal Law, and serves Nanaimo and all of Vancouver Island.

Most of her employment work is for workers, though she has also acted for some non-profit employers. It includes severance negotiations, discrimination and harassment complaints under the BC Human Rights Code, workplace investigations, mediations and reviewing employment contracts. She also defends criminal charges such as assault, theft, fraud and impaired driving in provincial and Supreme Court matters.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('stroll-law-group-vancouver','Stroll Law Group','Vancouver','BC','bc-vancouver',0,5,46,49.2663354,-123.1330875,'{"name":"Stroll Law Group","city":"Vancouver","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"bc-vancouver","province":"BC","lat":49.2663354,"lng":-123.1330875,"address":"1275 W 6th Ave 3rd floor, Vancouver, BC V6H 1A6","phone":"+16045688741","rating":5,"count":46,"slug":"stroll-law-group-vancouver","mapsUrl":"https://www.google.com/maps/search/Stroll+Law+Group+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1275+W+6th+Ave+3rd+floor%2C+Vancouver%2C+BC+V6H+1A6","website":"https://www.strolllawgroup.com","blurb":"General practice law firm in Vancouver. Rated 5.0 from 46 Google reviews.","type":"logo","src":"images/logos/stroll-law-group-vancouver.png","details":{"areas":["Business law","Entertainment law","Immigration law","Media, technology & intellectual property","Film and television agreements","Music licensing","Trademark registration","Family sponsorship"]}}',NULL,'Stroll Law Group is a Vancouver firm handling business, entertainment and immigration law for filmmakers, artists and entrepreneurs. Established in 2007, the practice is led by sole practitioner Orrin Stroll, a business and entertainment lawyer with more than 18 years of experience alongside independent film producers and production companies in Western Canada.

Entertainment work includes film and television agreements for every stage from development through production, post-production, delivery and distribution, as well as Errors and Omissions insurance. The firm also handles personal and business immigration matters under federal and provincial programs, plus general corporate and commercial work, and encourages clients to stay involved in and informed about their own legal matters.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('jiwa-law-corporation-surrey','Jiwa Law Corporation','Surrey','BC','bc-fraser',0,4.6,48,49.1772,-122.8415701,'{"name":"Jiwa Law Corporation","city":"Surrey","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"bc-fraser","province":"BC","lat":49.1772,"lng":-122.8415701,"address":"13761 96 Ave Ste 605, Surrey, BC V3V 0E8","phone":"+16045689444","rating":4.6,"count":48,"slug":"jiwa-law-corporation-surrey","mapsUrl":"https://www.google.com/maps/search/Jiwa+Law+Corporation+Surrey+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=13761+96+Ave+Ste+605%2C+Surrey%2C+BC+V3V+0E8","website":"https://www.jlc.ca","blurb":"Family Law in Surrey. Rated 4.6 from 48 Google reviews.","type":"logo","src":"images/logos/jiwa-law-corporation-surrey.png","details":{"languages":["Vietnamese","Punjabi","Hindi","Gujarati"],"lawyers":[{"name":"Farouk Jiwa"},{"name":"Sandra Jennings"},{"name":"Mandy Badwal"},{"name":"Shelly Butler"},{"name":"Wai Cheung"}],"areas":["Family law","Personal injury","Estate litigation"],"serving":["Vancouver","Surrey"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Jiwa Law Corporation is a Surrey and Vancouver firm handling family and divorce law and estate litigation. It has provided legal services in British Columbia for 17 years, and its team can assist clients in Vietnamese, Punjabi, Hindi and Gujarati.

Family work covers all aspects of family and divorce law. Estate litigation covers will challenges and validity disputes, wills variation, executor disputes and removal applications, beneficiary disputes and trust disputes under the Wills, Estates and Succession Act. The lawyers include Farouk Jiwa, Sandra Jennings, Mandy Badwal and Wai Cheung.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('nirwan-law-corporation-surrey','Nirwan Law Corporation','Surrey','BC','bc-fraser',0,4.8,44,49.177393,-122.842861,'{"name":"Nirwan Law Corporation","city":"Surrey","featured":false,"tags":["Personal Injury","Civil Litigation"],"caseTypes":["injury","litigation"],"region":"bc-fraser","province":"BC","lat":49.177393,"lng":-122.842861,"address":"13737 96 Ave, Surrey, BC V3V 0C6","phone":"+16043720253","rating":4.8,"count":44,"slug":"nirwan-law-corporation-surrey","mapsUrl":"https://www.google.com/maps/search/Nirwan+Law+Corporation+Surrey+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=13737+96+Ave%2C+Surrey%2C+BC+V3V+0C6","website":"https://nirwanlawcorp.com","blurb":"Personal Injury / Civil Litigation in Surrey. Rated 4.8 from 44 Google reviews.","type":"logo","src":"images/logos/nirwan-law-corporation-surrey.png","heroImage":"images/hero/nirwan-law-corporation-surrey.webp","details":{"lawyers":[{"name":"Harpreet S. Nirwan"},{"name":"Radhika Sandur"}],"areas":["Car accidents","Cyclist accidents","Hit & run accidents","Wrongful death","Pedestrian injuries","Workplace accidents","Motorcycle accidents","Truck accidents","Slip & fall claims","Medical malpractice"],"serving":["Washington","British Columbia","Alberta"]}}',NULL,'Nirwan Law Corporation is a Surrey personal injury firm handling car, pedestrian, bicycle and motorcycle accidents and slip and falls. Founded in 2014, the firm acts for people injured through someone else''s negligence.

It operates from two head offices, one in British Columbia and one in Washington state, and its lawyers are licensed to practise in British Columbia, Alberta, Washington, Texas and other American jurisdictions. The firm handles each case from the first meeting with a client through to litigation.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('truman-law-surrey','Truman Law','Surrey','BC','bc-fraser',0,5,42,49.1357373,-122.8432466,'{"name":"Truman Law","city":"Surrey","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"bc-fraser","province":"BC","lat":49.1357373,"lng":-122.8432466,"address":"7327 137 St #302, Surrey, BC V3W 1A4","phone":"+16048281313","rating":5,"count":42,"slug":"truman-law-surrey","mapsUrl":"https://www.google.com/maps/search/Truman+Law+Surrey+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7327+137+St+%23302%2C+Surrey%2C+BC+V3W+1A4","website":"https://www.trumanlaw.ca","blurb":"General practice law firm in Surrey. Rated 5.0 from 42 Google reviews.","type":"logo","src":"images/logos/truman-law-surrey.png","details":{"lawyers":[{"name":"Harkirat Singh Kang"}],"areas":["Real estate","Business law","Civil litigation","Estate planning","Powers of attorney","Representation agreements","Wills","Notarization","Foreclosures"]}}',NULL,'Truman Law is a Surrey firm advising on real estate, corporate matters, civil litigation, foreclosures and estate planning. Principal lawyer Harkirat Singh Kang founded it in 2020 as a litigation practice and expanded into residential and commercial real estate in 2021.

He was called to the bar in Delhi in 2013, Ontario in 2016 and British Columbia in 2017, and has appeared in the Provincial Court and the Supreme Court of British Columbia. His real estate work includes foreclosures, encumbered titles, private lending, corporate ownership structures and non-standard closings, and the firm also prepares wills, powers of attorney and representation agreements.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mike-beckett-law-surrey','Mike Beckett Law','Surrey','BC','bc-fraser',0,4.9,42,49.1380326,-122.8575195,'{"name":"Mike Beckett Law","city":"Surrey","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"bc-fraser","province":"BC","lat":49.1380326,"lng":-122.8575195,"address":"7445 132 St Unit 1012, Surrey, BC V3W 1J8","phone":"+16047872258","rating":4.9,"count":42,"slug":"mike-beckett-law-surrey","mapsUrl":"https://www.google.com/maps/search/Mike+Beckett+Law+Surrey+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7445+132+St+Unit+1012%2C+Surrey%2C+BC+V3W+1J8","website":"https://mikebeckettlaw.ca","blurb":"Criminal Defence in Surrey. Rated 4.9 from 42 Google reviews.","type":"logo","src":"images/logos/mike-beckett-law-surrey.png","details":{"lawyers":[{"name":"Michael A. Beckett","title":"Barrister & Solicitor"}],"areas":["Assault & domestic violence","Violent criminal offences","Drug & trafficking charges","Theft & fraud charges","Robbery & extortion","Sexual offences","Impaired driving offences","Firearm & weapons offences","Murder & homicide","Prison law"],"serving":["Vancouver","Surrey","British Columbia","Alberta","Saskatchewan"]}}',NULL,'Mike Beckett Law is a Surrey criminal defence practice acting for people charged with or under investigation for criminal offences. Michael Beckett is a criminal defence and trial lawyer who practises mainly in Metro Vancouver and appears in Provincial Court, Supreme Court and the Court of Appeal of British Columbia.

The practice covers crimes of violence, sexual offences, theft and fraud, drug trafficking and production, impaired driving, firearms offences and computer crime. He has also appeared in Alberta and Saskatchewan courts and in hearings for people found Not Criminally Responsible on account of Mental Disorder, and has advised businesses in the medicinal marijuana and online gambling industries on legal compliance.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('carraig-law-group-llp-vancouver','Carraig Law Group LLP','Vancouver','BC','bc-vancouver',0,4.6,40,49.2844081,-123.1159333,'{"name":"Carraig Law Group LLP","city":"Vancouver","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"bc-vancouver","province":"BC","lat":49.2844081,"lng":-123.1159333,"address":"543 Granville St #600, Vancouver, BC V6C 1X8","phone":"+17789071180","rating":4.6,"count":40,"slug":"carraig-law-group-llp-vancouver","mapsUrl":"https://www.google.com/maps/search/Carraig+Law+Group+LLP+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=543+Granville+St+%23600%2C+Vancouver%2C+BC+V6C+1X8","website":"https://www.carraiglaw.com","blurb":"Family Law in Vancouver. Rated 4.6 from 40 Google reviews.","type":"logo","src":"images/logos/carraig-law-group-llp-vancouver.png","details":{"languages":["Mandarin","Cantonese","Punjabi","Portuguese","Farsi"],"areas":["Family law","Commercial litigation","Wills and estates law","Sports law","Administrative law","Real estate law","Refugee protection","Mediation"]}}',NULL,'Carraig Law Group LLP is a Vancouver trial law firm handling family law, commercial litigation, sports law and wills drafting. The name is the Irish word for rock, and lawyers Dermot Devine, Sophie Gruyich and Ronald Wong act in lawsuits for individuals, companies and organizations.

Family matters include child support, parenting time, divorce, spousal support, property division, separation and marriage agreements, guardianship, child protection and child abduction. Litigation extends to construction, insurance, defamation, refugee protection and collections, and the firm helps athletes, parents, coaches and sporting organizations through disciplinary procedures.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('einfeld-law-kelowna','Einfeld Law','Kelowna','BC','bc-okanagan',0,5,36,49.8970554,-119.4962039,'{"name":"Einfeld Law","city":"Kelowna","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"bc-okanagan","province":"BC","lat":49.8970554,"lng":-119.4962039,"address":"1060 Manhattan Dr Ste. 160, Kelowna, BC V1Y 9X9","phone":"+12507120001","rating":5,"count":36,"slug":"einfeld-law-kelowna","mapsUrl":"https://www.google.com/maps/search/Einfeld+Law+Kelowna+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1060+Manhattan+Dr+Ste.+160%2C+Kelowna%2C+BC+V1Y+9X9","website":"https://www.einfeldlaw.com","blurb":"Personal Injury in Kelowna. Rated 5.0 from 36 Google reviews.","type":"logo","src":"images/logos/einfeld-law-kelowna.webp","details":{"lawyers":[{"name":"Glenn Einfeld"},{"name":"Casey Trivett"},{"name":"Monika Krenz"}],"areas":["Personal injury","Civil litigation"],"serving":["Kelowna"]}}',NULL,'Einfeld Law is a Kelowna civil litigation and personal injury firm acting in lawsuits, estate disputes and employment matters. It acts for individuals and businesses in civil lawsuits in the Okanagan and beyond, including contract disputes, insurance disputes, property disputes and matters involving municipalities.

Business litigation includes breach of contract, negligence, lease disputes, builders liens and product liability. Estate work covers contested wills, wills variation, trust litigation and executor disputes, with arbitration and mediation available, and employment work covers wrongful dismissal and severance. Injury cases arise from negligence such as slips and falls and unsafe property; the firm does not act on ICBC motor vehicle injury cases.','dynamic','live',NULL);
