INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('surrovik-law-corporation-surrey','Surrovik Law Corporation','Surrey','BC','bc-fraser',0,5,24,49.192347,-122.8459648,'{"name":"Surrovik Law Corporation","city":"Surrey","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"bc-fraser","province":"BC","lat":49.192347,"lng":-122.8459648,"address":"RPO Central City, Surrey, BC V3T 5R5","phone":"+17785327705","rating":5,"count":24,"slug":"surrovik-law-corporation-surrey","mapsUrl":"https://www.google.com/maps/search/Surrovik+Law+Corporation+Surrey+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=RPO+Central+City%2C+Surrey%2C+BC+V3T+5R5","website":"https://www.surroviklawcorporation.ca","blurb":"General practice law firm in Surrey. Rated 5.0 from 24 Google reviews.","type":"logo","src":"images/logos/surrovik-law-corporation-surrey.png","details":{"areas":["Family law","Civil law","Divorce","Child support","Spousal support","Contract disputes","Insurance claims","Personal injury claims"],"serving":["Vancouver"]}}',NULL,'Surrovik Law Corporation is a Surrey firm handling family law and civil matters, including divorce, child support and personal injury. Jagriti Jaswal founded the firm, and its lawyers act for clients in Vancouver and the surrounding area.

Family services cover divorce, pre- and post-nuptial agreements, child and spousal support, property division, domestic violence and guardianship, and civil work covers contract disputes, insurance matters and personal injury. Jagriti Jaswal works mainly in family and personal injury law, has appeared in the provincial and supreme courts, and negotiates or mediates for clients whenever possible. Umed Singh is also part of the team.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('the-law-portal-vancouver','The Law Portal','Vancouver','BC','bc-vancouver',0,4.8,24,49.2830026,-123.1217871,'{"name":"The Law Portal","city":"Vancouver","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"bc-vancouver","province":"BC","lat":49.2830026,"lng":-123.1217871,"address":"777 Hornby St Suite 600, Vancouver, BC V6Z 1S4","phone":"+17783282828","rating":4.8,"count":24,"slug":"the-law-portal-vancouver","mapsUrl":"https://www.google.com/maps/search/The+Law+Portal+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=777+Hornby+St+Suite+600%2C+Vancouver%2C+BC+V6Z+1S4","website":"https://thelawportal.ca","blurb":"General practice law firm in Vancouver. Rated 4.8 from 24 Google reviews.","type":"logo","src":"images/logos/the-law-portal-vancouver.jpg","details":{"serving":["British Columbia"]}}',NULL,'The Law Portal is a Vancouver-based virtual family law firm representing clients anywhere in British Columbia. Its family law team includes Sarah Miller, Katya Richardson in Vancouver, Christine Inducil in Abbotsford, Tiara Flores and Dawn Shandley.

The firm handles divorce, with uncontested divorces starting at $750, and prepares cohabitation, marriage and separation agreements and parenting plans. Disputes are approached first through negotiation and mediation, with court advocacy when those fail. Forms are signed electronically, an optional client portal is provided, and meetings are normally held remotely, with in-person meetings available at the downtown Vancouver head office.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('maio-family-law-kelowna','Maio Family Law','Kelowna','BC','bc-okanagan',0,4.8,24,49.8879931,-119.4931714,'{"name":"Maio Family Law","city":"Kelowna","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"bc-okanagan","province":"BC","lat":49.8879931,"lng":-119.4931714,"address":"1441 Ellis St Unit 202, Kelowna, BC V1Y 2A3","phone":"+17787600017","rating":4.8,"count":24,"slug":"maio-family-law-kelowna","mapsUrl":"https://www.google.com/maps/search/Maio+Family+Law+Kelowna+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1441+Ellis+St+Unit+202%2C+Kelowna%2C+BC+V1Y+2A3","website":"https://maiolaw.com","blurb":"Family Law in Kelowna. Rated 4.8 from 24 Google reviews.","type":"logo","src":"images/logos/maio-family-law-kelowna.png","details":{"founded":2014,"lawyers":[{"name":"Domenic Maio"}],"areas":["Separation and divorce","Family law agreements","Custody","Child support","Relocation","Spousal support","Property division"],"serving":["Kelowna","Lake Country","Peachland"]}}',NULL,'Maio Family Law is a boutique Kelowna family law firm handling separation, divorce, parenting arrangements, support and property division. Domenic Maio owns and operates the firm and is called to the bar in both British Columbia and Ontario, which lets him assist clients relocating between the two provinces.

He has provided legal services in Ontario since 2014, practising in criminal, real estate, corporate and family law and preparing wills and powers of attorney, before opening the Kelowna office in 2018 with a focus on family law. He appears in both the Provincial Court and the Supreme Court of British Columbia, and the firm also covers family law agreements, relocation and real estate purchases and sales.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bay-view-law-employment-lawyers-kelowna','Bay View Law Employment Lawyers','Kelowna','BC','bc-okanagan',0,4.8,21,49.88426,-119.495882,'{"name":"Bay View Law Employment Lawyers","city":"Kelowna","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"bc-okanagan","province":"BC","lat":49.88426,"lng":-119.495882,"address":"347 Leon Ave Ste 210, Kelowna, BC V1Y 8C7","phone":"+16044162610","rating":4.8,"count":21,"slug":"bay-view-law-employment-lawyers-kelowna","mapsUrl":"https://www.google.com/maps/search/Bay+View+Law+Employment+Lawyers+Kelowna+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=347+Leon+Ave+Ste+210%2C+Kelowna%2C+BC+V1Y+8C7","website":"https://bvlaw.ca","blurb":"Employment Law in Kelowna. Rated 4.8 from 21 Google reviews.","type":"logo","src":"images/logos/bay-view-law-employment-lawyers-kelowna.png","bioImage":"images/bio/bay-view-law-employment-lawyers-kelowna.webp","details":{"lawyers":[{"name":"Aleks Kukolj","title":"Barrister & Solicitor"}],"areas":["Wrongful dismissal","Constructive dismissal","Severance claims","Employment law","Maternity and parental leave"],"serving":["Vancouver","Kelowna","British Columbia"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Bay View Law Employment Lawyers is a Kelowna firm acting for British Columbia employees in wrongful dismissal, layoff and severance matters. It has offices in Kelowna and Vancouver, and lawyer Aleks Kukolj is named for both.

The firm represents employees in termination, constructive dismissal and layoff disputes, assesses reasonable notice and severance entitlements, and helps negotiate employment arrangements. It also advises on workplace bullying and harassment, discrimination and maternity and parental leave. Vancouver work focuses on dismissals and layoffs among workers in sectors such as technology, hospitality, film and construction.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('velletta-pedersen-christie-lawyers-victoria','Velletta Pedersen Christie Lawyers','Victoria','BC','bc-victoria',0,4.5,153,48.4236972,-123.3585215,'{"name":"Velletta Pedersen Christie Lawyers","city":"Victoria","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"bc-victoria","province":"BC","lat":48.4236972,"lng":-123.3585215,"address":"931 Fort St 4th Floor, Victoria, BC V8V 3K3","phone":"+12503839104","rating":4.5,"count":153,"slug":"velletta-pedersen-christie-lawyers-victoria","mapsUrl":"https://www.google.com/maps/search/Velletta+Pedersen+Christie+Lawyers+Victoria+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=931+Fort+St+4th+Floor%2C+Victoria%2C+BC+V8V+3K3","website":"https://www.victorialaw.ca","blurb":"General practice law firm in Victoria. Rated 4.5 from 153 Google reviews.","type":"logo","src":"images/logos/velletta-pedersen-christie-lawyers-victoria.webp","bioImage":"images/bio/velletta-pedersen-christie-lawyers-victoria.webp","details":{"lawyers":[{"name":"Michael J. Velletta","title":"Partner"},{"name":"Gregory T. Rhone"},{"name":"W. Eric Pedersen"},{"name":"Cadeyrn Christie"},{"name":"Natalia M. Velletta"},{"name":"Alison Rhynas"},{"name":"Stan Osobik"},{"name":"Eric Clausen"},{"name":"Sankar Nair"},{"name":"Candace Rissley"},{"name":"Claire McOuat"},{"name":"Ciara McLean"}],"areas":["Business and entrepreneur law","Real estate law","Litigation","Family law","Immigration law","Wills and estates law","Employment law","Personal injury law","Entertainment law"],"serving":["Victoria","Canada"]}}','{"1":[["08:30","17:00"]],"2":[["08:30","17:00"]],"3":[["08:30","17:00"]],"4":[["08:30","17:00"]],"5":[["08:30","17:00"]]}','Velletta Pedersen Christie Lawyers is a full-service Victoria firm covering litigation, corporate, real estate, family and estates law. Practising since 1982, it acts for clients in Victoria, across Canada and abroad.

Its business work includes contracts, publishing companies, royalty agreements and non-disclosure agreements, along with share and asset purchases, and it also handles immigration, employment, personal injury and entertainment law. Its lawyers have appeared before the Supreme Court of Canada, the British Columbia Court of Appeal, the Federal Court of Canada and the Court Martial Appeal Court of Canada.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('george-lee-law-corp-burnaby','George Lee Law Corp','Burnaby','BC','bc-burnaby',0,4.5,115,49.229653,-123.004196,'{"name":"George Lee Law Corp","city":"Burnaby","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"bc-burnaby","province":"BC","lat":49.229653,"lng":-123.004196,"address":"4538 Kingsway #608, Burnaby, BC V5H 4T9","phone":"+16046811611","rating":4.5,"count":115,"slug":"george-lee-law-corp-burnaby","mapsUrl":"https://www.google.com/maps/search/George+Lee+Law+Corp+Burnaby+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=4538+Kingsway+%23608%2C+Burnaby%2C+BC+V5H+4T9","website":"https://gleelaw.com","blurb":"General practice law firm in Burnaby. Rated 4.5 from 115 Google reviews.","type":"logo","src":"images/logos/george-lee-law-corp-burnaby.png","details":{"founded":2002,"languages":["English","Mandarin","Korean"],"lawyers":[{"name":"George Lee","title":"Founder"},{"name":"James Lee","title":"Associate Counsel"}],"areas":["Family law","Civil litigation","Immigration law","Criminal defence"],"serving":["Burnaby","Vancouver","Lower Mainland","British Columbia"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','George Lee Law Corporation is a Burnaby firm handling family, civil, immigration and criminal matters from its Metrotown office. George Lee has practised since 2002, and the firm serves Vancouver, Burnaby and the rest of British Columbia in English, Mandarin and Korean.

Lawyers George Lee and James Lee approach disputes by first looking for a practical resolution such as clear advice, a firm letter, negotiation, a four-way meeting or mediation, and they prepare the evidence for court when it becomes necessary. The firm also takes selected solicitor matters including conveyancing, and offers virtual meetings when appropriate.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('hutchison-oss-cech-marlatt-victoria','Hutchison Oss-Cech Marlatt','Victoria','BC','bc-victoria',0,4.5,67,48.4292306,-123.3692832,'{"name":"Hutchison Oss-Cech Marlatt","city":"Victoria","featured":false,"tags":["Personal Injury","Family Law"],"caseTypes":["injury","family"],"region":"bc-victoria","province":"BC","lat":48.4292306,"lng":-123.3692832,"address":"505 Fisgard St #1, Victoria, BC V8W 1R3","phone":"+12503602500","rating":4.5,"count":67,"slug":"hutchison-oss-cech-marlatt-victoria","mapsUrl":"https://www.google.com/maps/search/Hutchison+Oss-Cech+Marlatt+Victoria+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=505+Fisgard+St+%231%2C+Victoria%2C+BC+V8W+1R3","website":"https://www.hom-law.com","blurb":"Personal Injury / Family Law in Victoria. Rated 4.5 from 67 Google reviews.","type":"logo","src":"images/logos/hutchison-oss-cech-marlatt-victoria.png","details":{"lawyers":[{"name":"James S. Hutchison"}],"areas":["Personal injury claims","Civil law"],"serving":["Victoria"]}}',NULL,'Hutchison Oss-Cech Marlatt is a full-service Victoria law firm with personal injury, family, estate and corporate practices. It is led by James S. Hutchison, Lorenzo G. Oss-Cech and Barri A. Marlatt, and does not take criminal cases.

Personal injury work covers motor vehicle, motorcycle, bicycle, pedestrian, boating and aircraft accidents, brain injury and WCB appeals. The firm also handles employment law, construction and commercial disputes, wills and estate planning, estate litigation and wills variation, defamation, and business matters such as mergers and acquisitions, intellectual property and lending.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('a-s-mattoo-and-associates-law-office-kamloops','A.S. Mattoo & Associates Law Office','Kamloops','BC','bc-thompson',0,4.5,53,50.6750876,-120.3238419,'{"name":"A.S. Mattoo & Associates Law Office","city":"Kamloops","featured":false,"tags":["Immigration","Real Estate","Wills & Estates"],"caseTypes":["immigration","realestate","wills"],"region":"bc-thompson","province":"BC","lat":50.6750876,"lng":-120.3238419,"address":"712 Seymour St, Kamloops, BC V2C 2H3","phone":"+12503743337","rating":4.5,"count":53,"slug":"a-s-mattoo-and-associates-law-office-kamloops","mapsUrl":"https://www.google.com/maps/search/A.S.+Mattoo+%26+Associates+Law+Office+Kamloops+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=712+Seymour+St%2C+Kamloops%2C+BC+V2C+2H3","website":"https://mattoolaw.com","blurb":"Immigration / Real Estate in Kamloops. Rated 4.5 from 53 Google reviews.","type":"logo","src":"images/logos/a-s-mattoo-and-associates-law-office-kamloops.png","details":{"lawyers":[{"name":"Steve Mattoo"},{"name":"Jas Dhaliwal","title":"Associate"}],"areas":["Real estate law","Commercial transactions","Refinances","Wills and estates","Corporate law","Taxpayer representation"],"serving":["Surrey"]}}',NULL,'Mattoo & Associates is a Kamloops law office handling residential and commercial real estate, mortgages, wills and estates, and corporate law. A.S. Mattoo & Associates is led by Amrik S. (Steve) Mattoo, who works with associate Jas Dhaliwal, and the lawyers and senior staff bring more than two decades of combined conveyancing experience.

Commercial real estate work includes the acquisition and sale of office buildings, apartment buildings and shopping centres. The firm also represents taxpayers in CRA audits, appeals and the Tax Court of Canada, working with a former CRA tax auditor who has 23 years of experience in investigations, appeals and audits, and assists families with the transfer of estates on death.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kazlaw-injury-lawyers-vancouver','KazLaw Injury Lawyers','Vancouver','BC','bc-vancouver',0,4.5,49,49.2838095,-123.1158094,'{"name":"KazLaw Injury Lawyers","city":"Vancouver","featured":false,"tags":["Personal Injury","Civil Litigation"],"caseTypes":["injury","litigation"],"region":"bc-vancouver","province":"BC","lat":49.2838095,"lng":-123.1158094,"address":"570 Granville St #1900, Vancouver, BC V6C 3P1","phone":"+16046819344","rating":4.5,"count":49,"slug":"kazlaw-injury-lawyers-vancouver","mapsUrl":"https://www.google.com/maps/search/KazLaw+Injury+Lawyers+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=570+Granville+St+%231900%2C+Vancouver%2C+BC+V6C+3P1","website":"https://www.kazlaw.ca","blurb":"Personal Injury / Civil Litigation in Vancouver. Rated 4.5 from 49 Google reviews.","type":"logo","src":"images/logos/kazlaw-injury-lawyers-vancouver.png","details":{"founded":2007,"lawyers":[{"name":"Marc Kazimirski","title":"Founding Partner"}],"areas":["Personal injury","ICBC claims","Sexual abuse","Car accident","Bike accident","Pedestrian accidents","Motorcycle accident"],"serving":["Vancouver","Surrey","Victoria"]}}',NULL,'KazLaw Injury Lawyers is a Vancouver personal injury firm acting only for injured people in ICBC and other injury cases. It has Vancouver and Surrey offices and merged with the Victoria firm Robert W. Cameron Law Corporation, and its trial lawyers do not act for ICBC or other insurance companies.

Founding partner Marc Kazimirski was a member of the Canadian national team in cyclocross and mountain biking and advocates for cyclists across British Columbia. He created the KazLaw Community Foundation, which sponsors young athletes, including a program that sends two riders to the BC Bike Race. Lawyers include Hermanie Chiong, George Rainforth, Sandra Kovacs and Mallory Hogan.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('snowdon-and-terepocki-llp-abbotsford','Snowdon & Terepocki LLP','Abbotsford','BC','bc-fraser',0,4.5,46,49.0457966,-122.2877572,'{"name":"Snowdon & Terepocki LLP","city":"Abbotsford","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"bc-fraser","province":"BC","lat":49.0457966,"lng":-122.2877572,"address":"33832 South Fraser Way #100, Abbotsford, BC V2S 2C5","phone":"+16047441066","rating":4.5,"count":46,"slug":"snowdon-and-terepocki-llp-abbotsford","mapsUrl":"https://www.google.com/maps/search/Snowdon+%26+Terepocki+LLP+Abbotsford+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=33832+South+Fraser+Way+%23100%2C+Abbotsford%2C+BC+V2S+2C5","website":"https://www.gstlegal.ca","blurb":"Family Law in Abbotsford. Rated 4.5 from 46 Google reviews.","type":"logo","src":"images/logos/snowdon-and-terepocki-llp-abbotsford.png","details":{"lawyers":[{"name":"Ondine Snowdon"},{"name":"Christopher Terepocki"}],"areas":["Civil litigation","Family law","Human rights","Prison law","Administrative law","Criminal law","Driving offences"]}}',NULL,'Snowdon & Terepocki LLP, known as GS&T LLP, is an Abbotsford criminal defence firm handling driving offences across the Fraser Valley. It was opened by former colleagues Tonia Grace, Ondine Snowdon and Chris Terepocki as Grace, Snowdon & Terepocki LLP.

Criminal work includes drug offences such as possession, trafficking and production, while driving work covers immediate roadside prohibitions of 3, 30 and 90 days and violation tickets. The firm also handles civil litigation, family law, human rights, prison law and administrative law, appears in courts from Abbotsford and Chilliwack to Vancouver, New Westminster, Surrey and Port Coquitlam, and is available around the clock on driving matters.','dynamic','live',NULL);
