INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('meridian-law-group-vancouver','Meridian Law Group','Vancouver','BC','bc-vancouver',0,4.5,39,49.2799262,-123.1244648,'{"name":"Meridian Law Group","city":"Vancouver","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"bc-vancouver","province":"BC","lat":49.2799262,"lng":-123.1244648,"address":"808 Nelson St #1401, Vancouver, BC V6Z 2H2","phone":"+16046872277","rating":4.5,"count":39,"slug":"meridian-law-group-vancouver","mapsUrl":"https://www.google.com/maps/search/Meridian+Law+Group+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=808+Nelson+St+%231401%2C+Vancouver%2C+BC+V6Z+2H2","website":"https://meridianlawgroup.ca","blurb":"Real Estate in Vancouver. Rated 4.5 from 39 Google reviews.","type":"logo","src":"images/logos/meridian-law-group-vancouver.webp","details":{"founded":1988,"lawyers":[{"name":"Alina Petraru"}],"areas":["Property disputes","Commercial litigation","Estates","Family law","Personal injury"],"serving":["Vancouver"]}}',NULL,'Meridian Law Group is a Vancouver litigation firm acting in commercial, estate, family, insurance and personal injury disputes. Founded in 1988, the firm is based in the Nelson Square building in downtown Vancouver and acts for clients across Canada and internationally.

Its litigators appear before all levels of court in British Columbia and also use arbitration and mediation to resolve disputes where possible. Practice areas include property disputes, commercial litigation, estate litigation, family law, insurance litigation and personal injury, with topics such as prenuptial agreements and shareholder oppression in family companies.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('alice-huynh-law-corporation-vancouver','Alice Huynh Law Corporation','Vancouver','BC','bc-vancouver',0,4.5,34,49.2637821,-123.1332617,'{"name":"Alice Huynh Law Corporation","city":"Vancouver","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"bc-vancouver","province":"BC","lat":49.2637821,"lng":-123.1332617,"address":"600, 1285 W Broadway 6th Floor, Vancouver, BC V6H 3X8","phone":"+17787929889","rating":4.5,"count":34,"slug":"alice-huynh-law-corporation-vancouver","mapsUrl":"https://www.google.com/maps/search/Alice+Huynh+Law+Corporation+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=600%2C+1285+W+Broadway+6th+Floor%2C+Vancouver%2C+BC+V6H+3X8","website":"https://alicehuynhlaw.com","blurb":"General practice law firm in Vancouver. Rated 4.5 from 34 Google reviews.","type":"logo","src":"images/logos/alice-huynh-law-corporation-vancouver.png","details":{"languages":["Vietnamese"],"lawyers":[{"name":"Alice Huynh"}],"areas":["Estate planning","Wills","Powers of attorney","Representation agreements","Adult guardianship"],"serving":["Burnaby","Vancouver"]}}',NULL,'Alice Huynh Law Corporation is a Vancouver firm handling family law, civil disputes and estate disputes, with service available in Vietnamese. It has offices on West Broadway in Vancouver and on Edmonds Street in Burnaby.

Family services cover separation agreements, divorce, parenting arrangements, child and spousal support, the division of assets and debt, cohabitation and pre-nuptial agreements, and adoption applications. The firm also represents individuals, businesses and government entities in civil disputes and helps with will and estate conflicts, including challenges to a will''s validity, disputes over an executor''s actions and allegations of undue influence.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('trivium-law-richmond','Trivium Law','Richmond','BC','bc-richmond',0,4.5,32,49.1835646,-123.0722591,'{"name":"Trivium Law","city":"Richmond","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"bc-richmond","province":"BC","lat":49.1835646,"lng":-123.0722591,"address":"4320 Viking Wy #260, Richmond, BC V6V 2L4","phone":"+16042421578","rating":4.5,"count":32,"slug":"trivium-law-richmond","mapsUrl":"https://www.google.com/maps/search/Trivium+Law+Richmond+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=4320+Viking+Wy+%23260%2C+Richmond%2C+BC+V6V+2L4","website":"https://www.triviumlaw.com","blurb":"Real Estate / Wills & Estates in Richmond. Rated 4.5 from 32 Google reviews.","type":"logo","src":"images/logos/trivium-law-richmond.png","details":{"lawyers":[{"name":"Gary Hou"},{"name":"Tony Su"},{"name":"Jenny Ruan"},{"name":"Steven Liu"}],"areas":["Business law","Real estate law","Wills and estates","Business acquisition and sale","Business entity structuring"]}}',NULL,'Trivium Law is a Richmond firm handling business, real estate, and wills and estates matters, with offices in Richmond and Vancouver. Business work runs from entity setup and financing to shareholder and partnership agreements, acquisitions, franchising and commercial leasing.

Real estate services cover purchases, sales, financing and development, including REDMA compliance, pre-sale agreements, disclosure statements, subdivisions, stratification and land assemblies, plus commercial and industrial due diligence and bare trusts. The firm also handles tax-driven corporate reorganizations, succession planning and wealth preservation.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('johnston-franklin-bishop-nanaimo','Johnston Franklin Bishop','Nanaimo','BC','bc-island',0,4.5,23,49.1663559,-123.9402189,'{"name":"Johnston Franklin Bishop","city":"Nanaimo","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"bc-island","province":"BC","lat":49.1663559,"lng":-123.9402189,"address":"256 Wallace St #320, Nanaimo, BC V9R 5B3","phone":"+12507563823","rating":4.5,"count":23,"slug":"johnston-franklin-bishop-nanaimo","mapsUrl":"https://www.google.com/maps/search/Johnston+Franklin+Bishop+Nanaimo+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=256+Wallace+St+%23320%2C+Nanaimo%2C+BC+V9R+5B3","website":"https://www.jfblaw.ca","blurb":"General practice law firm in Nanaimo. Rated 4.5 from 23 Google reviews.","type":"logo","src":"images/logos/johnston-franklin-bishop-nanaimo.png","details":{"founded":1983,"lawyers":[{"name":"Marsha Bishop","title":"Partner"},{"name":"Greg Phillips"},{"name":"Blair Franklin"}],"areas":["Injury claims","Corporate and commercial","Wills and estates","Civil litigation"]}}',NULL,'Johnston Franklin Bishop is a Nanaimo law firm handling personal injury, civil litigation, real estate, wills and estates, and corporate matters. Locally owned and operated since 1983, when Richard Johnston founded Johnston and Company, the firm represents clients across Vancouver Island, including Parksville, Qualicum, Port Alberni, Courtenay, Comox, Campbell River and Duncan.

The partnership grew through Glen Lewis in 1985 and Blair Franklin in 1996, became Johnston Franklin Bishop when Marsha Bishop became a partner in 2014, and added Greg Phillips in 2017. Estate litigation covers disputes over the validity of wills and the distribution of assets, and the firm supports local groups such as the Nanaimo Curling Club.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('skyline-law-corporation-surrey','Skyline Law Corporation','Surrey','BC','bc-fraser',0,5,19,49.1375118,-122.8447385,'{"name":"Skyline Law Corporation","city":"Surrey","featured":false,"tags":["Family Law","Criminal Defence","Wills & Estates"],"caseTypes":["family","criminal","wills"],"region":"bc-fraser","province":"BC","lat":49.1375118,"lng":-122.8447385,"address":"7404 King George Blvd #200, Surrey, BC V3W 1N6","phone":"+16043370020","rating":5,"count":19,"slug":"skyline-law-corporation-surrey","mapsUrl":"https://www.google.com/maps/search/Skyline+Law+Corporation+Surrey+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7404+King+George+Blvd+%23200%2C+Surrey%2C+BC+V3W+1N6","website":"https://www.skylinelaw.ca","blurb":"Family Law / Criminal Defence in Surrey. Rated 5.0 from 19 Google reviews.","type":"logo","src":"images/logos/skyline-law-corporation-surrey.png","details":{"lawyers":[{"name":"Nav Randhawa","title":"Principal Lawyer and Founder"}],"areas":["Family law","Residential tenancy disputes","Separation and divorce","Criminal law","Estate planning"],"serving":["Surrey","Vancouver"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","14:00"]]}','Skyline Law Corporation is a Surrey firm handling family law, criminal defence, residential tenancy disputes, and wills and estates. Founder and principal lawyer Nav Randhawa leads the firm, which serves clients in Surrey, including Fleetwood and Guildford, and in Vancouver.

Family matters include separation, divorce, child custody disputes, and the division of property and debt. The firm also acts on criminal charges, landlord and tenant disputes and estate planning, negotiating out-of-court settlements where it can and pursuing litigation when needed.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('neil-brooks-law-corporation-victoria','Neil Brooks Law Corporation','Victoria','BC','bc-victoria',0,5,19,48.4229522,-123.3523188,'{"name":"Neil Brooks Law Corporation","city":"Victoria","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"bc-victoria","province":"BC","lat":48.4229522,"lng":-123.3523188,"address":"1141 Fort St, Victoria, BC V8V 3K9","phone":"+12506611893","rating":5,"count":19,"slug":"neil-brooks-law-corporation-victoria","mapsUrl":"https://www.google.com/maps/search/Neil+Brooks+Law+Corporation+Victoria+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1141+Fort+St%2C+Victoria%2C+BC+V8V+3K9","website":"https://neilbrookslaw.com","blurb":"Criminal Defence / Civil Litigation in Victoria. Rated 5.0 from 19 Google reviews.","type":"logo","src":"images/logos/neil-brooks-law-corporation-victoria.png","details":{"lawyers":[{"name":"Neil Brooks"}],"areas":["Charter applications","Criminal trials","Impaired driving","Drug offences","Assault and domestic violence","Sexual offences","Firearms and weapons offences","Bail","Sentencing and appeals","Criminal defence"],"serving":["British Columbia","Vancouver Island"]}}',NULL,'Neil Brooks Law Corporation is a Victoria criminal defence firm acting in Charter applications, trials, impaired driving and serious charges. One senior trial lawyer handles each file from intake to verdict, so the lawyer a client meets is the one who argues the case at every appearance.

Matters include drug offences, assault and domestic violence, sexual offences, firearms and weapons offences, bail, sentencing and appeals, before judge and jury and in Provincial Court and the Supreme Court of British Columbia. The practice serves clients across the province, including Victoria, Nanaimo and Duncan, and the lawyer''s earlier career ran from a commercial fishing deck to First Officer of Navigation on a large cruise ship.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('redpoint-law-llp-kelowna','Redpoint Law LLP','Kelowna','BC','bc-okanagan',0,5,19,49.886477,-119.494007,'{"name":"Redpoint Law LLP","city":"Kelowna","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"bc-okanagan","province":"BC","lat":49.886477,"lng":-119.494007,"address":"478 Bernard Ave #208, Kelowna, BC V1Y 6N7","phone":"+16047573032","rating":5,"count":19,"slug":"redpoint-law-llp-kelowna","mapsUrl":"https://www.google.com/maps/search/Redpoint+Law+LLP+Kelowna+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=478+Bernard+Ave+%23208%2C+Kelowna%2C+BC+V1Y+6N7","website":"https://redpointlaw.ca","blurb":"General practice law firm in Kelowna. Rated 5.0 from 19 Google reviews.","type":"logo","src":"images/logos/redpoint-law-llp-kelowna.png","details":{"founded":2021,"lawyers":[{"name":"Tim Lack"},{"name":"Falko Wong"},{"name":"Scott McInnes"},{"name":"Norman Chow"},{"name":"Jerry Shi"},{"name":"Robert Mazzarolo"},{"name":"Denis Walz"},{"name":"Gail Davies"},{"name":"Clement Lau"}],"areas":["Real estate","Corporate and commercial law","Wills and estates","Secured and commercial lending","Business law"]}}',NULL,'Redpoint Law LLP is a boutique Kelowna and Vancouver firm handling real estate, corporate and commercial law, and wills and estates. It has offices in downtown Kelowna on Bernard Avenue and in the Marine Building in Vancouver''s financial district, and serves clients throughout British Columbia.

Real estate work covers residential conveyances, commercial projects, development, commercial leasing, secured lending and financing, for individuals, corporations, landlords and tenants, developers, realtors, brokers and lenders. Estate services include planning, administration and probate.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('marc-sabourin-montreal','Marc Sabourin','Montreal','QC','qc-montreal',0,4.9,446,45.4329283,-73.6699999,'{"name":"Marc Sabourin","city":"Montreal","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"qc-montreal","province":"QC","lat":45.4329283,"lng":-73.6699999,"address":"68 7e Avenue, Lachine, QC H8S 2J4","phone":"+15146395611","rating":4.9,"count":446,"slug":"marc-sabourin-montreal","mapsUrl":"https://www.google.com/maps/search/Marc+Sabourin+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=68+7e+Avenue%2C+Lachine%2C+QC+H8S+2J4","website":"https://www.rupturequebec.com","blurb":"Family Law in Montreal. Rated 4.9 from 446 Google reviews.","type":"logo","src":"images/logos/marc-sabourin-montreal.png","details":{"areas":["Divorce"]}}',NULL,'Marc Sabourin handles uncontested joint divorces in Montreal for a fixed fee, with set packages for couples with or without dependent children. The practice operates as Rupture Québec from an office in Lachine.

In the all-inclusive package with a lawyer, both spouses attend a single meeting of one to two hours, in person or by videoconference, where documents are reviewed and the court papers are prepared, signed and sworn. The fee includes taxes and the 251 dollar court stamp fee for couples who qualify for subsidized mediation, and a do-it-yourself option is also offered. A joint procedure requires both spouses to agree, at least one of them to have lived in Quebec during the previous twelve months and, with exceptions, a separation of more than one year.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('banks-avocats-montreal','Banks Avocats','Montreal','QC','qc-montreal',0,5,172,45.5210885,-73.7103518,'{"name":"Banks Avocats","city":"Montreal","featured":false,"tags":["Business Law"],"caseTypes":["business"],"region":"qc-montreal","province":"QC","lat":45.5210885,"lng":-73.7103518,"address":"5255 Henri Bourassa Blvd W #425, Saint-Laurent, Quebec H4R 2M6","phone":"+15144480253","rating":5,"count":172,"slug":"banks-avocats-montreal","mapsUrl":"https://www.google.com/maps/search/Banks+Avocats+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5255+Henri+Bourassa+Blvd+W+%23425%2C+Saint-Laurent%2C+Quebec+H4R+2M6","website":"https://banksavocats.com","blurb":"Business Law in Montreal. Rated 5.0 from 172 Google reviews.","type":"logo","src":"images/logos/banks-avocats-montreal.png","details":{"areas":["Droit civil","Droit commercial","Incorporations","Rédaction de contrats"],"serving":["Québec"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','In Montreal, Banks Avocats handles corporate and commercial law, civil litigation, family law and immigration matters across Quebec. It is led by Maître Jade Banks and is based on Boulevard Henri-Bourassa Ouest in Saint-Laurent.

Its clients range from small start-ups to multinationals, and from individuals to businesses, in English and in French. Business services run from incorporation and contracts to compliance, while the civil law practice covers contract disputes and personal injury. Immigration work includes visa applications, asylum cases, family reunification and employment-based immigration. A guide to opening a business in Quebec is also published for new entrepreneurs.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('immigration-rh-avocats-inc-quebec-city','Immigration Rh Avocats Inc.','Quebec City','QC','qc-quebec',0,4.8,137,46.7942849,-71.2743902,'{"name":"Immigration Rh Avocats Inc.","city":"Quebec City","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-quebec","province":"QC","lat":46.7942849,"lng":-71.2743902,"address":"650 Rue Graham Bell #206, Québec City, Quebec G1N 4H5","phone":"+13673219063","rating":4.8,"count":137,"slug":"immigration-rh-avocats-inc-quebec-city","mapsUrl":"https://www.google.com/maps/search/Immigration+Rh+Avocats+Inc.+Quebec+City+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=650+Rue+Graham+Bell+%23206%2C+Qu%C3%A9bec+City%2C+Quebec+G1N+4H5","website":"https://immigrationrh.ca","blurb":"Immigration in Quebec City. Rated 4.8 from 137 Google reviews.","type":"logo","src":"images/logos/immigration-rh-avocats-inc-quebec-city.png","details":{"lawyers":[{"name":"Anouar Bouraoui","title":"Fondateur"}],"areas":["Immigration","Demande de visa","Permis de travail","Résidence permanente","Citoyenneté canadienne","Demande d''asile","Contrôle judiciaire","Recrutement international"],"serving":["Québec"]}}',NULL,'Visas, work permits, permanent residence, citizenship and refugee matters are the work of Immigration RH, a Quebec City firm.

The firm was founded and is led by Me Anouar Bouraoui, a member of the Barreau du Québec and a regulated immigration representative, and it acts for individuals, families and businesses. Its work covers visitor and transit visas, new and renewed closed or open work permits, the Quebec Selection Certificate (CSQ) and permanent residence, and citizenship applications through to the oath. It represents clients before the Immigration and Refugee Board, assists with asylum applications and applications to challenge decisions at the Federal Court, and helps businesses with international recruitment from its office on rue Graham-Bell.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('georgia-pappis-montreal','Georgia Pappis','Montreal','QC','qc-montreal',0,5,98,45.4965005,-73.6775781,'{"name":"Georgia Pappis","city":"Montreal","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"qc-montreal","province":"QC","lat":45.4965005,"lng":-73.6775781,"address":"100 Boul Alexis-Nihon #950, Saint-Laurent, Quebec H4M 2N6","phone":"+15144393838","rating":5,"count":98,"slug":"georgia-pappis-montreal","mapsUrl":"https://www.google.com/maps/search/Georgia+Pappis+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=100+Boul+Alexis-Nihon+%23950%2C+Saint-Laurent%2C+Quebec+H4M+2N6","website":"https://georgiapappis.com","blurb":"General practice law firm in Montreal. Rated 5.0 from 98 Google reviews.","type":"logo","src":"images/logos/georgia-pappis-montreal.jpg","details":{"lawyers":[{"name":"Georgia Pappis","title":"Barrister & Solicitor"}],"areas":["Immigration"],"serving":["Montreal"]}}',NULL,'Montreal immigration lawyer Georgia Pappis handles Express Entry, family sponsorship, work and study permits and citizenship applications.

She has been a barrister and solicitor since 2004, is a member of the Quebec Bar and belongs to the Association of Quebec Immigration Lawyers (AQAADI). Her practice has been exclusively immigration law for more than 20 years. Matters include Quebec Skilled Workers, the Quebec Experience Program (PEQ), visitor visas, permanent resident card renewals, humanitarian and compassionate applications, criminal rehabilitation and record suspensions, along with advice on criminal matters that can affect immigration status. She works in English, French and Greek from an office on Boulevard Alexis-Nihon in Saint-Laurent.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ols-avocats-en-droit-du-travail-labour-and-employment-lawyers-montreal','OLS Avocats en droit du travail/Labour and Employment Lawyers','Montreal','QC','qc-montreal',0,4.7,87,45.5011826,-73.5748045,'{"name":"OLS Avocats en droit du travail/Labour and Employment Lawyers","city":"Montreal","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"qc-montreal","province":"QC","lat":45.5011826,"lng":-73.5748045,"address":"2015 Rue Peel Ste 950, Montreal, Quebec H3A 1T8","phone":"+15147006753","rating":4.7,"count":87,"slug":"ols-avocats-en-droit-du-travail-labour-and-employment-lawyers-montreal","mapsUrl":"https://www.google.com/maps/search/OLS+Avocats+en+droit+du+travail%2FLabour+and+Employment+Lawyers+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2015+Rue+Peel+Ste+950%2C+Montreal%2C+Quebec+H3A+1T8","website":"https://olsquebec.com","blurb":"Employment Law in Montreal. Rated 4.7 from 87 Google reviews.","type":"logo","src":"images/logos/ols-avocats-en-droit-du-travail-labour-and-employment-lawyers-montreal.png","details":{"lawyers":[{"name":"Susan Orenstein Little"},{"name":"Niall O’Kelley"}],"areas":["Labour and employment law","Collective agreements","Constructive dismissal","Severance negotiations","Executive dismissals"],"serving":["Montreal"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Executives, professionals and employers facing dismissal or severance are advised by OLS, a Montreal labour and employment law firm.

The boutique practice has worked in this field for more than 75 years. Its files include executive terminations, wrongful and constructive dismissal, severance negotiations, psychological harassment, age discrimination and CNESST matters, before the Administrative Labour Tribunal and the courts. It acts for employees and employers, unionized or not. Beyond Montreal, the firm serves Laval, Longueuil, Sherbrooke, Lévis, Gatineau, Trois-Rivières and Terrebonne.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('cantin-boulianne-avocats-saguenay','Cantin Boulianne Avocats','Saguenay','QC','qc-saguenay-bsl',0,4.8,77,48.4105324,-71.2562807,'{"name":"Cantin Boulianne Avocats","city":"Saguenay","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"qc-saguenay-bsl","province":"QC","lat":48.4105324,"lng":-71.2562807,"address":"2456 Rue Saint-Dominique, Jonquière, QC G7X 6K3","phone":"+14185428111","rating":4.8,"count":77,"slug":"cantin-boulianne-avocats-saguenay","mapsUrl":"https://www.google.com/maps/search/Cantin+Boulianne+Avocats+Saguenay+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2456+Rue+Saint-Dominique%2C+Jonqui%C3%A8re%2C+QC+G7X+6K3","website":"https://www.cantinboulianne.com","blurb":"General practice law firm in Saguenay. Rated 4.8 from 77 Google reviews.","type":"logo","src":"images/logos/cantin-boulianne-avocats-saguenay.jpg","details":{"founded":1993,"lawyers":[{"name":"Julien Boulianne"},{"name":"Sylvain Morissette"},{"name":"Charles Cantin"}],"areas":["Droit criminel","Droit pénal"]}}',NULL,'Based in Jonquière and founded in 1993, Cantin Boulianne Avocats is a criminal and penal law firm serving Saguenay.

Three lawyers, Charles Cantin, Julien Boulianne and Sylvain Morissette, act for clients in the Saguenay–Lac-Saint-Jean region and elsewhere in Quebec, supported by a team of support staff. The firm has represented people in criminal and penal matters for more than 30 years and works with rigour and discretion on each file. Its office is on rue Saint-Dominique in Jonquière.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('eli-bloom-avocat-montreal','ELI BLOOM Avocat','Montreal','QC','qc-montreal',0,4.9,69,45.4983507,-73.6479939,'{"name":"ELI BLOOM Avocat","city":"Montreal","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"qc-montreal","province":"QC","lat":45.4983507,"lng":-73.6479939,"address":"4810 Rue Jean-Talon O, Montréal, QC H4P 1W7","phone":"+14388348633","rating":4.9,"count":69,"slug":"eli-bloom-avocat-montreal","mapsUrl":"https://www.google.com/maps/search/ELI+BLOOM+Avocat+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=4810+Rue+Jean-Talon+O%2C+Montr%C3%A9al%2C+QC+H4P+1W7","website":"https://elibloom.ca","blurb":"General practice law firm in Montreal. Rated 4.9 from 69 Google reviews.","type":"logo","src":"images/logos/eli-bloom-avocat-montreal.webp"}',NULL,'ELI BLOOM Avocat is a general practice law office in Montreal, Quebec. The office is located at 4810 Rue Jean-Talon Ouest, Montreal, QC H4P 1W7. The firm''s practice is recorded as general practice, and no further details about its lawyers, particular areas of law or languages of service are on record.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('chakib-benhadji-serradj-montreal','Chakib Benhadji Serradj','Montreal','QC','qc-montreal',0,4.8,69,45.5013559,-73.5698619,'{"name":"Chakib Benhadji Serradj","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.5013559,"lng":-73.5698619,"address":"3 Pl. Ville-Marie Ste 400, Montreal, Quebec H3B 2E3","phone":"+15142918888","rating":4.8,"count":69,"slug":"chakib-benhadji-serradj-montreal","mapsUrl":"https://www.google.com/maps/search/Chakib+Benhadji+Serradj+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=3+Pl.+Ville-Marie+Ste+400%2C+Montreal%2C+Quebec+H3B+2E3","website":"https://cblegal.ca","blurb":"Immigration in Montreal. Rated 4.8 from 69 Google reviews.","type":"logo","src":"images/logos/chakib-benhadji-serradj-montreal.png","heroImage":"images/hero/chakib-benhadji-serradj-montreal.webp","details":{"areas":["Immigration","Résidence permanente","Visa touriste","Permis de travail","Réunification familiale","Citoyenneté","Permis d''étude","Statut de réfugié","Examen des risques avant renvoi"],"serving":["Montreal"]}}',NULL,'Through CB Legal in Montreal, Chakib Benhadji Serradj practises immigration law covering visitor visas, Express Entry, Quebec programs and permanent residence.

Services include electronic travel authorizations, tourist and business visas and the super visa for parents and grandparents, as well as the Provincial Nominee Programs, the Quebec Experience Program (PEQ) and the regular Quebec skilled worker program. Business immigration for investors, entrepreneurs and self-employed workers is covered, together with permanent resident card renewals, travel documents, study in Canada, citizenship and challenges before the Federal Court. Clients can obtain legal advice, a revision of an existing file or full management of an immigration file, with appointments held remotely from an office at Place Ville-Marie.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('tlm-avocat-divorce-montreal','TLM Avocat Divorce','Montreal','QC','qc-montreal',0,4.7,59,45.5308517,-73.5625504,'{"name":"TLM Avocat Divorce","city":"Montreal","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"qc-montreal","province":"QC","lat":45.5308517,"lng":-73.5625504,"address":"2120 R. Sherbrooke E Ste 1010, Montréal, QC H2K 1C3","phone":"+15143036889","rating":4.7,"count":59,"slug":"tlm-avocat-divorce-montreal","mapsUrl":"https://www.google.com/maps/search/TLM+Avocat+Divorce+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2120+R.+Sherbrooke+E+Ste+1010%2C+Montr%C3%A9al%2C+QC+H2K+1C3","website":"https://www.tlm-avocats.com","blurb":"Family Law in Montreal. Rated 4.7 from 59 Google reviews.","type":"logo","src":"images/logos/tlm-avocat-divorce-montreal.jpg","details":{"areas":["Droit familial","Droit civil","Droit des personnes","Divorce","Pension alimentaire","Garde d''enfants","Mise en demeure"],"serving":["Montréal"]}}',NULL,'Divorce, child custody, child support and mediation are the focus of TLM Avocat Divorce, a Montreal family law firm with fixed-price packages.

Operating as TLM Avocats, the team of family lawyers also covers civil law and the law of persons, and assists with small claims proceedings. Packages exist for uncontested divorce without children and for joint custody and child support procedures, and the child support calculation is included. Payment arrangements can be set up, and payment is accepted by cheque, Interac, MasterCard, Visa or cash. The office is on Rue Sherbrooke Est in Montreal.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('twin-lisbet-avocats-and-fiscalistes-montreal','Twin Lisbet Avocats & Fiscalistes','Montreal','QC','qc-montreal',0,5,50,45.5049476,-73.5556983,'{"name":"Twin Lisbet Avocats & Fiscalistes","city":"Montreal","featured":false,"tags":["Business Law"],"caseTypes":["business"],"region":"qc-montreal","province":"QC","lat":45.5049476,"lng":-73.5556983,"address":"79 Rue de Brésoles, Montréal, QC H2Y 1V7","phone":"+15149936920","rating":5,"count":50,"slug":"twin-lisbet-avocats-and-fiscalistes-montreal","mapsUrl":"https://www.google.com/maps/search/Twin+Lisbet+Avocats+%26+Fiscalistes+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=79+Rue+de+Br%C3%A9soles%2C+Montr%C3%A9al%2C+QC+H2Y+1V7","website":"https://www.twinlisbet.com","blurb":"Business Law in Montreal. Rated 5.0 from 50 Google reviews.","type":"logo","src":"images/logos/twin-lisbet-avocats-and-fiscalistes-montreal.png","heroImage":"images/hero/twin-lisbet-avocats-and-fiscalistes-montreal.webp","details":{"lawyers":[{"name":"Claudia Di Iorio"}],"areas":["Droit des affaires","Litige fiscal","Acquisition et fusion d''entreprise","Planification fiscale","Planification successorale","Litige commercial et civil","Marque de commerce","Droit immobilier","Propriété intellectuelle","Droit corporatif"],"serving":["Montréal","Bromont"]}}','{"1":[["07:30","22:00"]],"2":[["07:30","22:00"]],"3":[["07:30","22:00"]],"4":[["07:30","22:00"]],"5":[["07:30","22:00"]],"6":[["07:30","22:00"]],"7":[["07:30","22:00"]]}','Twin Lisbet Avocats & Fiscalistes is a Montreal firm practising tax litigation, tax and estate planning and business law.

On the tax side, the firm handles objections to notices of assessment, negotiation with Revenu Québec and the Canada Revenue Agency, and representation from tax audit through to litigation. Business work includes purchases and mergers of companies, commercial and civil litigation, regulatory compliance, international contracts and cross-border disputes, trademarks, patents and real estate law. Estate planning covers wills, mandates in case of incapacity, trusts, life insurance and the liquidation of estates, including business succession and blended families.','dynamic','live',NULL);
