INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('m-i-b-avocat-inc-laval','M.I.B Avocat Inc.','Laval','QC','qc-laval-laurentides',0,5,11,45.5518773,-73.7607136,'{"name":"M.I.B Avocat Inc.","city":"Laval","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"qc-laval-laurentides","province":"QC","lat":45.5518773,"lng":-73.7607136,"address":"3933 Blvd. Saint-Martin O #103, Laval, Quebec H7T 2P7","phone":"+15146046064","rating":5,"count":11,"slug":"m-i-b-avocat-inc-laval","mapsUrl":"https://www.google.com/maps/search/M.I.B+Avocat+Inc.+Laval+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=3933+Blvd.+Saint-Martin+O+%23103%2C+Laval%2C+Quebec+H7T+2P7","website":"https://www.mibavocat.com","blurb":"General practice law firm in Laval. Rated 5.0 from 11 Google reviews.","type":"logo","src":"images/logos/m-i-b-avocat-inc-laval.png"}',NULL,'With an office in Laval, MIB Avocat handles immigration applications and criminal defence for clients in the Montreal area.

Immigration services cover visitors, foreign students, temporary workers, permanent residence, sponsorship and Canadian citizenship, while criminal law work includes release hearings and the defence of criminal charges and court summonses. Lawyers and staff communicate in French, English and Arabic. The firm''s values are respect, transparency, open-mindedness, discretion, perseverance and excellence, and its office is on Boulevard Saint-Martin Ouest.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('melanie-lord-gatineau','Mélanie Lord','Gatineau','QC','qc-outaouais',0,4.8,11,45.426325,-75.7182678,'{"name":"Mélanie Lord","city":"Gatineau","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"qc-outaouais","province":"QC","lat":45.426325,"lng":-75.7182678,"address":"137 Rue Wellington, Gatineau, QC J8X 2J1","phone":"+18197755000","rating":4.8,"count":11,"slug":"melanie-lord-gatineau","mapsUrl":"https://www.google.com/maps/search/M%C3%A9lanie+Lord+Gatineau+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=137+Rue+Wellington%2C+Gatineau%2C+QC+J8X+2J1","website":"https://lafleurandassociates.weebly.com","blurb":"Criminal Defence in Gatineau. Rated 4.8 from 11 Google reviews.","type":"logo","src":"images/logos/melanie-lord-gatineau.png","details":{"lawyers":[{"name":"Michael J. Houle","title":"Counsel"}],"serving":["Ontario","Nunavut"]}}',NULL,'Mélanie Lord is a criminal and penal defence lawyer in Gatineau, Quebec, listed under criminal defence. The practice is associated with Lafleur & associés, which provides criminal and penal law services in the Ottawa and Gatineau region. The office address is 137 Rue Wellington, Gatineau, QC J8X 2J1, and no further details about its team or languages of service are on record.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('gbv-avocats-quebec-city','GBV Avocats','Quebec City','QC','qc-quebec',0,4.6,11,46.7659358,-71.2927334,'{"name":"GBV Avocats","city":"Quebec City","featured":false,"tags":["Civil Litigation","Business Law"],"caseTypes":["litigation","business"],"region":"qc-quebec","province":"QC","lat":46.7659358,"lng":-71.2927334,"address":"#500, 2960 Boul Laurier, Québec, QC G1V 4S1","phone":"+14186561313","rating":4.6,"count":11,"slug":"gbv-avocats-quebec-city","mapsUrl":"https://www.google.com/maps/search/GBV+Avocats+Quebec+City+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=%23500%2C+2960+Boul+Laurier%2C+Qu%C3%A9bec%2C+QC+G1V+4S1","website":"https://www.gbvavocats.com","blurb":"Civil Litigation / Business Law in Quebec City. Rated 4.6 from 11 Google reviews.","type":"logo","src":"images/logos/gbv-avocats-quebec-city.png","heroImage":"images/hero/gbv-avocats-quebec-city.webp","details":{"founded":1998,"serving":["Sherbrooke"]}}',NULL,'Since 1998, GBV Avocats has practised in Quebec City, covering civil and commercial litigation, corporate and banking law.

The firm has offices in Quebec City, Lévis, Trois-Rivières, Montreal and Sherbrooke, and acts for individuals, small, medium and large companies, insurance companies and financial and banking institutions. Practice areas include real estate, environment, energy and natural resources, family and estates, administrative, municipal and constitutional law, access to information, mergers and acquisitions, labour and employment, and public law. Its philosophy rests on intensity, rigour and humility.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('steven-slimovitch-montreal','Steven Slimovitch','Montreal','QC','qc-montreal',0,4.6,11,45.5044875,-73.5576762,'{"name":"Steven Slimovitch","city":"Montreal","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"qc-montreal","province":"QC","lat":45.5044875,"lng":-73.5576762,"address":"le 500 Place-d''Armes, 500 Pl. d''Armes, Montréal, QC H2Y 2W3","phone":"+15149464030","rating":4.6,"count":11,"slug":"steven-slimovitch-montreal","mapsUrl":"https://www.google.com/maps/search/Steven+Slimovitch+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=le+500+Place-d%27Armes%2C+500+Pl.+d%27Armes%2C+Montr%C3%A9al%2C+QC+H2Y+2W3","website":"https://montrealcriminallaw.com","blurb":"Criminal Defence / Civil Litigation in Montreal. Rated 4.6 from 11 Google reviews.","type":"logo","src":"images/logos/steven-slimovitch-montreal.png","details":{"lawyers":[{"name":"Steven Slimovitch"}],"areas":["Criminal defence","Assault","Drug offences","Extradition","Disciplinary law","Firearms","Theft and shoplifting","Young offenders","Driving offences","Immigration offences"],"serving":["Montreal","Quebec","New Brunswick","Ontario","Saskatchewan"]}}','{"1":[["00:00","23:59"]],"2":[["00:00","23:59"]],"3":[["00:00","23:59"]],"4":[["00:00","23:59"]],"5":[["00:00","23:59"]],"6":[["00:00","23:59"]],"7":[["00:00","23:59"]]}','Steven Slimovitch is a bilingual criminal defence lawyer in Montreal who has been in private practice since 1991.

He defends people under investigation or charged under the Criminal Code, the Controlled Drugs and Substances Act, the Income Tax Act and the Quebec Highway Safety Act, and acts in penal and Charter of Rights litigation for individuals and corporations. He has appeared at all levels of court, including the Supreme Court of Canada, in matters concerning freedom of religion and the validity of certain search warrants. His office is in the Old Port of Montreal, and he also represents clients elsewhere in Quebec and in provinces including New Brunswick, Ontario and Saskatchewan.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('krk-law-corporation-winnipeg','KRK Law Corporation','Winnipeg','MB','mb-winnipeg',0,5,58,49.8354143,-97.1509159,'{"name":"KRK Law Corporation","city":"Winnipeg","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"mb-winnipeg","province":"MB","lat":49.8354143,"lng":-97.1509159,"address":"1483 Pembina Hwy #103, Winnipeg, MB R3T 2C6","phone":"+12042213011","rating":5,"count":58,"slug":"krk-law-corporation-winnipeg","mapsUrl":"https://www.google.com/maps/search/KRK+Law+Corporation+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1483+Pembina+Hwy+%23103%2C+Winnipeg%2C+MB+R3T+2C6","website":"https://krklaw.ca","blurb":"Immigration in Winnipeg. Rated 5.0 from 58 Google reviews.","type":"logo","src":"images/logos/krk-law-corporation-winnipeg.png","details":{"areas":["Family law","Refugee claims","Immigration","Real estate","Wills & Estate"]}}',NULL,'In Winnipeg, KRK Law Corporation handles immigration and refugee matters, family law, real estate, wills and estates, and corporate law.

Kasun, the managing partner, was admitted to the Manitoba bar in 2022. He earned his law degree at Sri Lanka Law College in 2009, practised in Sri Lanka for four years, and received his Certificate of Qualification from the Federation of Law Societies of Canada in 2020. Family law work covers divorce, child custody, child support and spousal support, and real estate work covers residential and commercial purchases and sales, leases and commercial contracts. Legal assistant Srima Jayakody is a former lawyer in Sri Lanka with more than eight years of experience.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('threshold-law-winnipeg','Threshold Law','Winnipeg','MB','mb-winnipeg',0,4.6,56,49.8948389,-97.1409921,'{"name":"Threshold Law","city":"Winnipeg","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"mb-winnipeg","province":"MB","lat":49.8948389,"lng":-97.1409921,"address":"233 Portage Ave Ste 201, Winnipeg, MB R3B 2A7","phone":"+12049562336","rating":4.6,"count":56,"slug":"threshold-law-winnipeg","mapsUrl":"https://www.google.com/maps/search/Threshold+Law+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=233+Portage+Ave+Ste+201%2C+Winnipeg%2C+MB+R3B+2A7","website":"https://thresholdlaw.ca","blurb":"Immigration in Winnipeg. Rated 4.6 from 56 Google reviews.","type":"logo","src":"images/logos/threshold-law-winnipeg.png","details":{"lawyers":[{"name":"David H. Davis"}],"areas":["Immigration","Cybersecurity and privacy","LMIA applications","Work permits","Temporary Resident Permits","Criminal inadmissibility waivers","Federal Court judicial review","Pre-removal risk assessments","US work visas","Business investment"]}}',NULL,'Threshold Law, a Winnipeg firm, advises employers, investors and organizations on immigration, business investment and cybersecurity and privacy.

Principal lawyer David H. Davis was called to the Manitoba bar in 1989 and has served clients across all ten provinces and three territories since 1997. Immigration work covers healthcare recruitment, employer pathways, worker sourcing, entertainer inadmissibility waivers, appeals and cross-border coordination with US-licensed attorneys. For foreign investors, the firm sources established Canadian businesses and guides them through Provincial Nominee Programs. Cybersecurity work covers breach notification, regulatory communications and privacy compliance, including PHIA, PIPEDA and OCAP-aligned data governance.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ratuski-law-office-winnipeg','Ratuski Law Office','Winnipeg','MB','mb-winnipeg',0,4.8,26,49.9599948,-97.0676668,'{"name":"Ratuski Law Office","city":"Winnipeg","featured":false,"tags":["Real Estate","Wills & Estates","Business Law"],"caseTypes":["realestate","wills","business"],"region":"mb-winnipeg","province":"MB","lat":49.9599948,"lng":-97.0676668,"address":"2131 Henderson Hwy, Winnipeg, MB R2G 1P8","phone":"+12043344994","rating":4.8,"count":26,"slug":"ratuski-law-office-winnipeg","mapsUrl":"https://www.google.com/maps/search/Ratuski+Law+Office+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2131+Henderson+Hwy%2C+Winnipeg%2C+MB+R2G+1P8","website":"https://www.ratuskilaw.com","blurb":"Real Estate / Wills & Estates in Winnipeg. Rated 4.8 from 26 Google reviews.","type":"logo","src":"images/logos/ratuski-law-office-winnipeg.png","details":{"areas":["Wills","Estates","Real estate","Corporate law"],"serving":["Winnipeg","Manitoba"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Founded in 1989 in North Kildonan, Ratuski Law Office handles wills, estates, incorporations and real estate in Winnipeg.

Arlene S. Ratuski started the practice, and her daughter Alexandra C. Dueck-Dunsford joined it in 2009. Services include wills, powers of attorney and health care directives, winding up the estate of a deceased person, preparing Articles of Incorporation and minute books for businesses, and real estate transactions in Manitoba such as buying a first home, building, purchasing a cottage, selling a condominium and refinancing. The office is on Henderson Highway.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ginakes-law-office-winnipeg','Ginakes Law Office','Winnipeg','MB','mb-winnipeg',0,4.6,24,49.9394987,-97.1160191,'{"name":"Ginakes Law Office","city":"Winnipeg","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"mb-winnipeg","province":"MB","lat":49.9394987,"lng":-97.1160191,"address":"1850 Main St #2, Winnipeg, MB R2V 3J4","phone":"+12049420396","rating":4.6,"count":24,"slug":"ginakes-law-office-winnipeg","mapsUrl":"https://www.google.com/maps/search/Ginakes+Law+Office+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1850+Main+St+%232%2C+Winnipeg%2C+MB+R2V+3J4","website":"https://www.dbglawyers.com","blurb":"General practice law firm in Winnipeg. Rated 4.6 from 24 Google reviews.","type":"logo","src":"images/logos/ginakes-law-office-winnipeg.jpg","details":{"lawyers":[{"name":"Peter Ginakes"}],"areas":["Lifetime and estate planning","Estate administration","Residential and commercial real estate","Notarial services","Corporate law"],"serving":["Winnipeg"]}}',NULL,'In Winnipeg, Ginakes Law Office brings together independent lawyers in estate planning, real estate, notarial services and corporate law.

The firm practises under the name Dobrowolski, Boonov & Ginakes, Barristers & Solicitors. Services include lifetime and estate planning, probate and estate administration, residential and commercial real estate, business and corporate law for companies from start-ups to large family-run businesses, and notarial services, since all of its lawyers are authorized by the Manitoba government to act as notaries. The firm moved in 2022 into an office it owns on Main Street.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('hook-and-smith-winnipeg','Hook & Smith','Winnipeg','MB','mb-winnipeg',0,4.5,34,49.8797557,-97.2831354,'{"name":"Hook & Smith","city":"Winnipeg","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"mb-winnipeg","province":"MB","lat":49.8797557,"lng":-97.2831354,"address":"3070 Portage Ave, Winnipeg, MB R3K 0Y2","phone":"+12048854520","rating":4.5,"count":34,"slug":"hook-and-smith-winnipeg","mapsUrl":"https://www.google.com/maps/search/Hook+%26+Smith+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=3070+Portage+Ave%2C+Winnipeg%2C+MB+R3K+0Y2","website":"https://hookandsmith.com","blurb":"Real Estate in Winnipeg. Rated 4.5 from 34 Google reviews.","type":"logo","src":"images/logos/hook-and-smith-winnipeg.jpg","details":{"lawyers":[{"name":"Dennis A. Smith"},{"name":"Winston F. Smith"},{"name":"Geoffrey B. Toews"},{"name":"Thomas W. Turner"}],"areas":["Wills, trust, and estates law","Commercial real estate law","Residential real estate law"],"serving":["Winnipeg"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Established in 1984, Hook & Smith is a Winnipeg firm practising corporate and commercial law, real estate, wills and estates, and transportation law.

Dennis A. Smith and Gordon P. Hook founded the firm, which acts mainly for small and medium-sized businesses and not-for-profit organizations, and for individuals and families. Real estate work includes condominiums, industrial buildings, apartment blocks and hotels. Transportation law concerns railway regulation, federal and provincial, including discontinuance and sale of rail lines, and construction and infrastructure law ranges from home building contracts to major projects with government or corporate bodies. Its lawyers serve Winnipeg, Portage la Prairie and Steinbach from an office on Portage Avenue.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('sullivan-law-winnipeg','Sullivan Law','Winnipeg','MB','mb-winnipeg',0,4.5,31,49.8619804,-97.109577,'{"name":"Sullivan Law","city":"Winnipeg","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"mb-winnipeg","province":"MB","lat":49.8619804,"lng":-97.109577,"address":"66 St Anne''s Rd, Winnipeg, MB R2M 2Y5","phone":"+12042336246","rating":4.5,"count":31,"slug":"sullivan-law-winnipeg","mapsUrl":"https://www.google.com/maps/search/Sullivan+Law+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=66+St+Anne%27s+Rd%2C+Winnipeg%2C+MB+R2M+2Y5","website":"https://sullivanlawoffice.ca","blurb":"Real Estate in Winnipeg. Rated 4.5 from 31 Google reviews.","type":"logo","src":"images/logos/sullivan-law-winnipeg.png","details":{"lawyers":[{"name":"John Sullivan"}],"areas":["Business law","Real estate","Wills & Estates","Notary public"],"serving":["Winnipeg","Manitoba"]}}',NULL,'Business law and real estate are the primary practice areas of Sullivan Law, a boutique Winnipeg firm that also handles wills, estates and notary services.

The firm was re-established by John Sullivan and acts for individuals, entrepreneurs, businesses and organizations on matters of Manitoba law, including clients outside the province. Business work includes incorporations, among them medical corporations, contracts, share and asset acquisitions and sales, financings and reorganizations. Real estate work covers residential purchases and sales, commercial property, leasing, financings and development. Flat fees apply in certain areas, and the office is in the St. Vital area of south Winnipeg, on St Anne''s Road.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kmmg-law-winnipeg','KMMG Law','Winnipeg','MB','mb-winnipeg',0,4.5,25,49.9033081,-97.0952121,'{"name":"KMMG Law","city":"Winnipeg","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"mb-winnipeg","province":"MB","lat":49.9033081,"lng":-97.0952121,"address":"625 Nairn Ave, Winnipeg, MB R2L 0X4","phone":"+12049871227","rating":4.5,"count":25,"slug":"kmmg-law-winnipeg","mapsUrl":"https://www.google.com/maps/search/KMMG+Law+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=625+Nairn+Ave%2C+Winnipeg%2C+MB+R2L+0X4","website":"https://kmmglaw.ca","blurb":"General practice law firm in Winnipeg. Rated 4.5 from 25 Google reviews.","type":"logo","src":"images/logos/kmmg-law-winnipeg.png","heroImage":"images/hero/kmmg-law-winnipeg.webp","details":{"lawyers":[{"name":"Daniel Minuk","title":"Managing Partner"},{"name":"Merissa Mundey","title":"Associate"},{"name":"Shaylan Cottick","title":"Associate"},{"name":"Renée Nichols","title":"Lawyer"}],"areas":["Family law","Real estate","Wills","Collaborative family law","Mediation","Arbitration","Cohabitation agreements","Pre-nuptial agreements","Adoption","Guardianship"],"serving":["Elmwood","East Kildonan"]}}',NULL,'KMMG Law is a Winnipeg firm serving Elmwood and East Kildonan with family law, collaborative divorce, real estate and estate work.

The firm, also known as Kelekis Minuk MicFlikier Green, has been present in the area for more than 30 years and has three lawyers. Managing partner Daniel Minuk was called to the bar in 2009, focuses on family law and is certified in family law mediation and arbitration. Associates Merissa Mundey and Shaylan Cottick and lawyer, mediator and collaborative practitioner Renée Nichols complete the team. Collaborative divorce and separation is offered as an alternative to litigation, and the office is on Nairn Avenue.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('samphir-law-office-winnipeg','Samphir Law Office','Winnipeg','MB','mb-winnipeg',0,4.8,19,49.8829039,-97.1883291,'{"name":"Samphir Law Office","city":"Winnipeg","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"mb-winnipeg","province":"MB","lat":49.8829039,"lng":-97.1883291,"address":"1311 Portage Ave L01, Winnipeg, MB R3G 0V3","phone":"+12045000775","rating":4.8,"count":19,"slug":"samphir-law-office-winnipeg","mapsUrl":"https://www.google.com/maps/search/Samphir+Law+Office+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1311+Portage+Ave+L01%2C+Winnipeg%2C+MB+R3G+0V3","website":"https://samphirlaw.com","blurb":"Real Estate in Winnipeg. Rated 4.8 from 19 Google reviews.","type":"logo","src":"images/logos/samphir-law-office-winnipeg.png","details":{"areas":["Real estate","Wills & estates","Immigration law","Business law","Notary services"],"serving":["Manitoba","Ontario","Winnipeg"]}}',NULL,'In Winnipeg, Samphir Law Office handles real estate, wills and estates, small business and immigration law for clients in Manitoba and Ontario.

In operation for more than 25 years, the firm acts for sellers, purchasers, investors and developers in residential and commercial real estate, including Winnipeg homes and cottages in the Lake of the Woods area. Wills and estates work covers wills, powers of attorney, probate applications and executor services, with a focus on inter-provincial estates. Small business services include incorporation, contracts and licensing, and immigration services cover permanent and temporary residence, including complex cases and refusals. Notary and commissioner for oaths services are available by appointment or in an emergency.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lyon-stern-immigration-law-winnipeg','LYON STERN IMMIGRATION LAW','Winnipeg','MB','mb-winnipeg',0,5,10,49.8957492,-97.1392686,'{"name":"LYON STERN IMMIGRATION LAW","city":"Winnipeg","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"mb-winnipeg","province":"MB","lat":49.8957492,"lng":-97.1392686,"address":"201 Portage Ave Suite 1800, Winnipeg, MB R3B 3K6","phone":"+12044008024","rating":5,"count":10,"slug":"lyon-stern-immigration-law-winnipeg","mapsUrl":"https://www.google.com/maps/search/LYON+STERN+IMMIGRATION+LAW+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=201+Portage+Ave+Suite+1800%2C+Winnipeg%2C+MB+R3B+3K6","website":"https://lyonstern.com","blurb":"Immigration in Winnipeg. Rated 5.0 from 10 Google reviews.","type":"logo","src":"images/logos/lyon-stern-immigration-law-winnipeg.webp","details":{"areas":["Express Entry","Provincial Nominee Program","Family sponsorship","Study permits","Work permits","Temporary residence","LMIA & International Mobility Programs","Refusals and appeals"]}}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Permanent residence, work and study permits, sponsorship and business immigration are covered by Lyon Stern Immigration Law, a full-service Winnipeg firm.

The firm, also known as Lyon Stern Partners, works through a global network of lawyers, consultants and other immigration professionals and acts for individuals, families and businesses. Services include Provincial Nominee Programs, inter-company transfers, visitor applications, immigration services for Canadian businesses and citizenship. It offers a single access point for all immigration services, and its lawyers prepare strategies for dealings with Immigration, Refugees and Citizenship Canada. The office is on Portage Avenue.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('holloway-thliveris-winnipeg','Holloway Thliveris','Winnipeg','MB','mb-winnipeg',0,4.6,10,49.8872879,-97.143497,'{"name":"Holloway Thliveris","city":"Winnipeg","featured":false,"tags":["Civil Litigation","Business Law"],"caseTypes":["litigation","business"],"region":"mb-winnipeg","province":"MB","lat":49.8872879,"lng":-97.143497,"address":"363 Broadway #1430, Winnipeg, MB R3C 3N9","phone":"+12042891523","rating":4.6,"count":10,"slug":"holloway-thliveris-winnipeg","mapsUrl":"https://www.google.com/maps/search/Holloway+Thliveris+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=363+Broadway+%231430%2C+Winnipeg%2C+MB+R3C+3N9","website":"https://htlaw.ca","blurb":"Civil Litigation / Business Law in Winnipeg. Rated 4.6 from 10 Google reviews.","type":"logo","src":"images/logos/holloway-thliveris-winnipeg.png","details":{"areas":["Construction law","Commercial litigation"],"serving":["Winnipeg"]}}',NULL,'In Winnipeg, Holloway Thliveris LLP practises only construction law and commercial litigation.

Ivan Holloway and Stephan Thliveris have more than 30 years of combined civil litigation and appellate experience in Manitoba, British Columbia, Alberta, Saskatchewan and Ontario. The firm handles trials and appeals in provincial superior courts and federal court, and applications for leave to the Supreme Court of Canada. Ivan Holloway, a University of Manitoba law graduate of 2002, previously chaired a construction law practice group at a large Winnipeg firm and has argued before the Courts of Appeal of Saskatchewan, Manitoba and Ontario and the Federal Court of Appeal. Matters include workplace health and safety issues in construction and disputes over real and personal property.','dynamic','live',NULL);
